pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item fills the bin exactly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: strongly reward when the next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more slack: mild reward scaled by tightness.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize proportionally to wasted potential.
            let unusable = (next_item_size - post_residual) as f64;
            score += 60.0 * (unusable / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is below the mean (tight bins absorb items well).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize creating small dead spaces (< 10, unusable for typical items) unless exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild preference for filling existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    } else {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are heavily penalized (non-linearly).
    let dead_zone = 25.0;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 0.9;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 35.0;
    }

    // Tight-fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * fill_ratio * 20.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + progress * 2.0);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: bonus if leftover can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leftover that is just barely below the next item (awkward gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Mean-residual coupling: bins deviating far below mean residual are
    // good candidates to be emptied first.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32 as f64 * 80.0
            + open_bins_count as f64 * -1.0
            + mean_residual * 0.3;
        score = 100.0 - pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item are toxic.
    // Items in [1,100]; treat residual < 10 as unusable dead space (min item size fallback).
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // Heavily penalize creating unusable slivers.
        score += (dead_threshold - pr) * 6.0;
    }

    // Nonlinear waste curve: quadratic blowup on medium dead gaps.
    let waste = (pr / bin_capacity as f64).powi(2);
    score += waste * 25.0;

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 1.5;

    // Mean-residual coupling: penalize bins far below mean residual (fragmented bins).
    score += (mean_residual - pr).abs() * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, big bonus for chaining.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 20.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // Next item won't fit here; slight penalty for blocking.
        score += 5.0;
    }

    // New-bin candidate handling: make empty bin attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by how poor the current fits are.
        score = 45.0 + pr as f64 * 0.5;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals too small to hold typical future items
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 200.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 150.0 + 0.5 * next_item_size as f64;
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
        // perfect chain: next item exactly fills the remainder
        if post_residual == next_item_size {
            score -= 250.0;
        }
    }

    // Prefer tight fits relative to mean residual
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no good open option exists
    if bin_residual == bin_capacity {
        score += 60.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && bin_residual >= next_item_size + item_size {
            score -= 40.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for typical items) are heavily penalized.
    let dead_zone_low = 1.0;
    let dead_zone_high = 19.0;
    if post_residual >= dead_zone_low as u32 && post_residual <= dead_zone_high as u32 {
        // Quadratic ramp inside the dead zone: smaller gaps are worse.
        let center = (dead_zone_low + dead_zone_high) / 2.0;
        let d = (post_residual as f64 - center).abs();
        score += 55.0 - 3.0 * d * d / (dead_zone_high - dead_zone_low);
    }

    // Reward tight fits (small post_residual outside dead zone).
    if post_residual > dead_zone_high as u32 {
        score -= 18.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 70.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow.
        score += 25.0 + 12.0 * pressure;
    } else {
        score -= 4.0 * pressure;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= dead_zone_high as u32 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item would be blocked by a dead-space gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Late in the stream, tighten up: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mild preference for bins below mean residual (balance residuals).
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are essentially wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post) * 5.0;
    }

    // Penalize "awkward" gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Best-fit flavor: tighter fit preferred (post residual already in base,
    // add mild curvature to emphasize small residuals).
    score += (post / cap) * 8.0;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, keep best-fit ordering via post residual
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading across too many bins,
    // but also allow new-bin escape when all fits are poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // New-bin candidate: make it attractive only when the item fits badly
    // everywhere (large post residual in existing bins) or when the
    // lookahead item would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        let fresh_bonus = 55.0
            + (post / cap) * 20.0
            + if next_item_size > 0 && next_item_size >= item_size { 8.0 } else { 0.0 };
        score -= fresh_bonus.min(70.0);
        // But penalize opening bins when a good fit already exists.
        if post_residual == 0 {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial lookahead reward: next item fits into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space scaled by mismatch
        let waste = post_residual as f64 - next_item_size as f64;
        score += 0.3 * waste.max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild pressure to consolidate when many bins are open
    score += 0.2 * open_bins_count as f64;

    // Early in stream: mild preference to keep new bins closed
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // New-bin candidate: default neutral-ish score, only attractive when
    // existing residuals are badly fragmented
    if bin_residual == bin_capacity {
        score = 40.0 + 0.5 * mean_residual;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 && (next_item_size == 0 || post_residual < 10) {
        score += 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item fits this bin anyway; slight penalty for consuming space now
        score += 8.0;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Many fitting bins: mildly penalize wasting space in a crowded field
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate logic: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open new bin when mean residual is high (open bins are full-ish)
        score -= 0.6 * mean_residual;
        // cheaper when many bins open (fragmented state, consolidate by opening fresh)
        score -= 2.0 * open_bins_count as f64;
        // early in stream, opening bins is fine; late in stream avoid it
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // if next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates below mean (consolidate emptier bins? no —
    // fill fuller bins first): penalize bins with residual above mean
    if mean_residual > 0.0 {
        score += 0.3 * ((bin_residual as f64 - mean_residual).max(0.0));
    }

    // Small-item arrival: keep large residuals intact
    if item_size <= 20 && bin_residual > 50 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (size 1) are still usable, but residuals that
    // fall into the classic "dead zone" (1..=9 in typical streams, scaled
    // here for unknown distributions) waste capacity. Penalize heavily.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, prefer tightening existing
    // bins over spreading; add mild penalty proportional to open count.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual can't host the next item -> likely dead space.
        score += 10.0;
    }

    // Prefer bins tighter than the mean residual (better packing density).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild progression term: early in the stream, slightly discourage
    // hoarding near-perfect bins; later, be stricter about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual <= 9 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is in a "useful"
    // residue class (multiples of small sizes) are more valuable.
    let pr = post_residual;
    let useful = if pr == 0 { 3.0 }
        else if pr % 10 == 0 { 2.0 }
        else if pr % 5 == 0 { 1.0 }
        else { 0.0 };
    score -= useful * 4.0;

    // Penalize small awkward leftovers in coarse bands.
    if pr > 0 && pr < 10 { score += 12.0; }
    else if pr < 20 { score += 6.0; }

    // Perfect fit reward.
    if pr == 0 { score -= 25.0; }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chaining).
    if next_item_size > 0 {
        if next_item_size == pr { score -= 20.0; }
        else if next_item_size <= pr { score -= 5.0; }
        else { score += 3.0; }
    } else {
        // Last item: prefer zero waste aggressively.
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2 - (open_bins_count as f64) * 1.5;
        // Late in stream, prefer reusing open bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // If next item is large, a fresh bin is more flexible.
        if next_item_size > 60 { score -= 10.0; }
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64 - mean_residual) * 0.1;

