    } else if post > 0 {
        score += 3.0; // narrow slot, deprioritize unless last chance
    }

    // Coupling with the lookahead item: if the next item fits exactly into
    // post_residual, this is a harmonic pairing — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size < post {
            let pair_res = post - next_item_size;
            if pair_res % 10 == 0 {
                score -= 5.0;
            }
            score += (pair_res % 10) as f64 * 0.5;
        }
        // If next item cannot fit here anyway, mild penalty for wasted lookahead
        if next_item_size > post && post > 0 {
            score += 2.0;
        }
    }

    // Last-chance bin logic: if this is the only fitting bin, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: keep the empty bin neutral-to-slightly
    // unattractive so we prefer filling existing bins, but attractive when
    // open bins are fragmented (high mean residual spread / many bins).
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 * 0.7 + mean_residual * 0.05;
        score += 4.0 - fragmentation * 0.3;
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing else fits: must open new bin
        }
    }

