pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual

    // Base: non-linear polynomial in normalized post residual.
    // Favor tight fits (small x) with an accelerating penalty as x grows.
    let mut score = 2.0 * x * x + 0.6 * x * x * x - 0.35 * x;

    // Smooth coupling of residual quality with stream progress:
    // late in the stream, waste becomes more costly (higher-order growth).
    let prog_term = progress * (x - 0.5) * (x - 0.5);
    score += 3.0 * prog_term;

    // Cross term: progress * post_residual (raw) — late items prefer very full bins.
    score += 0.02 * progress * pr;

    // Penalize bins whose residual deviates strongly from the mean residual
    // (keeps the pool of open bins homogeneous and reusable).
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: reward bins whose leftover can host the next item (smooth gate).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 0.8 * (1.0 - slack * slack);
        } else {
            score += 0.5 * ((nx - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (smooth saturation rather than hard constant).
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - x).max(0.0);
    }

    // Mild penalty for spreading across many open bins when residual is large.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * x;

    // New-bin candidate handling: a fresh empty bin gets a neutral-ish score;
    // make it attractive only when the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score = 1.2 + 2.0 * x * x + progress * 0.5;
    }

    score
}

