    // Prefer bins whose residual was already small (best-fit spirit).
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    // Open-bin pressure: with many open bins, discourage spreading; opening a
    // new bin is only attractive when this bin would leave a nasty gap.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if next item cannot fit in post residual but this bin could have
    // been shaped better (mild nudge toward compacting).
    if next_item_size > post_residual && next_item_size <= bin_residual && bin_residual != bin_capacity {
        score += 10.0;
    }

    // New-bin candidate: keep neutral-ish baseline, but allow it when the
    // current placement would create dead space.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0; // better to open fresh bin than bake in a dead gap
        }
    }

    // Mean residual coupling: if open bins are on average roomy, tighten more.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Stream progression: late in stream, waste tolerance shrinks.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.35 * tightness * tightness * (bin_capacity as f64);

    // Aggressive 2-step lookahead: strongly reward bins where the NEXT item
    // also fits into the post_residual (perfect chain match).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact or near-exact chain match gets a big bonus.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 + 8.0 * (1.0 - chain_waste / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize proportionally to how much
            // dead space is left behind (unusable for the lookahead item).
            let dead = (post_residual as f64) / (bin_capacity as f64);
            let next_rel = (next_item_size as f64) / (bin_capacity as f64);
            score += 6.0 * dead * (0.5 + next_rel);
        }
    } else {
        // Last item: pure tightest-fit behavior.
        score -= 4.0 * tightness;
    }

    // Relative-to-mean coupling: bins with residuals far below mean are
    // "almost full" — placing here consolidates waste.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res_f / mean_residual;
        if rel < 1.0 {
            score -= 3.0 * (1.0 - rel); // below-mean residual => good target
        } else {
            score += 1.5 * (rel - 1.0).min(2.0); // above-mean => less attractive
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make a fresh empty bin attractive only when
    // no open bin offers a good chain match. An empty bin has neutral
    // post_residual = capacity, so add a mild opening cost that tight-fit /
    // chain-bonus bins can overcome.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 + 4.0 * (1.0 - progress);
        // More open bins => slightly cheaper to open another (parallelism of fills)
        score -= 0.3 * (open_bins_count as f64).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tight fit reward (small post residual already low; amplify near-perfect fits)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * tightness * 10.0;

    // New-bin candidate handling
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin when alternatives exist;
        // the penalty fades if no other bin fits or bins are scarce.
        let alternative_pressure = if fitting_bins_count == 0 {
            -50.0 // must open a bin
        } else {
            18.0 + 4.0 * (fitting_bins_count as f64).ln().max(0.0)
        };
        // Early in stream, opening fresh bins is cheaper (more future to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += alternative_pressure * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: reward bins that can also host the next item
    if !is_new_bin && next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item also fits here -> chain bonus, stronger when residual slack is small
            let chain = 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= chain;
        } else if post_residual > 0 {
            // leaves a sliver that next item can't use -> penalize dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - dead).min(20.0);
            }
        }
    }

    // Last-chance bin bonus: avoid opening a bin for one item
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state: if mean residual is high, prefer packing into fuller bins
    if !is_new_bin {
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= fullness * mean_residual * 0.15;
    }

    // Mild preference to consolidate when many bins are open
    if !is_new_bin && open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: post residual, shaped non-linearly
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: penalize residual more as stream advances
    score += 30.0 * norm_pr * progress;

    // Interaction: residual squared vs item size ratio
    score += 12.0 * norm_pr * norm_pr * (1.0 - fit);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let pair_fill = (item_size as f64 + next_item_size as f64) / cap;
        score -= 15.0 * pair_fill * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Mean residual deviation: penalize bins far from the open-bin average
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress + 10.0 * fit * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is useless if no
    // future item (>= 1) can ever fill it; reward residuals that are
    // multiples of common small item sizes.
    let pr = post_residual;
    if pr > 0 {
        let usable = if pr >= 50 { 3.0 } else if pr >= 20 { 2.0 } else if pr % 10 == 0 { 1.5 } else { 0.0 };
        score -= usable * 5.0;
        // Penalize awkward residuals (prime-ish, small odd leftovers)
        if pr < 10 && pr > 0 {
            score += 8.0;
        }
        if pr % 2 == 1 && pr < 15 {
            score += 4.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty for tight bins
            score += 5.0;
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: prefer existing bins unless residual is
    // large and mean residual is high (fragmentation) — then fresh bin is fine.
    if bin_residual == bin_capacity {
        // base score for new bin = capacity (large), adjusted by state
        score = cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // open new bin when existing bins are fragmented
        if mean_residual < cap * 0.35 {
            score -= 120.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Prefer fullest bins (small residual before placement)
    score += (bin_residual as f64) * 0.3;

    // Mild load balancing: many open bins -> discourage spreading
    if open_bins_count > 8 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        // A gap is "dead" if it's too small for the smallest plausible item.
        // Treat gaps < 10 as fully dead; scale penalty quadratically as gap shrinks.
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * (10.0 - gap) * 4.0;
        } else {
            // Mild penalty for any leftover, growing as fraction of capacity wasted.
            score += gap * 0.15;
        }
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 12.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += pressure * 6.0;
        // But if mean residual of open bins is tiny (all nearly full),
        // a new bin is reasonable: relax the penalty.
        score -= mean_residual.min(20.0) * 0.8;
    } else {
        // Existing bin: small bonus to keep bins consolidated.
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize leaving a gap it could have used.
        if next_item_size <= post_residual + 5 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits with small slack: strong reward proportional to tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack);
    }

    // Penalize dead space too small for any plausible item (below min size 1..100)
    if next_item_size > 0 && post_residual < next_item_size {
        // waste: this bin's leftover can't host the lookahead item
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bins leave big waste
    if bin_residual == bin_capacity {
        let waste = mean_residual - post_residual as f64; // mean residual of open bins
        if waste < 15.0 {
            score += 25.0; // open bins are tight enough; don't open a new one
        } else {
            score -= 5.0; // open bins are wasteful; new bin is attractive
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for tighter bins relative to mean residual
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; mild penalty proportional to wasted lookahead.
            score += 4.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer the tightest; slight penalty to reduce crowding.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // New-bin candidate handling: opening a bin is costly early, cheaper late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize, less so as stream progresses.
        score += 45.0 * (1.0 - 0.5 * progress);
        // But if existing bins are crowded (high mean residual), opening is less bad.
        score -= 0.3 * mean_residual;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        // Using an existing bin: reward more when many bins are already open.
        score -= (open_bins_count as f64).min(20.0);
        // Encourage balancing: prefer bins with residual above the mean.
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Mild time-horizon modulation: late in the stream, pack tighter.
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling: small residuals are valuable late, penalize big waste early
    let x = pr / cap; // normalized post residual in [0,1)
    let poly = x * x * (1.0 - x) * 4.0; // hump around x=0.5 (medium dead space worst)
    score += poly * cap * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= tightness * tightness * 8.0 * (0.3 + 0.7 * progress);

    // Lookahead coupling: if next item fits the post residual, reward this bin smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 6.0 * fit_quality * fit_quality * (1.0 - progress);
        } else {
            // smooth penalty proportional to shortfall
            let gap = (nx - pr) / cap;
            score += 4.0 * gap * gap * cap * 0.1;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty when bin residual deviates from mean residual (keep residuals balanced)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline so it only wins when open bins are poor
    if bin_residual == bin_capacity {
        score = cap * (0.55 - 0.25 * progress) + 2.0 * dev.abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual divisible by 4 -> very reusable (many item sizes land on it)
    // Class 1: divisible by 2 -> moderately reusable
    // Class 2/3: odd residues -> harder to fill later
    let hclass = post_residual % 4;
    score -= match hclass {
        0 => 6.0,
        1 => 0.0,
        2 => 2.5,
        _ => -1.0,
    };

    // Dead-space penalty: post_residual below half the smallest item class is nearly dead.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 34 {
        score += 2.0;
    }

    // Integer-division thresholds: leftover in [10, 34] can host a mid item;
    // leftover >= 50 keeps strong flexibility.
    if post_residual >= 50 {
        score -= 5.0;
    }

    // Perfect fit reward (harmonic zero class).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post_residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after next placement, harmonic class again
            let post2 = post_residual - next_item_size;
            score -= 6.0 + (post2 % 4 == 0) as i32 as f64 * 4.0;
        } else {
            // next item will need another bin; slight penalty for leaving this bin stranded
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless post_residual would be tiny dead space.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
        if post_residual < 10 {
            score -= 10.0; // even better: nearly perfect fill
        }
    }

    // New-bin candidate logic: an empty bin has full residual; penalize it mildly so
    // we prefer existing bins with good fits, but keep it attractive when current
    // bin would leave large awkward residue relative to mean residual.
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual as f64 > mean_residual + 15.0 {
            score -= 20.0; // existing bins are congested; fresh bin is fine
        }
    }

    // Stream progression: early on, encourage tight packing into few bins;
    // late in stream, prioritize closing bins out (small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.15;

    // Congestion: many open bins -> prefer filling existing ones (penalize new bin implicitly
    // via post_residual=capacity, reward small post_residual).
    score -= (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are nearly worthless — penalize them hard.
    if post_residual > 0 {
        let min_item = 10u32;
        if post_residual < min_item {
            // Unusable gap: dead space penalty proportional to how close
            // post_residual is to zero (smaller = worse).
            score += (min_item - post_residual) as f64 * 25.0;
        } else if post_residual <= 20 {
            // Marginal gap: only fits tiny items, mildly discouraged.
            score += (20 - post_residual) as f64 * 4.0;
        }
    }

    // Reward perfect / near-perfect packing strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, using it
    // avoids opening a new bin — reward it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading items; the new-bin candidate (residual == capacity)
    // gets penalized when open_bins_count is high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    if bin_residual == bin_capacity {
        // Brand-new bin candidate: extra penalty scaled by number of open bins
        // and mean residual available elsewhere; late in the stream be more
        // conservative and avoid opening bins.
        score += 35.0 + open_bins_count as f64 * 3.0 + mean_residual * 0.3 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward
    // this placement (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - slack / post_residual as f64);
        }
    }

    // Slight preference for bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward, scaled by how snug the chain is.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 + 100.0 * snug;
        } else if post_residual > 0 {
            // Dead space the next item can't use: penalize proportionally.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 120.0 * waste;
        }
    }

    // Compare residual against mean residual of open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Mild preference to fill existing bins over opening new ones.
    if bin_residual < bin_capacity {
        score -= 30.0;
    } else {
        // Brand-new bin candidate: penalize slightly unless item is huge.
        score += 60.0 + 0.3 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac * fill_frac;

    // Penalize large post-residuals that are hard to reuse later.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }
    if post_residual >= 10 && post_residual < 20 {
        score -= 8.0; // still useful for small items
    }

    // Lookahead: if the next item fits the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Next item won't fit here; mildly penalize leaving big gaps.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open (amortization).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // Allow opening a new bin when the current item is huge and nothing fits well.
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Global state: when mean residual across open bins is small, bins are nearly
    // full; prefer filling them rather than spreading.
    score += (mean_residual - post_residual as f64) * 0.2;

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr + 0.6 * (1.0 - progress) * norm_pr * norm_pr);
    let mut score = poly * cap;

    // Smoothly increasing urgency to close bins as stream progresses.
    score -= 6.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.1;

    // Reward if the lookahead item fits in the post-residual (smooth kernel).
    if next_item_size > 0 {
        let fit_gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let tight = 1.0 - (fit_gap / cap);
        score -= 5.0 * tight * tight * (next_item_size as f64 / cap);
    }

    // Penalize a brand-new empty bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        let mean_waste = (mean_residual - item_size as f64).max(0.0) / cap;
        score += cap * (0.35 + 0.4 * scarcity + 0.5 * mean_waste) * (0.6 + 0.4 * (1.0 - progress));
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // Mild preference for tighter fits overall.
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: small dead zones are worse
    let dead_class = post_residual % 10;
    if dead_class > 0 && post_residual < item_size.min(50) {
        score += (10 - dead_class) as f64 * 1.5;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Post-residual can host the next item: strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        // harmonic tier of remaining slack after next item
        let tier = slack / 10;
        score -= 25.0 + tier as f64 * 2.0;
    } else if next_item_size > 0 {
        // next item would need a new bin anyway; penalize less if this bin is nearly full
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.3;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening unless item is large relative to residual pattern
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 35.0 - fill_frac * 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can serve next item too
        }
    }

    // Prefer tighter bins when many are open
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(10.0) * 2.0;

    // Mild late-stream tightening
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it's too small for typical future items.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 15.0;
    }

    // Reward tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving large gaps when the item was small relative to the bin
    // (wasteful use of a nearly empty bin unless it's a new-bin candidate).
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio < 0.4 && post_residual > 40 {
            score += (post_residual as f64 - 40.0) * 0.8;
        }
    }

    // Open bins pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if is_new_bin {
        score += open_pressure * 2.0;
    } else {
        score -= open_pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 8 {
            score -= 20.0;
        }
        // If next item cannot fit here anyway, mild bonus for keeping gaps usable.
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the gap: gap becomes dead space for lookahead.
        score += 8.0;
    }

    // Prefer bins with below-mean residual (tighter bins) to keep looser bins
    // flexible for future large items.
    let mean_dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += mean_dev * 30.0;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect packing, reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the NEXT item exactly fills the post_residual,
    // this placement chains perfectly — reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits inside the leftover: mild reward proportional to fill.
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover space: penalize dead space more
            // when the leftover is small (unusable) but not zero.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 30.0;
            }
        }
    }

    // Prefer bins that are already tight relative to the fleet mean residual:
    // packing into below-average-residual bins consolidates waste.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But early in the stream or with few open bins, new bins are cheap.
        if open_bins_count <= 2 {
            score -= 100.0;
        }
        // If lookahead item is huge relative to current item, a fresh bin helps
        // preserve flexibility for large future items.
        if next_item_size > item_size + 20 {
            score -= 60.0;
        }
    }

    // Slight preference for keeping many open bins consolidated as stream progresses.
    score += 0.5 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- New-bin candidate handling ----
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline for a fresh bin: full capacity of "wasted" residual,
        // adjusted by global state. Opening a new bin is discouraged when
        // many bins are already open (fragmentation risk), encouraged when
        // the current bin landscape is poor (high mean residual = bad fits).
        let mut new_bin_score = bin_capacity as f64;
        // Early in the stream, opening bins is cheap and builds diversity.
        new_bin_score -= (1.0 - progress) * 20.0;
        // If open bins have poor residuals, a fresh bin is more attractive.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 15.0;
        // If only one bin fits and it is this empty-bin call context, penalize less.
        if fitting_bins_count == 0 {
            new_bin_score -= 25.0;
        }
        // If the next item is large, having a fresh bin is valuable.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt > bin_capacity as f64 * 0.5 {
                new_bin_score -= 10.0;
            }
        }
        return new_bin_score;
    }

    // ---- Tight-fit reward: strongly prefer minimal post_residual ----
    // Non-linear: quadratic reward for very tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // ---- Exact fit is perfect ----
    if post_residual == 0 {
        score -= 100.0;
    }

    // ---- Dead-space penalty: residual too small to fit any plausible item ----
    // Items are 1..100; residual below the smallest item is pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable slivers are bad
    }

    // ---- Lookahead coupling: reward if next item fits in post_residual ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Next item can chain into this bin: reward proportionally.
            score -= 12.0 + (nxt / bin_capacity as f64) * 10.0;
        } else {
            // Next item won't fit here: penalize leaving medium dead space.
            score += 6.0;
        }
    }

    // ---- Last-chance bonus: if this is the only bin that fits, use it ----
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Many options: be pickier, penalize mediocre fits.
        score += (fitting_bins_count as f64).min(5.0) * 2.0;
    }

    // ---- Global state: prefer filling bins when many are open ----
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 1.5;
    }

    // ---- Mean-residual alignment: prefer bins below mean residual (tighter) ----
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // ---- Time horizon: late in the stream, consolidate aggressively ----
    if progress > 0.8 {
        score -= 10.0 * progress;
    }

    // ---- Prefer placing larger items into fuller bins ----
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear base: super-linear cost of leftover space.
    let mut score = (pr / cap).powf(1.7) * 100.0;

    // Reward tight fits more strongly as the stream progresses (fill up open bins late).
    let tightness = 1.0 - pr / cap;
    score -= tightness.powf(2.2) * (30.0 + 50.0 * progress);

    // Dead-space penalty: leftover that cannot fit the next item is likely wasted.
    let nx = next_item_size as f64;
    if nx > 0.0 && pr < nx {
        let gap = (nx - pr) / cap;
        score += gap.powf(1.4) * (40.0 + 60.0 * progress);
    } else if nx > 0.0 {
        // Reward bins that remain useful for the lookahead item.
        let fit_ratio = (nx / pr.max(1.0)).min(1.0);
        score -= (1.0 - fit_ratio) * 15.0 * (1.0 - progress);
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let waste = pr / cap; // = 1.0 for empty bin
        score += waste * 0.0; // no-op to keep coupling explicit
        score += 18.0 - 10.0 * progress; // mild cost of opening a bin, cheaper early
        // If existing bins are very fragmented, opening a fresh bin is attractive.
        score -= (mean_residual / cap).powf(2.0) * 20.0;
    }

    // Slight penalty for spreading across too many open bins.
    score += (open_bins_count as f64).powf(0.8) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual / 10 classes
    let post_class = (post_residual / 10) as f64;
    score -= post_class * 6.0;

    // Perfect fit reward (dead space zero)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small unusable dead space penalty: leftover in (0,10) is nearly dead
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo classes: leftovers that are multiples of 10 pair well with
    // typical item sizes; reward post_residual divisible by 10.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: strong reward
            score -= 18.0;
            // Exact chain (post_residual == next_item_size) is ideal
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // Next item will NOT fit here: if this bin is the only fitting
            // one, place here anyway (last-chance logic).
            if fitting_bins_count <= 1 {
                score -= 15.0;
            } else {
                // Penalize leaving a bin whose residual is smaller than
                // the next item when other options exist.
                score += 8.0;
            }
        }
        // Harmonic residue of next item vs post residual (mod 10 match)
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin
    // would be badly fragmented. Empty-bin call has bin_residual == cap.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; discount when stream is early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 - 15.0 * progress;
        // If many open bins already, opening more is worse
        score += (open_bins_count as f64) * 1.5;
        // But if mean residual of open bins is tiny, new bin is fine
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins: closeness of item to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Mild penalty for very large leftover relative to capacity
    if post_residual as f64 > 0.6 * cap {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

