    let waste_frac = post_residual as f64 / bin_capacity as f64;
    if waste_frac <= 0.15 {
        score -= 25.0;
    } else if waste_frac >= 0.5 {
        score += 10.0; // leaving more than half empty is suspicious
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let pressure = (open_bins_count as f64).sqrt() * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if nothing fits well.
        score += 30.0 + pressure * 4.0;
        if fitting_bins_count == 0 {
