        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        score -= 35.0;
    }

    // Mean residual coupling: if open bins are generally roomy, prefer
    // consuming from a roomy bin; penalize when this bin is much tighter
    // than average (its residual is precious).
    if (bin_residual as f64) < mean_residual - 20.0 {
        score += 8.0;
    } else if (bin_residual as f64) > mean_residual + 20.0 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
