    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would NOT fit post-residual but would fit another bin,
    // mildly penalize leaving a gap that blocks the future item.
    if next_item_size > post_residual && next_item_size <= bin_capacity {
        score += 4.0;
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

