        score += 8.0;
    }

    // Lookahead: bonus if the next item fits into the post residual (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual too small for next item: mild penalty.
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer fuller bins (best-fit bias).
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: open a new bin only if current fits are poor and
    // many bins are already open late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_options = if fitting_bins_count == 0 { 1.0 } else { (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64 };
        score = 12.0 - 10.0 * poor_options + 8.0 * progress + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 30.0; // never open when a last-chance bin exists
        }
    }

    // Global state coupling: penalize bins far from mean residual (fragmentation).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - progress) * 40.0;
    score += poly;

    // Penalize large post-residual more as the stream progresses
    score += progress * pr * pr / cap;

    // Reward tight fits: subtract when post_residual is small
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 25.0;

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr >= next {
            score -= 12.0 * (1.0 - ((pr - next) / cap).abs());
        } else {
            score += 8.0;
        }
    }

    // Dead-space penalty: post_residual below smallest possible item
    if pr > 0.0 && pr < 10.0 {
        score += 30.0 * (10.0 - pr);
    }

    // Slight preference to fill existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (multiples of 10, 25, 50) are "reusable" classes; odd/tiny fragments are dead space.
    let r = post_residual;
    if r == 0 {
        score -= 40.0; // perfect fit is ideal
    } else {
        let mut bonus = 0.0;
        if r % 10 == 0 { bonus += 8.0; }
        if r % 20 == 0 { bonus += 4.0; }
        if r % 25 == 0 { bonus += 6.0; }
        if r % 50 == 0 { bonus += 5.0; }
        // integer-division thresholds: large usable chunks
        if r / 25 >= 1 { bonus += 3.0; }
        if r / 50 >= 1 { bonus += 3.0; }
        score -= bonus;

        // tiny fragments (< 10, the minimum item size) are pure dead space
        if r < 10 {
            score += 25.0;
        } else if r < 20 && r % 10 != 0 {
            score += 10.0;
        }
    }

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if next_item_size <= r {
            if r - next_item_size == 0 {
                score -= 30.0;
            } else if (r - next_item_size) % 10 == 0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to the gap
            score += ((next_item_size - r) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when few bins fit
    // the item or residual landscape is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (fitting_bins_count == 0) as i32 as f64
            + (open_bins_count == 0) as i32 as f64
            + (mean_residual < item_size as f64) as i32 as f64;
        if pressure >= 1.0 {
            score -= 15.0 + 10.0 * progress;
        } else {
            // keep existing bins preferred; slight tilt toward compacting early
            score += 12.0 - 5.0 * progress;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score += (bin_residual as f64) * 0.05;
    score -= (mean_residual - post_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space) below 10
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        // perfect fit: heavy reward
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Penalize leaving gaps that could fit the next item (waste of opportunity)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // but if no open bin fits well, opening may be fine; soften when mean residual is low
        score -= 2.0 * (100.0 - mean_residual).max(0.0) / 10.0;
    }

    // Mild early-stream preference to consolidate into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial lookahead reward: next item fits into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space scaled by mismatch
        let waste = post_residual as f64 - next_item_size as f64;
        score += 0.3 * waste.max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild pressure to consolidate when many bins are open
    score += 0.2 * open_bins_count as f64;

    // Early in stream: mild preference to keep new bins closed
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // New-bin candidate: default neutral-ish score, only attractive when
    // existing residuals are badly fragmented
    if bin_residual == bin_capacity {
        score = 40.0 + 0.5 * mean_residual;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress horizon: early in the stream, be pickier about residual waste;
    // late in the stream, just fill bins to avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strongly reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving dead space that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small dead space is fine (near-full bin)
    }
    if post_residual >= 10 && post_residual <= 20 {
        score += 6.0; // awkward gap that only tiny items can fill
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins that are already well-filled relative to the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: opening a bin is expensive.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0 + open_bins_count as f64 * 1.5;

        // If no open bin fits (or this is the only option), opening is unavoidable.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            // Compare: is the existing fit terrible? Then a new bin may be better.
            let waste = (bin_residual - item_size) as f64;
            if waste > 30.0 {
                score -= 20.0; // allow opening a fresh bin instead of a bad fit
            }
        }

        // Late in the stream, discourage new bins even more.
        if progress > 0.8 {
            score += 20.0 * progress;
        }
    }

    // Mild global pressure: many open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: post_residual weighted by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large wasted space quadratically, softened early in stream
    score += 40.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) with cubic bonus
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Dead-space avoidance: residual too small for typical future items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            // smooth reward when next item also fits
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Prefer fuller bins among many open bins
    score -= 5.0 * (1.0 - norm_pr) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Slight preference for keeping mean residual balanced
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: neutral-ish baseline with mild penalty, decreasing late
    if bin_residual == bin_capacity {
        score = 35.0 * (1.0 - 0.4 * progress) + 10.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is in a "useful"
    // residue class (multiples of small sizes) are more valuable.
    let pr = post_residual;
    let useful = if pr == 0 { 3.0 }
        else if pr % 10 == 0 { 2.0 }
        else if pr % 5 == 0 { 1.0 }
        else { 0.0 };
    score -= useful * 4.0;

    // Penalize small awkward leftovers in coarse bands.
    if pr > 0 && pr < 10 { score += 12.0; }
    else if pr < 20 { score += 6.0; }

    // Perfect fit reward.
    if pr == 0 { score -= 25.0; }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chaining).
    if next_item_size > 0 {
        if next_item_size == pr { score -= 20.0; }
        else if next_item_size <= pr { score -= 5.0; }
        else { score += 3.0; }
    } else {
        // Last item: prefer zero waste aggressively.
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2 - (open_bins_count as f64) * 1.5;
        // Late in stream, prefer reusing open bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // If next item is large, a fresh bin is more flexible.
        if next_item_size > 60 { score -= 10.0; }
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful are heavily penalized.
    // Useless gap threshold: nothing but tiny items could use a gap < ~15.
    let dead_threshold = 15.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Reward bins whose residual closely matches the item (tight fit shaping).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Open-bin pressure: discourage opening new bins when many are already open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 6.0 * (open_bins_count as f64) + 20.0 * progress;
        // But if no existing bin fits well, allow opening a new one.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If this item is a last-chance fit for exactly one bin, avoid new bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    } else {
        // Reward using existing bins, especially scarce fits.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Prefer bins with larger residuals (keeps small bins consolidating? no:
        // prefer bins with smaller residual to fill tightest first is handled by post_residual).
        // Slight preference to keep mean residual balanced: penalize bins far from mean.
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;
    }

    // Lookahead: if the next item can exactly use this bin's post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item would fit in post_residual, mild reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }
    // If next item cannot fit in post_residual, penalize leaving a large stranded gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item still fits well in the residual left behind
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 0.5;
    }
    // Next item would not fit after this placement: penalize wasted residual
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits relative to current bin residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Penalize placements leaving residual far from mean (dead-space creation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when few bins fit or residual is small everywhere
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 400.0 * pressure;
        if mean_residual < 15.0 {
            score -= 120.0; // open bins nearly full -> fresh bin is good
        }
        score += open_bins_count as f64 * 5.0;
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within the stream (0..1).
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Base: strongly reward tight fits (low post-residual), non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize wasted residual relative to current item size: dead space smaller
    // than the smallest plausible future item is pure loss.
    if post_residual > 0 && post_residual < item_size.max(1) {
        score += 25.0;
    }
    // Residuals below ~10 are unusable given item sizes >= 1..100 unknown; mild penalty.
    if post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a gap; reward proportionally to fill.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // Next item cannot use this residual: penalize large leftover gaps.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Many candidates: emphasize best-fit discrimination.
        score += 0.5 * fitting_bins_count as f64;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when few open bins can fit this item,
        // or when all open residuals are too small to be useful.
        let scarcity = (fitting_bins_count as f64).min(5.0) / 5.0; // 0 = scarce
        score -= 20.0 * (1.0 - scarcity);
        // Late in the stream, avoid proliferating bins with big residual spreads.
        score += progress * 12.0;
        // If mean residual is large, prefer using existing capacity.
        if mean_residual > item_size as f64 {
            score += 18.0;
        }
        // Opening a bin when many bins are open is costly.
        score += (open_bins_count as f64).sqrt() * 3.0;
        // Large items start fresh bins happily (hard to fit elsewhere).
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    } else {
        // Existing bin: reward bins whose residual is close to the item (best fit).
        let diff = (bin_residual as f64 - item_size as f64).abs();
        score += 0.3 * diff;
        // Slight preference for bins below the mean residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), non-linearly amplified.
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling: waste penalized more as stream progresses.
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Reward near-exact fills with a smooth saturation term.
    score -= 20.0 * (1.0 - norm_pr).powi(4) * (1.0 + progress);

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - (nx / pr)) * (1.0 + progress);
        } else {
            // Penalize leaving a residual that just barely fails the next item.
            score += 6.0 * (1.0 - (pr / nx)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many bins; smooth in open_bins_count.
    score += 0.6 * open_bins_count as f64 * norm_pr;

    // Coupling with mean residual: avoid bins deviating from fleet state.
    score += 0.15 * (mean_residual - pr).abs();

    // New-bin candidate must look unattractive unless residuals are all bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable"
    // classes (small leftovers, or multiples of common item sizes).
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if pr <= 5 {
        score -= 20.0;
    } else if pr <= 15 {
        score -= 10.0;
    } else {
        // penalize mid-range dead space, worse if not a multiple of 10
        let r10 = pr % 10;
        if r10 == 0 {
            score -= 5.0;
        } else {
            score += (10 - r10) as f64 * 0.8;
        }
    }

    // Integer-division threshold classes on post_residual
    let class = pr / 10; // 0..=10
    score += match class {
        0 => -8.0,
        1 => -4.0,
        2 | 3 => 0.0,
        4 | 5 => 3.0,
        6 | 7 => 5.0,
        _ => 7.0,
    } as f64;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack <= 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize leaving large unusable space
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: neutral baseline, slightly penalized so it is
    // only chosen when open bins score poorly; scale with stream progress.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer filling bins below mean residual (i.e., tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Many open bins: discourage fragmentation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=12) are nearly
    // unusable for future items -> penalize them super-linearly.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits (item consumes most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Penalize dumping huge items into nearly-full bins leaving big gaps? No:
    // instead penalize placing small items into large-residual bins (wasteful).
    if item_size < 30 && bin_residual > 60 {
        score += 10.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing
    // bins (existing-bin calls have bin_residual < capacity; new bin has full).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // New-bin candidate: full residual -> add fixed surcharge so it only wins
    // when all existing fits are terrible, plus a bonus if it enables a
    // perfect pairing with the lookahead item.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin (only fitting bin): strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead synergy: if the next item exactly fills this bin's post
    // residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual && post_residual > 0 {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the gap anyway -> dead space, mild penalty
        score += post_residual as f64 * 0.15;
    }

    // Mean-residual coupling: bins far below mean residual are "loose";
    // prefer bins closer to being filled (lower residual than mean).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let capacity = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 {
        let diff = (post - next).abs();
        if diff < 0.5 {
            score -= 30.0; // perfect chain: next item exactly fills this bin
        } else if next <= post {
            // next item fits after this one: reward proportionally to how well it uses leftover
            let fill_ratio = next / post.max(1.0);
            score -= 10.0 * fill_ratio;
            // extra reward if next item leaves a still-usable remainder
            let post2 = post - next;
            if post2 <= 10.0 {
                score -= 8.0; // nearly perfect two-item packing
            }
        } else {
            // next item won't fit here: penalize leaving dead space next item can't use
            score += 5.0 * (1.0 - post / next.max(1.0)).min(1.0);
        }
    } else {
        // Last item: minimize post_residual strongly
        score -= 15.0 * (1.0 - post / capacity);
    }

    // Penalize large unusable leftovers relative to typical item sizes
    if post > 0.0 && post < 10.0 {
        score += 12.0; // tiny dead space
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.5 * (residual - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin; reduce if stream is early or many items remain
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 20.0 * progress;
        if next_item_size > 0 && next <= bin_capacity as u32 {
            // a fresh bin can chain current + next if they roughly complement
            if (item_size as f64 + next) <= capacity + 0.5 {
                score -= 15.0;
            }
        }
    }

    // Slight preference to fill bins with more accumulated content (fewer open bins overall)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but dead space below min item size (1) is useless.
    if post_residual == 0 {
        score -= 50.0; // perfect fit is golden
    } else if post_residual < 10 {
        score += 8.0; // tiny unusable sliver: penalize leaving it
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish, slightly worse than a decent tight fit.
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no alternatives -> open new bin
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        score += open_bins_count as f64 * 1.5;
        return score;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chains nicely
        } else if post_residual > 0 {
            // wasted unless next item small; scale penalty with gap
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score += gap * 0.3;
        }
    }

    // Prefer filling bins that deviate below mean residual (tighten laggards).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.4; // bin is tighter than average: good, use it
    } else {
        score += (-dev) * 0.15; // loose bin: mild penalty
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Progress horizon: early stream, be conservative with slivers; late, pack hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post-residual, non-linearly warped by stream progress.
    // Late in the stream, small residuals matter less (dead space is cheaper),
    // so the quadratic residual penalty relaxes with progress.
    let pr_norm = pr / cap;
    let base = pr * (1.0 + 0.8 * pr_norm * (1.0 - progress)) - 12.0 * progress * pr_norm;

    // Reward tight fits: strongly subtract when post_residual is small,
    // with a smooth cubic falloff.
    let tight = -30.0 * (1.0 - pr_norm).powi(3);

    // Lookahead coupling: if the next item fits into post_residual, reward this placement;
    // smooth interaction between post_residual and next item size.
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0) / cap;
        -15.0 * fits_next * (1.0 + 0.5 * progress)
        // Penalize wasting almost all residual on a too-small next-item gap
        + 8.0 * ((nx - pr).max(0.0) / cap) * (1.0 - progress)
    } else {
        0.0
    };

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -25.0
    } else {
        0.0
    };

    // New-bin candidate: penalize mildly, but relax late in stream when
    // open bins have large mean residual (bad candidates).
    let mean_gap = (mean_residual - pr).abs() / cap;
    let new_bin = if bin_residual == bin_capacity {
        10.0 + 15.0 * (1.0 - progress) - 5.0 * mean_gap
    } else {
        0.0
    };

    // Slight preference for bins whose residual is close to the item (coupling term).
    let coupling = -0.5 * ((bin_residual as f64 - item_size as f64) / cap);

    base + tight + lookahead + last_chance + new_bin + coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize post_residual non-linearly.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Harmonic class of post_residual: dead space in small classes is worse.
    let class = post_residual / 10; // capacity fraction class (0..10)
    score += match class {
        0 => -8.0,   // near-perfect fit
        1 => -3.0,
        2 => 0.0,
        3 => 1.5,
        4 => 3.0,
        5 => 4.5,
        6 => 6.0,
        7 => 7.5,
        8 => 9.0,
        _ => 10.0,
    };

    // Integer-division thresholds: penalize residuals that no small item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
            // harmonic bonus when next item exactly fills remaining space
            if post_residual - next_item_size < 5 {
                score -= 3.0;
            }
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize spreading across many open bins lightly.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: only open a new bin if current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual > 0.0 { mean_residual } else { 1.0 };
        let fragmentation = (mean_residual / bin_capacity as f64).powi(2);
        score = 20.0 + fragmentation * 30.0
            - if fitting_bins_count == 0 { 25.0 } else { 0.0 }
            + 0.1 * pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are toxic.
    let min_useful = next_item_size.max(1);
    if post_residual > 0 && (post_residual as u64) < (min_useful as u64) {
        score += 60.0 + (min_useful - post_residual) as f64 * 3.0;
    }
    // Gaps below a hard floor are unusable forever if stream has small items possible.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward proportional tightness.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Reward using a bin that can't be reused by the lookahead item anyway.
    if next_item_size > 0 && bin_residual >= item_size && bin_residual < item_size + next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation over new bins.
    let open_pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 20.0 + 12.0 * open_pressure;
        // But if no existing bin fits well, opening is fine (handled by comparisons).
        if post_residual > 0 && post_residual < min_useful {
            score += 30.0;
        }
    } else {
        score -= 5.0 * open_pressure.min(3.0);
    }

    // Late in stream: consolidate aggressively, keep residual near mean.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 - mean_residual).abs() * (0.3 + 0.7 * progress);

    // Small early-stream nudge toward tight fits.
    score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prog = step_index as f64 / total_items.max(1) as f64;

    // Aggressive 2-step lookahead: perfect chain fit (post_residual == next_item_size)
    // is the gold standard — heavily reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if gap < 0.5 {
            // Perfect 2-step chain: residual exactly consumed by next item.
            score -= 60.0 + 20.0 * (1.0 - prog);
        } else if nxt <= pr {
            // Next item fits in the leftover: reward proportionally to closeness.
            score -= 30.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit: penalize leftover that is nearly-but-not usable.
            score += 5.0 * (1.0 - pr / cap);
        }
    }

    // Coupling with mean residual: bins with residual far below the mean are
    // "odd" bins; placing here is fine only if it tightens them.
    let mr = mean_residual.max(0.0);
    let deviation = (pr - mr).abs();
    score += 0.15 * deviation;

    // Penalize leaving dead space smaller than the minimum item size (unusable).
    if next_item_size > 0 && pr > 0.0 && pr < 1.0 {
        score += 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., best open post_residual would be large) or stream is early.
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 15.0 * (1.0 - prog);
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits: new bin is necessary
        }
        if next_item_size > 0 && (next_item_size as f64) > pr - 1.0 {
            score += 20.0; // fresh bin pairs badly with next item
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    if prog > 0.8 && bin_residual != bin_capacity {
        score -= 8.0 * (prog - 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward small-but-not-zero post residual (dead space 1..=9 is hard to use).
    if post_residual > 0 && post_residual <= 9 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * next_fit;
        if post_residual == next_item_size {
            score -= 10.0; // perfect chain: bin fully consumed by next item
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // post-residual too small for next item: mild penalty proportional to wasted potential
        score += 2.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 10.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be conservative (favor tight fits more);
    // late in the stream, prioritize closing bins out (favor larger post_residual usage).
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - t) * fit_ratio;
    score += 3.0 * t * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into already-stressed bins rather than spreading; also make new bins less attractive.
    let mean_fit_gap = (mean_residual - item_size as f64).abs();
    score += 0.05 * mean_fit_gap * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many items remain or few bins open.
        score = bin_capacity as f64 * 0.9;
        score -= 4.0 * (1.0 - t); // early stream: opening bins is cheaper
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open
        } else if fitting_bins_count == 1 {
            // Only one fitting bin; open a new bin only if that bin would be badly fragmented.
            if fit_ratio > 0.9 {
                score += 50.0; // the single fit is actually great, keep it
            }
        } else {
            score += 6.0; // several options exist; prefer reusing
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 {
            score -= 5.0;
        }
    }

    // Small stabilizing coupling: discourage near-empty usage of large-residual bins
    // when the item is tiny relative to the residual.
    if fit_ratio < 0.2 && bin_residual != bin_capacity {
        score += 4.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear emphasis on tight fits.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream progress coupling: later in the stream, dead space becomes more costly.
    let progress_penalty = progress * (pr * pr) / (cap * cap) * 40.0;
    score += progress_penalty;

    // Reward near-perfect fits smoothly (post_residual close to 0).
    let perfect_bonus = (-pr * 0.15) - (norm_pr * norm_pr * 30.0);
    score += perfect_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty scaled by wasted residual.
        score += 0.05 * pr;
    }

    // Mean residual context: penalize bins far from the mean residual (outliers).
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev;

    // Many open bins: discourage spreading items; prefer filling existing bins.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: keep it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (1.0 - fitting_bins_count as f64).min(1.0) * (1.0 - progress);
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue classes modulo 10
    // define "usable" vs "dead" space bands.
    let r = post_residual;
    let class = if r == 0 { 0 } else if r <= 9 { 1 } else if r <= 19 { 2 } else if r <= 29 { 3 } else if r <= 49 { 4 } else { 5 };

    // Penalize dead space classes super-linearly.
    let class_penalty = match class {
        0 => -60.0,                       // perfect fit: strongly reward
        1 => 25.0 + (10 - r) as f64 * 4.0,// tiny dead space: worst waste per unit
        2 => 10.0 + (20 - r) as f64 * 2.0,
        3 => 3.0,
        4 => -2.0,                        // roomy residual still useful
        _ => 0.0,
    };
    score += class_penalty;

    // Exact-fit coupling: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == r {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size < r {
        // Reward proportionally how much of the residual the next item consumes.
        let fill = next_item_size as f64 / r as f64;
        score -= 20.0 * fill;
    } else if next_item_size > 0 && next_item_size > r {
        // Next item won't fit here: penalize if we leave a large residual anyway.
        score += (next_item_size - r) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge or
    // all open bins would leave tiny dead space.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score += 30.0 - 20.0 * tightness;
        if next_item_size > 0 && next_item_size <= r {
            score += 10.0; // item pairs well with a fresh bin later
        }
    }

    // Fractional capacity coupling: reward bins whose residual is a clean
    // fraction of capacity (harmonic divisor classes).
    if r > 0 && bin_capacity % r == 0 {
        score -= 5.0;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (post_residual as f64 / cap);

    // Slight preference for bins below mean residual (tighter bins fill first).
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold even the smallest
    // plausible future item are "dead". Penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward near-perfect fits (post_residual close to zero).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual was already small (tight packing preference):
    // prefer filling the tightest bin, i.e. penalize bins with lots of room.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few are open, a new bin is cheap.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discounted early in stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 60.0 * pressure - 10.0 * (1.0 - progress);
        // If item fits poorly nowhere else (last chance bin exists), avoid new bin.
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
    } else {
        // Last-chance bin bonus: strongly favor the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // If the next item fits exactly in the post-residual, reward this placement.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 25.0;
        }
        // Penalize leaving a gap that next item cannot use but is close.
        if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
        // Mean-residual coupling: prefer bins below mean residual (tighter than average).
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead fit: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0 + 20.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize mismatch between leftover and next item
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.35;
        // If next item cannot use the leftover, penalize proportionally
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates far below mean (wasting usable space elsewhere)
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Prefer filling bins tightly relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Discard tiny unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 15.0;
    }

    // New-bin candidate: mild penalty so existing decent fits win, but allow
    // opening when no open bin fits well (high post_residual everywhere)
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward near-perfect fits nonlinearly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= 6.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Penalize dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead coupling: if next item fits exactly into post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / 50.0).max(0.0);
        } else {
            // Next item cannot use this residual; mild penalty proportional to leftover value.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate handling: prefer new bin only when open bins are badly fragmented
    // or this is a very tight fit elsewhere is impossible.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score = 60.0 + post_residual as f64;
        // Early in stream, opening bins is cheap; later, expensive.
        score += 30.0 * progress;
        // If many bins are open and fragmented, discourage yet another bin.
        score += open_bins_count as f64 * 1.5;
        // If mean residual is large, open bins can absorb the item instead.
        if mean_residual > item_size as f64 * 1.2 {
            score += 25.0;
        }
        // If the next item is huge and would need a fresh bin anyway, opening now is fine.
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    // Slight preference to fill bins with smaller residual first (tighter packing pressure).
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Mild global pressure: as stream progresses, discourage wasting space.
    score += mean_residual * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: late in stream, tighten packing more aggressively.
    let progress_gain = 1.0 + 1.5 * t * t;
    score *= progress_gain;

    // Smooth interaction: post_residual vs mean residual (avoid inflating mean).
    score += 0.35 * (pr - mean_residual).abs() * (0.5 + t);

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_quality = 1.0 - norm_pr;
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bin: strong smooth reward scaled by how well it fits.
    if fitting_bins_count == 1 {
        score -= 8.0 * fit_quality;
    }

    // Lookahead coupling: penalize leaving space just below next item size
    // (dead space), reward space that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 3.0 * (1.0 - (gap / cap).min(1.0));
        } else {
            score += 2.5 * (-gap / cap) * (1.0 + t);
        }
    }

    // Mild penalty for bin proliferation late in the stream.
    score += 0.05 * open_bins_count as f64 * (0.3 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "small"
    // residue class (near-perfect fills) are strongly rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo classes on post_residual (capacity quantum = 10)
    let quantum = 10u32;
    let post_mod = post_residual % quantum;
    let post_div = post_residual / quantum;

    // Reward post residuals that are tiny or exactly on quantum boundaries
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_mod <= 2 {
        score -= 25.0 * (1.0 - pr / cap); // near-quantum dead space is tolerable
    } else if post_mod >= quantum - 2 {
        score -= 15.0;
    } else {
        // mid-class residuals: penalize quadratically
        score += (post_mod as f64 - 5.0).abs() * 2.0;
    }

    // Integer-division tier of post_residual: small tiers are better targets
    score -= (bin_capacity as u32 / (post_div.max(1))) as f64 * 0.5;

    // Harmonic fraction of residual used
    let fill_frac = 1.0 - pr / cap;
    score -= fill_frac * fill_frac * 20.0;

    // Lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward tight coupling
            let after = post_residual - next_item_size;
            score -= 20.0 - (after as f64) * 0.3;
            if after % quantum == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: penalize if this bin would be stranded
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize unless existing fits are bad
    if bin_residual == bin_capacity {
        score = cap - (item_size as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0;
        }
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Many open bins: discourage spreading, favor tight bins
    if open_bins_count > 3 {
        score += (mean_residual - pr) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item
    // (items >= 10) are nearly worthless, so penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 35.0;
    } else if post_residual < 30 {
        score += 18.0;
    } else if post_residual < 40 {
        score += 8.0;
    }

    // Reward tight fits (small usable post_residual) proportionally.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // If the next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        let leftover = post_residual - next_item_size;
        score -= 10.0 * (1.0 - leftover as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mild penalty unless post_residual is dead space anyway.
        if post_residual >= 10 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid pushing the item into a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; also consider stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Mean residual coupling: if open bins are already sparse on average,
    // discourage wasting this bin's space unless the fit is tight.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate: only attractive when no good placement exists,
    // i.e. when open bins are numerous and this item would leave dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + pressure;
        if post_residual >= 10 && post_residual < 30 {
            score += 10.0; // opening a bin for a near-full fill is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect pairing: post_residual == next_item_size -> very strong bonus.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to closeness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasting space the lookahead could use.
            score += 10.0 + 0.3 * diff;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    let resid = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (resid - mean_residual);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    }

    // Late in the stream, consolidation matters more: penalize leftover space harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor minimal post residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.25;
        } else {
            // Next item won't fit here: penalize leaving a large unusable-looking gap
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize bins far from the mean residual (fragmentation signal),
    // unless it's the empty new-bin candidate.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // New-bin candidate: only attractive when few bins fit or residuals are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let threshold = 55.0 + 25.0 * (1.0 - progress);
        // Open new bin only if best existing placement would leave big waste
        score = threshold + (bin_capacity as f64 - item_size as f64) * 0.3 - pressure * 20.0;
        if item_size > 60 {
            score -= 10.0; // large items justify fresh bins more readily
        }
    }

    // Late in stream: consolidate, avoid opening bins, prefer near-full bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.2;

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Smooth polynomial coupling: penalize residual with progress-weighted curvature.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += post * (0.35 * p2 + 0.55 * p3);

    // Reward tight fits non-linearly (small post_residual is exponentially good later).
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * (0.4 + progress);

    // Penalize leaving awkward medium dead-space (post_residual near half capacity).
    let half = (post / cap - 0.5).abs();
    score += 6.0 * (0.25 - half * half).max(0.0) * (1.0 - progress);

    // Last-chance bin: strong reward.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Lookahead: if next item fits snugly into post_residual, reward; else mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 8.0 * snug * snug * (0.5 + progress);
        } else {
            score += 3.0 * (1.0 - progress);
        }
    }

    // Prefer bins with below-mean residual (consolidate emptier space).
    score += 0.4 * (bin_residual as f64 - mean_residual) * (1.0 - progress);

    // Mild preference for filling bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * fit_frac * 2.0;

    // New-bin candidate: only attractive when nothing fits well.
    let new_bin_bonus = if bin_residual == bin_capacity {
        let waste = post;
        20.0 - 0.5 * waste - 18.0 * (fitting_bins_count as f64).recip()
    } else {
        0.0
    };
    score += new_bin_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (C/8 bands)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let eighth = cap / 8.0;
    let band = (pr / eighth).floor() as i32; // 0..8

    // Dead-space penalty: residuals in the "unusable sliver" bands
    // (very small, unlikely to fit typical items) get extra penalty.
    let sliver_threshold = 12.0;
    if pr <= sliver_threshold {
        score += 40.0 * (sliver_threshold - pr) / sliver_threshold;
    }

    // Reward residuals in "harmonic" classes: multiples of common item
    // sizes (10, 20, 25, 50) are reusable by future items.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if r % m == 0 && r > 0 {
                b += 6.0;
            }
        }
        b
    };
    score -= harmonic_bonus(post_residual);

    // Integer-division threshold on post_residual: which next-item class fits?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can chain with the lookahead: reward by slack quality
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.1 * slack;
            // Extra reward for perfect chain (residual exactly consumed next)
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Lookahead won't fit here: penalize proportionally
            score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just fill as tightly as possible
        score -= 5.0;
    }

    // Modulo coupling between item_size and capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if item_size % quarter == 0 {
        score -= 4.0; // item divides capacity harmonically
    }
    if item_size > half && post_residual < item_size / 2 {
        score += 8.0; // large item leaving awkward remainder
    }

    // Band-based dead-space shaping: penalize odd bands (non-harmonic)
    if band >= 0 && band <= 8 {
        let band_penalty = match band {
            0 => 30.0,           // 0..12.5 : nearly dead
            1 => 10.0,           // 12.5..25
            2 => 5.0,
            3 => 0.0,
            4 => -3.0,           // ~half full bin: healthy
            5 => 0.0,
            6 => 2.0,
            7 => 4.0,
            _ => 0.0,
        };
        score += band_penalty;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline, but allow it when open bins
    // would create heavy dead space or when mean residual is very low.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // low mean residual -> bins nearly full
        let base = 18.0;
        // Prefer new bin if existing bins are too full (mean residual small)
        // relative to current item needs.
        score = base + 30.0 * pressure - if next_item_size > 0 && next_item_size >= 40 { 5.0 } else { 0.0 };
        // Late in stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
    }

    // Mild preference to fill bins with high residual when many bins open
    score -= 0.05 * bin_residual as f64 * (open_bins_count as f64 / 10.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    } else {
        score -= 4.0; // generous leftover is reusable
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual exactly matches the next item (lookahead pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 4.0 * open_bins_count as f64;
        // But allow new bin if all open bins would leave tight dead space.
        if post_residual == bin_capacity - item_size && post_residual > 30 {
            score -= 15.0;
        }
    }

    // Mean residual coupling: prefer bins near the mean residual (balanced usage).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Late-stream tightening: penalize waste more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: make an empty bin moderately attractive,
    // but let a perfect 2-step lookahead match beat it.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = 45.0;
        // Late in the stream, prefer closing out open bins rather than spawning.
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
        // If many bins already open, discourage opening yet another.
        score += 3.0 * (open_bins_count as f64).sqrt();
        return score;
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect chain: post_residual exactly fits the next item -> huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Near-perfect chain: next item fits with small slack.
        else if post_residual >= next_item_size {
            let slack = post - nxt;
            // Reward proportional to how snugly the next item fits.
            score -= 40.0 * (1.0 - slack / 100.0);
        } else {
            // Next item will NOT fit here: dead space risk.
            // Penalize more when the leftover is small and unusable.
            let unusable = nxt - post;
            score += 0.8 * unusable;
            // Extra penalty if leftover is below the minimum item size (1..100 range):
            // tiny leftovers are almost surely dead space.
            if post_residual < 10 {
                score += 25.0;
            }
        }
    } else {
        // Last item: prefer the fullest possible packing.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are good targets
    // for aggressive filling; bins looser than the mean get a mild penalty
    // so we don't spread items thinly.
    let dev = (post_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Reward tighter fits generally (small post_residual is good).
    score -= 0.1 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic time horizon
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits strongly: fraction of bin consumed by this item
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item can use.
    // Items can be as small as 1, but small dead space is still wasteful;
    // weight dead space more heavily later in the stream (less chance to fill it).
    let dead = post_residual as f64;
    score += dead * (0.3 + 0.7 * progress);

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leave it well-shaped
            let leftover = post_residual - next_item_size;
            score -= 8.0 - 0.1 * leftover as f64;
        } else {
            // next item won't fit here; mild penalty for blocking useful space
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: encourage consolidating into bins with low residuals
    // (bins whose residual is close to mean residual are "average" candidates;
    //  prefer placing into bins with residual near item_size to keep mean low)
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * diff;

    // Penalize opening a new bin, unless the item is large and no bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (fitting_bins_count <= 2 && fit_ratio < 0.5);
        if poor_fit_everywhere {
            score -= 20.0; // opening a bin is reasonable
        } else {
            score += 15.0 + 10.0 * (1.0 - progress); // early stream: reuse bins
        }
    }

    // Slight preference for bins that would end with residual in "usable" bands
    // (multiples-friendly zones where future small items likely fit)
    if post_residual >= 10 && post_residual <= 40 {
        score -= 2.0;
    }

    // Mild open-bins pressure: with many bins open, discourage fragmentation
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0, 1]

    // Progress-modulated polynomial: early on, prefer tight fits strongly;
    // later, tolerate larger residuals slightly more.
    let phase = progress * std::f64::consts::PI;
    let w_early = 0.5 * (1.0 + (phase).cos());      // ~1 early, ~0 late
    let w_late = 0.5 * (1.0 - (phase).cos());       // ~0 early, ~1 late

    // Cubic smooth term penalizing mid-range residual (dead space), rewarding near-zero residual.
    let cubic = x * x * (3.0 - 2.0 * x);            // smoothstep in [0,1]
    score += 12.0 * w_early * cubic;
    score -= 6.0 * w_late * (1.0 - cubic) * (1.0 - cubic);

    // Interaction: residual vs mean residual (relatively tighter bin is favored).
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        score += 4.0 * (rel - 1.0) * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 + 8.0 * w_early;
    }

    // Lookahead coupling: if next item fits exactly into post-residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / cap);
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize small residuals that strand space.
        score += 5.0 * w_late * (1.0 - x);
    }

    // Mild pressure to close bins when many are open.
    score += 0.5 * open_bins_count as f64 * x * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: class 0 (perfect fit) heavily rewarded.
    let class = (post_residual % 10) as f64;
    score -= (10.0 - class) * 1.5; // residual divisible by 10 is "harmonic" -> bonus

    // Dead-space penalty: small unusable residual (< next item and < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // If next item fits into post_residual, reward keeping room (chain fit)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // extra reward if next item exactly consumes remainder
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0; // remainder blocks lookahead item
    }

    // Tightness reward: fraction of bin used by this placement
    let fill = item_size as f64 / cap;
    score -= fill * 15.0;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalize opening
    // a new bin when many bins exist and residual is large (wasteful).
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
        // but if no open bin fits well (all fits leave big waste), allow it
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late stream: prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // Penalize bins far from mean residual (keeps pool homogeneous)
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 3.0;

    // Integer-division threshold: post_residual in [20,30) is a good shelf
    let shelf = post_residual / 20;
    match shelf {
        0 => score += 2.0,   // tiny remainder
        1 => score -= 3.0,   // 20..40: useful
        2 => score -= 1.0,   // 40..60
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items are "dead space". Penalize them heavily.
    if post_residual > 0 {
        let dead_threshold = 10.0 + 0.3 * mean_residual;
        if (post_residual as f64) < dead_threshold {
            // Non-linear penalty: smaller unusable gap => larger penalty.
            let gap = dead_threshold - post_residual as f64;
            score += 40.0 + 6.0 * gap.sqrt() + 0.5 * gap;
        }
        // Perfect fit is heavily rewarded.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Coupling with open bins count: pressure to close bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 2.0 * bin_pressure * (0.5 + progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward bins whose post residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.2 * next_item_size as f64;
        } else if post_residual > 0 {
            // Residual too small for the known next item => extra dead-space penalty.
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; escalate with open bins pressure.
        score = 25.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin is flexible for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal waste
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score -= 6.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0) * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect lookahead fit: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits with small slack: strong reward
        if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 12.0;
        }
        // Next item would NOT fit here: penalize leaving a bin that strands space
        if next_item_size > post_residual {
            score += 4.0;
        }
    } else {
        // Last item: pure waste minimization, slight bonus for tight fit
        score -= 2.0;
    }

    // Relative-to-mean coupling: bins tighter than average are precious
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        if pr < mean_residual {
            score -= 0.5 * (mean_residual - pr) / mean_residual;
        } else {
            score += 0.3 * (pr - mean_residual) / mean_residual;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_penalty = 8.0 + 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Opening a fresh bin keeps a perfect 2-step chain possible
            open_penalty -= 5.0;
        }
        score += open_penalty;
        // If many open bins can fit, definitely prefer them over a new bin
        if fitting_bins_count > 0 {
            score += 5.0 * (fitting_bins_count as f64).min(4.0);
        }
    }

    // Small residual dead space penalty (unusable fragments)
    if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness reward: fraction of bin used by this placement
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fit_ratio;

    // Lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tight = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - chain_tight / bin_capacity as f64);
    }
    // Penalize if next item almost fits but not quite (dead space risk)
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins have poor residuals or the item is large relative to residuals
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 60.0;
        // Less penalty late in the stream (fewer future consolidation chances)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * progress;
        // If item is large, a fresh bin is more attractive
        score -= 0.5 * item_size as f64;
        // If open bins have plenty of room on average, discourage new bin
        score += 0.3 * mean_residual;
        // Many open bins: slightly discourage adding another
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer filling bins whose residual is already small (best-fit coupling)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Small penalty for very fragmented leftover space
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Waste matters more as the stream advances (less room to recover dead space).
    let waste_weight = 0.5 + 2.5 * progress * progress;
    score += waste_weight * (pr * pr) / cap;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            let exact = 1.0 - (gap / cap).powi(2);
            score -= 6.0 * exact;
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 2.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * progress;
    }

    // Many open bins: prefer filling existing ones over spreading items.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr / cap);

    // Deviation from mean residual: prefer bins whose remaining space stays coherent.
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: keep it slightly unattractive unless post_residual of
    // existing bins is hopeless (large pr means poor fit anyway).
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "waste classes".
    let residue_class = (post_residual % 10) as f64;
    // Dead-space penalty grows super-linearly for awkward residues (1,2,9 => hard to fill).
    let awkward = match post_residual % 10 {
        1 | 2 | 9 => 2.5,
        3 | 4 | 7 | 8 => 1.2,
        5 | 6 => 0.6,
        _ => 0.0, // 0: perfect fit class
    };
    score += residue_class * awkward;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Integer-division thresholds on post_residual: small leftovers are valuable
    // only if the lookahead item can use them; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // bin remains usable for the next item
        } else {
            score += (post_residual as f64) * 0.35; // dead space the next item can't use
        }
        // Exact chain fit: post_residual == next_item_size is a perfect follow-up.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: minimize leftover only.
        score += (post_residual as f64) * 0.1;
    }

    // Capacity-fraction coupling: reward bins whose fill ratio lands in "good" bands.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill > 0.75 {
        score -= 10.0 * fill;
    } else if fill < 0.35 {
        score += 5.0 * (0.35 - fill);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post_residual would be huge).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual > 40 {
            score += (post_residual as f64 - 40.0) * 0.5; // but avoid huge waste
        }
    }

    // New-bin candidate: keep its baseline near mid-range; opening a bin is
    // sensible when mean residual across open bins is already tight.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.3 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            // item + next item can never share: new bin is fine
            score -= 10.0;
        }
    }

    // Stream progression: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (post_residual as f64) * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps nonlinearly.
    // A gap is "dead" if it is smaller than the smallest plausible item (<= 10),
    // and partially dead if it can only host very small items.
    let dead_zone: f64 = 10.0;
    if (post_residual as f64) < dead_zone {
        // Completely wasted space: harsh quadratic penalty.
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 2.0;
    } else if post_residual <= 20 {
        // Marginal gap: only tiny items can use it; moderate penalty.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits: the tighter the fit, the better.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 15.0;

    // If this bin is the ONLY one that fits, strongly prefer using it
    // rather than opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening new capacity is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial reward for keeping a usable gap for the known next item.
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap cannot host the next item: penalize proportionally to how dead it is.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Prefer bins whose residual is below average (tighter bins close out sooner).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is large
    // or the current stream is early (amortize the new bin over many items).
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
        if item_size >= 50 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 500.0; // exact 2-step chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post_residual too small for next item: dead-space penalty scaled by deadness
        score += 0.6 * post_residual as f64;
    }

    // Penalize bins whose residual is already far below mean (wasted bin)
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Early stream: be conservative, prefer tighter fits; late stream: pack aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    // Slight preference to fill existing bins rather than open new ones
    if bin_residual != bin_capacity {
        score -= 5.0;
    } else {
        score += 20.0; // new-bin candidate penalty unless lookahead strongly favors it
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual shrinks to nearly nothing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            let overflow = next_item_size - post_residual;
            score += overflow as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins below mean residual (more filled bins)
    // so that emptier bins stay available for large future items.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Time horizon: early in the stream, be conservative about fragmenting bins;
    // late in the stream, prioritize closing bins out (tight fits matter more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64) * 0.5;

    // Many open bins: encourage consolidation into existing bins rather than opening more.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin is attractive only when the item is large
    // or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        // Base penalty makes open bins preferred unless tight-fit rewards overcome it.
        score += 15.0 - large_item_bonus;
        if item_size > 50 {
            score -= 10.0;
        }
        // If many bins are open and item is small, opening a new bin is wasteful.
        if item_size < 30 && open_bins_count > 3 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, large residuals are tolerable (bins can still be filled);
    // late in the stream, dead space becomes costly, so amplify it smoothly.
    let progress_poly = 1.0 + 2.0 * progress * progress + 3.0 * progress * progress * progress;
    score += norm_pr * norm_pr * cap * progress_poly * 0.5;

    // Penalize residuals that cannot fit the lookahead item (smooth quadratic gap)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += gap * gap / cap * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 50.0 * (1.0 - norm_pr);
    }

    // New-bin candidate handling: empty bin should be attractive when it offers
    // a clean full residual, but not so attractive that we hoard bins early.
    let is_new_bin = bin_residual == bin_capacity && post_residual < bin_residual;
    if is_new_bin {
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        // favor new bins more when mean residual across open bins is small (poor fits)
        let mean_tight = (mean_residual / cap).max(0.0);
        let openness = (0.4 + 0.6 * progress) * scarcity * (1.0 + mean_tight);
        score -= 10.0 * openness * (0.5 + norm_pr);
        // slight penalty late in stream to avoid bin explosion
        score += 5.0 * progress * progress;
    }

    // Mild preference for bins whose residual is close to mean (balance load)
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (0.5 + 0.5 * progress);

    // Small smooth reward for filling more than half the bin
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill * (1.0 - progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: items whose leftover falls into
    // "small dead zones" (1..=9) are penalized heavily since that space is
    // nearly unusable for typical items.
    if post_residual > 0 && post_residual <= 9 {
        score += 25.0 - post_residual as f64;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 are
    // "harmonic" with typical item sizes and get rewarded.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: classify post_residual into coarse bands.
    let band = post_residual / 25; // 0,1,2,3
    score += band as f64 * 3.0;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            if next_left % 10 == 0 {
                score -= 12.0;
            }
            score += next_left as f64 * 0.3;
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: brand-new empty bin. Prefer it only when no open bin
    // offers a tight fit; penalize opening new bins when mean residual is healthy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit_exists = (mean_residual - item_size as f64).abs() < 15.0
            && mean_residual >= item_size as f64;
        if tight_fit_exists {
            score += 30.0;
        } else {
            score -= 5.0 + 10.0 * (1.0 - progress);
        }
        // Reward new bins when open bins are all nearly full.
        if mean_residual < 20.0 {
            score -= 20.0;
        }
    }

    // Favor filling bins that are already committed (larger item fraction used).
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Mild preference for fewer open bins when residuals align harmonically.
    if open_bins_count > 3 && post_residual < 15 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item are dead weight; penalize them quadratically.
    let min_item = 1u32;
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 * (post_residual as f64) * (post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fill is highly desirable.
        score -= 25.0;
    } else {
        // Mild preference for tighter fits (small post_residual).
        score += 0.5;
    }

    // Reward bins whose residual after placement cannot host the next item
    // only if the next item fits better elsewhere; penalize blocking the
    // lookahead item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Bin stays useful for the lookahead item: mild bonus.
            score -= 3.0;
        } else if next_item_size <= bin_residual {
            // This placement destroys the only space the next item could use.
            score += 2.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already
    // open relative to stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 8.0 + 2.5 * (open_bins_count as f64) * (1.0 + 0.5 * (1.0 - progress));
        // If many fitting bins exist, opening a new bin is rarely right.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
        }
    } else {
        // Using an existing bin reduces fragmentation pressure slightly.
        score -= 1.0;
    }

    // Coupling with mean residual: prefer bins whose post_residual stays
    // near the mean (keeps residual distribution homogeneous, easier fits).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits strongly (small post_residual is good).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + 5.0 * (6.0 - post_residual as f64);
    } else {
        // Penalize residual that is too small to fit typical items later
        let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
        score += 2.0 * dead;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0); // mild reward for chainable fits
        } else {
            // next item cannot follow here; penalize proportionally to wasted chain potential
            score += 0.5 * ((next_item_size - post_residual) as f64).min(30.0);
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves a bad leftover
    if bin_residual == bin_capacity {
        let base = 30.0;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base + 20.0 * progress;
        if post_residual == 0 {
            score -= 1000.0; // impossible for new bin, keep safety
        }
        // if item leaves a residual matching next item, new bin still attractive
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 5 {
            score -= 60.0;
        }
    }

    // Slight preference for fewer open bins
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are gold: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.35;
        } else {
            // Reward bins where next item also fits snugly.
            let nxt_left = post_residual - next_item_size;
            if nxt_left < 10 {
                score -= 9.0;
            }
        }
    } else {
        // Last item: just dump it into the tightest fit possible.
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a needless bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }
    // Many alternatives: slight penalty so best-fit logic dominates.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Global residual pressure: when mean residual is low, conserve open-bin space.
    let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += pressure * (post_residual as f64) * 0.25;

    // Early stream: prefer consolidating into few bins; late stream: be greedy-tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * open_bins_count as f64;
    score -= progress * 4.0 * tightness;

    // New-bin candidate: only attractive when item is huge and nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 / bin_capacity as f64).powi(3);
        let poor_fits = if fitting_bins_count > 0 {
            (post_residual as f64 / bin_capacity as f64)
        } else { 1.0 };
        score += 20.0 - 22.0 * desperation * (1.0 - 0.5 * poor_fits);
        score += open_bins_count as f64 * 2.0;
    } else {
        // Existing bin with big residual: mildly prefer reusing large empty space.
        score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // Waste-ratio term: penalize fraction of bin sacrificed.
    score += (item_size as f64 / bin_residual as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: tight fits favored
    let mut score = pr as f64;

    // Non-linear polynomial coupling with stream progress
    let p = progress;
    // As stream progresses, penalize large residuals more strongly (quartic growth)
    let poly = x * x * (1.0 + 3.0 * p) - 2.0 * x * x * x * (1.0 + p * p) + 1.5 * x * x * x * x * p;
    score += 20.0 * poly * cap;

    // Reward near-perfect fits smoothly
    let tightness = 1.0 - x;
    score -= 15.0 * tightness * tightness * tightness * cap;

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let fill = nx / pr.max(1.0) as f64;
            score -= 12.0 * fill * fill * (1.0 + p);
        } else {
            // next item won't fit: penalize smoothly proportional to leftover dead space
            score += 6.0 * (nx - pr) / cap * (1.0 + p);
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + p);
    } else if fitting_bins_count > 1 {
        // spread mild penalty among alternatives via count
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean residual context: placing in a bin below mean residual is slightly favored
    score -= 3.0 * (mean_residual - pr) / cap;

    // New-bin candidate: smooth penalty that decays with progress so late stream
    // prefers reusing open bins
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - 0.6 * p) * (1.0 + (open_bins_count as f64).ln().max(0.0) * 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 8 harmonic classes of residual space

    // Penalize awkward classes: residuals that are too small to be useful.
    let class_penalty = match class {
        0 => 0.0,                       // near-perfect fit, excellent
        1 => 6.0,                       // tiny dead space, hard to reuse
        2 | 3 => 2.5,                   // medium-small, moderately reusable
        _ => 0.0,                       // large residual, flexible
    };
    score += class_penalty;

    // Reward when the next item fits exactly into the post residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item fills the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * fill;
        } else {
            // Next item cannot use this residual: penalize small wasted leftovers more.
            if post_residual < 10 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Harmonic class via integer division thresholds on post_residual.
    let div_class = post_residual / 25; // 0..4
    match div_class {
        0 => score += 4.0,   // residual < 25: mostly dead space
        1 => score -= 1.0,   // 25..49: can host small items
        2 => score -= 2.0,   // 50..74: good flexibility
        _ => score -= 3.0,   // 75+: very flexible
    }

    // Slight preference to keep mean residual balanced across open bins.
    let deviation = post_residual as f64 - mean_residual;
    score += 0.05 * deviation.abs();

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    // (i.e., this call is for the empty bin and existing residuals are all small).
    if bin_residual == bin_capacity {
        // Opening a new bin is justified if the item would leave a bad class elsewhere.
        let would_be_bad = post_residual == 0 || (post_residual < 20 && post_residual > 0);
        if would_be_bad || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 15.0; // prefer reusing an open bin with decent residual
        }
    }

    // Modulo arithmetic bonus: residual divisible into clean chunks of common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: post_residual in small unusable gaps is heavily penalized.
    // Residuals below the minimum item size (1) are impossible, but tiny gaps (< 15)
    // are statistically hard to fill later; penalize superlinearly.
    let pr = post_residual as f64;
    if post_residual < 15 && post_residual > 0 {
        score += (15.0 - pr) * 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward leaving gaps that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 5.0 + 0.5 * (pr - n).min(20.0);
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += 4.0 * (n - pr).min(30.0);
        }
    }

    // Open bins pressure: with many open bins, prefer consolidation into existing bins
    // (penalize new-bin candidate); with few open bins, opening is cheaper.
    let bin_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 8.0 + 0.6 * bin_pressure;
        // But if no existing bin fits well (this is the only fitting option), soften.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward using it, especially when many bins are open.
        score -= 2.0 + 0.15 * bin_pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Slight preference early in the stream to keep bins tight (build good structure),
    // mild relaxation later when closing out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * (1.0 - progress);

    // Prefer bins whose residual is near the mean (keep residual distribution tight),
    // which preserves future packing flexibility.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild overall preference for tighter existing bins.
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too; reward proportionally to how much would remain.
            let chain_residual = post_residual - next_item_size;
            score -= 8.0 + 0.5 * (bin_capacity as f64 - chain_residual as f64);
        } else {
            // Next item cannot fit in leftover: penalize dead space.
            score += 6.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 5.0;
    }

    // Tightness reward: small absolute post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Penalize bins whose residual is far above the mean (wasteful bins).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Late in the stream, avoid opening new bins; early, allow exploration.
    score += 15.0 * progress;

    // Slight penalty when many bins are open, encouraging consolidation.
    score += 0.3 * open_bins_count as f64;

    // Brand-new empty bin candidate: neutral baseline; discourage unless item is large.
    if bin_residual == bin_capacity {
        score += 20.0 - 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), with non-linear emphasis.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Penalize large dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny sliver: acceptable waste
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + item_size as f64 * 0.3;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste: mild bonus scaled by fit quality
            let nl = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - nl / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize bins that would strand the lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0) * 0.5;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins to consolidate; few open bins -> opening new is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (open_bins_count as f64).ln().max(0.0) * mean_residual / bin_capacity as f64;
    score += consolidation * 6.0;

    // Time horizon: late in the stream, avoid opening new bins even harder.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, adjusted by state.
        score = 45.0 + consolidation * 4.0 + progress * 20.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, new bin is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // room for lookahead in fresh bin
        }
    } else {
        // Late stream: extra reward for closing out bins nearly perfectly.
        if post_residual <= 5 {
            score -= 10.0 * (0.5 + progress);
        }
        // Prefer bins whose residual is close to item (best-fit refinement).
        let pre_gap = (bin_residual - item_size) as f64;
        score += pre_gap * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, weighted by a smooth polynomial in stream progress
    let mut score = pr * (0.9 + 0.4 * t * t);

    // Non-linear coupling: squared normalized residual interacts with progress
    score += 30.0 * norm_pr * norm_pr * (1.0 - t);

    // Penalize residuals that are large but awkward (near mid-range) — polynomial bump
    let mid = norm_pr - 0.5;
    score += 20.0 * mid * mid * (1.0 - norm_pr * norm_pr);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 15.0 * (1.0 - norm_pr).powi(3) * t;

    // Lookahead: if next item fits in post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + t);
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual coupling: penalize bins far above mean residual (poor consolidation)
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: neutral-ish score, slightly worse early, better late
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.8 * t) - 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (dead-space classes)
    let res_class = post_residual % 10;
    score += (res_class as f64) * 0.35;

    // Integer-division thresholds on post_residual: very small residuals are "locked" bins
    if post_residual < 10 {
        score -= 12.0; // near-perfect fill, excellent choice
    } else if post_residual < 20 {
        score -= 6.0;
    } else if post_residual > 60 {
        score += 8.0; // large leftover wastes a bin slot
    }

    // Capacity fraction coupling: fraction of bin filled by this placement
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Lookahead harmonic: does next_item_size divide into post_residual nicely?
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_frac = post_residual as f64 / next_item_size as f64;
        // reward when next item leaves a small class remainder too
        let next_post = post_residual - next_item_size;
        let next_class = next_post % 10;
        score -= 10.0 - (next_class as f64) * 0.5;
        // exact division bonus (harmonic divisibility)
        if post_residual % next_item_size == 0 {
            score -= 5.0;
        }
        let _ = fit_frac;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; residual is dead unless small
        if post_residual >= 20 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only open when no open bin fits, or mean residual is very tight
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // forced open
        } else {
            // opening a fresh bin while others fit is usually wasteful
            score += 25.0;
            // but if all fitting bins would leave big dead space, opening is fine
            if post_residual < 15 {
                score -= 40.0;
            }
        }
        // early stream: allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Mean residual coupling: high mean residual -> prefer bins above average fill
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Open bins pressure: many open bins -> consolidate
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        // A residual gap is "dead" if no plausible future item (min size 1..~20) can use it well.
        // Treat gaps below 10 as fully dead; gaps 10..25 partially dead.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 2.5;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: prefer tighter bins when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 4.0);
    score += pressure * 1.5;

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0 - gap as f64;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot use the leftover, mildly penalize large leftovers.
    else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate: neutral baseline; only prefer it when no open bin offers
    // a decent fit (dead-space-heavy placements already score high above).
    if bin_residual == bin_capacity {
        // Slight preference for new bin early when open bins are numerous and fragmented.
        score = 100.0 - post_residual as f64 + pressure * 2.0;
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    score = (post_residual as f64).powf(1.35);

    // 2-step lookahead: reward when the next item exactly fills the leftover space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: this bin becomes exactly full next step
        } else if next_item_size > 0 && post_residual > next_item_size {
            // next item can also fit here afterwards: mild reward proportional to slack
            score -= 8.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use the leftover: penalize dead space more strongly
            score += 6.0 + 0.25 * post_residual as f64;
        }
    }

    // Relative-to-mean residual coupling: bins with much more slack than average
    // should absorb large items; bins below average slack are precious.
    let rel = post_residual as f64 - mean_residual;
    score += 0.5 * rel;

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin wastes capacity; make it attractive only
    // when current item is huge and leftover would be unusable for the next item.
    if bin_residual == bin_capacity {
        let waste_now = (bin_capacity - item_size) as f64;
        let lookahead_bad = next_item_size > 0 && waste_now < next_item_size as f64;
        if lookahead_bad && item_size >= 60 {
            score -= 25.0; // open fresh bin rather than fragment
        } else {
            score += 15.0 + 0.3 * waste_now; // default: prefer existing bins
        }
    }

    // Late in the stream, consolidate aggressively (fewer bins at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with more slack when many bins are open.
    score -= 0.05 * (bin_residual as f64 - item_size as f64) / (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual becomes small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: discourage opening a new bin unless current
    // placement would leave a lot of unusable space and the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_placed_elsewhere = (fitting_bins_count == 0) as i32 as f64;
        let bonus = 15.0 * (1.0 - progress) * (1.0 - waste_if_placed_elsewhere);
        score += bonus + item_size as f64 * 0.1;
    }

    // Mild preference for closing bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 0.15;

    // Spread awareness: many open bins -> prefer filling existing ones more.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tighten fits more aggressively (waste compounds).
    let progress_coupling = (post_residual as f64 / bin_capacity as f64)
        * (progress * progress * (1.0 - progress) * 4.0) // smooth bump peaking mid-stream
        * 12.0;
    score += progress_coupling;

    // Reward near-perfect fits with a quadratic bonus on small residuals.
    let r = post_residual as f64;
    score -= 6.0 * (1.0 - r / bin_capacity as f64).powi(4);

    // Penalize bins whose residual deviates far below the mean (fragmented bins)
    // with a smooth saturating term.
    let dev = (mean_residual - bin_residual as f64).abs();
    score += 0.5 * (dev / (mean_residual + 1.0)).powi(2).min(4.0);

    // Last-chance bin: strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement;
    // if the next item is large and this bin would be nearly full, that's fine too.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving awkward gaps that the next item cannot use,
            // scaled smoothly by how close the gap is to being useless.
            let gap_uselessness = (post_residual as f64 / next_item_size as f64).min(1.0);
            score += 3.0 * gap_uselessness * (1.0 - gap_uselessness);
        }
    }

    // Mild pressure to consolidate when many bins are open: prefer filling
    // existing bins over spreading out (smooth in open_bins_count).
    if bin_residual != bin_capacity {
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate gets a mild fixed penalty so it only wins when
    // existing fits are genuinely poor (its large post_residual already hurts).
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space
    // modulo common item-size buckets (capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement
    let frac = pr / cap;

    // Dead-space penalty: leftover too small for the smallest plausible item
    // (items >= 1, but typical "usable" threshold ~ capacity/10).
    let tiny_threshold = cap / 10.0;
    if pr < tiny_threshold && pr > 0.0 {
        // Nearly-full bin is excellent: reward heavily (subtract).
        score -= 25.0 * (tiny_threshold - pr) / tiny_threshold;
    }

    // Harmonic class: post_residual divisible by common chunk sizes
    // (10, 20, 25, 50) are more reusable — reward alignment.
    let pr_u = post_residual;
    if pr_u > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50] {
            if pr_u % m == 0 {
                harmony += 4.0;
            }
        }
        score -= harmony;
    } else {
        // Perfect fill
        score -= 30.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Chain-fit reward, scaled by tightness of the chained fit
        let chain_tight = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - chain_tight);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that cannot host the next item
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // unattractive unless no good open-bin fit exists. Penalize by mean
    // residual context: if open bins are crowded (mean residual low),
    // new bin becomes more acceptable.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Relax penalty when open bins are nearly exhausted
        let crowded = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score -= 40.0 * (1.0 - crowded).min(1.0);
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for tighter fits overall
    score += 0.1 * (bin_residual - item_size) as f64 * 0.0; // no-op guard
    score += 0.05 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps too small for the lookahead item are also dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins that can still fit the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (15.0 + 3.0 * open_bins_count as f64);

    // Late in the stream, tighten up: prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += new_bin * 20.0 * progress;
    score -= (1.0 - new_bin) * 5.0 * progress;

    // Slight preference for bins below mean residual (fill emptier bins first
    // is bad; prefer tighter bins => penalize bins with residual above mean).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Slack left for the next item: reward proportionally to tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize wasted potential
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward bins tighter than the mean (good packing), penalize loose bins
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    } else if fitting_bins_count > 1 {
        score += 10.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize tiny unusable residuals (dead space) unless next item matches
    if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 50.0;
    }

    // Early in stream: prefer filling existing bins less aggressively (keep flexibility)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // New-bin candidate: only attractive when current item leaves very large residual
    // that nothing else will use, or no bins fit well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else if post_residual > 70 {
            score -= 80.0;
        } else {
            score += 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small to be useful later (below typical item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < item_size {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count == 2 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 18.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting a versatile residual.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Global state: prefer filling bins when mean residual is high (bins are loose).
    score += 0.35 * (mean_residual - post_residual as f64);

    // Time horizon: early on, be picky (prefer new bins for bad fits); late, pack aggressively.
    if progress < 0.3 {
        score += 10.0 * (1.0 - progress / 0.3) * (post_residual as f64 / bin_capacity as f64);
    } else {
        score -= 8.0 * progress * tightness;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item fits poorly everywhere else
        // or when many open bins already have lots of space.
        let poor_fit = (post_residual as f64) > 0.45 * (bin_capacity as f64);
        if poor_fit && fitting_bins_count >= 1 {
            score -= 22.0 + 15.0 * progress;
        } else {
            score += 30.0;
        }
        // Slight preference for opening bins when few are open (cheap now, useful later).
        if open_bins_count < 4 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: wasted space, weighted non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial coupling of normalized post_residual with progress
    score += 40.0 * pr_norm * pr_norm * (0.3 + progress);

    // Reward tight fits (small post_residual) non-linearly
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * tightness;

    // Penalize residuals that cannot hold the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // usable residual: mild reward scaled by how well it fits
            let slack = pr - nxt;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // dead space relative to lookahead
            let gap = nxt - pr;
            score += 15.0 * (gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Slight penalty for contributing to bin proliferation
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Encourage balancing toward mean residual (smooth term)
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: prefer it only when residual waste would be large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions (quarter classes)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Integer-division thresholds: dead space penalty grows in discrete steps
    let dead_class = post / 10; // 0..10 classes
    score += (dead_class as f64).powi(2) * 0.5;

    // Modulo arithmetic on post_residual: bins whose residual is "wasteful"
    // (not a multiple of small item sizes) get penalized
    if post > 0 {
        let waste_mod = post % 10;
        score += waste_mod as f64 * 0.3;
    }

    // Perfect fit (residual lands on a harmonic multiple of 10) heavily rewarded
    if post % 10 == 0 && post < half {
        score -= 8.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 4.0;
    }

    // Exact fill is ideal
    if post == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post >= next_item_size {
        if post == next_item_size {
            score -= 15.0;
        } else if post % next_item_size == 0 {
            score -= 6.0;
        } else {
            score -= (post - next_item_size) as f64 * 0.05;
        }
    } else if next_item_size > 0 && post < next_item_size {
        // bin closes fully, that's fine
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.8;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 10.0; // existing bins too full anyway
        }
        // early in stream, opening fresh bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Prefer filling bins below mean residual (more full than average)
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 2.0;
        }
    }

    // Slight preference for keeping fewer open bins when progress is late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible item (size 1..~20)
    // or cannot hold the lookahead item.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 60.0 * (10.0 - gap) / 10.0; // tiny slivers are worst
    }
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0; // gap can't fit the next item -> likely dead space
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0; // gap remains usable for the lookahead item
    }

    // Reward tight fits (perfect or near-perfect packing).
    let tightness = 1.0 - gap / bin_capacity as f64;
    score -= 40.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and mean residual is healthy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and open bins grow.
        score += 15.0 + 8.0 * open_bins_count as f64 + 20.0 * progress;
        // But if mean residual is very low (all bins nearly full), new bin is fine.
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    } else {
        score += 2.0 * open_bins_count as f64 * 0.1;
    }

    // Slight preference for bins whose residual is close to the item (best-fit core).
    score += 0.5 * ((bin_residual - item_size) as f64).abs() * 0.0; // no-op guard
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match of post_residual with next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual == next_item_size {
            score -= 60.0; // exact two-step fit: item + next item perfectly fill bin
        } else if post_residual > next_item_size {
            // next item could also fit here: mild reward proportional to closeness
            score -= 12.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // dead space relative to what's coming: penalize small unusable leftovers
            score += 8.0 * (1.0 - diff / (bin_capacity as f64));
            if post_residual < 10 {
                score += 15.0; // nearly-dead space
            }
        }
    } else {
        // last item: prefer tightest fit
        score -= 5.0;
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual is close to the item (tight packing),
    // discourage dumping into bins far above average residual unless it's a great fit.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 6.0; // leaves much less than average: good consolidation
        } else if rel > 1.5 {
            score += 4.0; // leaves much more than average: fragmenting
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless residual after placement is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * post_residual as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when this bin would be left with unusable scraps.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scraps = post_residual > 0 && post_residual < 10;
        if scraps && next_item_size > post_residual {
            score -= 20.0; // avoid killing this bin with dead space
        } else {
            score += 30.0 + 40.0 * progress; // generally prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits with a non-linear squash of fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Lookahead (k=2): if the next item fits into the post-residual, reward this bin;
    // scale the reward by how snugly the next item couples to the leftover space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 + 10.0 * snug;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that the next item cannot use: penalize proportionally to dead space.
        score += 0.08 * (post_residual as f64) * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance pressure: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible, handled by post_residual term).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Crowding bonus: with many open bins, prefer consolidating into existing ones.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 1.5 * crowding.min(4.0);
    }

    // Global slack: when mean residual across bins is high, discourage leaving more slack;
    // when bins are nearly full overall, slight bonus for any existing bin.
    if bin_residual < bin_capacity {
        score -= 0.03 * mean_residual;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively (tolerate small residuals).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 3.0 * (post_residual as f64 / bin_capacity as f64);
    score -= t * 2.0 * fill;

    // New-bin candidate handling: an empty bin is only attractive for large items
    // that would leave a very poor fit elsewhere.
    if bin_residual == bin_capacity {
        let openness = 1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        score += 5.0 + 10.0 * openness - 14.0 * fill * fill;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: post_residual penalized more as stream progresses
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits with smooth term
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Dead-space penalty coupled with lookahead: if next item can't use residual, penalize smoothly
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        score += 15.0 * (gap / cap) * (1.0 + progress);
        // Bonus if next item fits exactly into post residual
        let fits_next = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        score -= 20.0 * fits_next * norm_pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many open bins (encourage consolidation)
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Coupling with mean residual: bins below mean residual are good targets
    score += 0.1 * (mean_residual - pr);

    // New-bin candidate: penalize so we prefer existing bins unless fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (waste < 10) are excellent; large leftovers
    // that no future item can use are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Fractional capacity classes: reward post residuals that are small
    // multiples of common item granularity (capacity / 8 lattice).
    let lattice = cap / 8.0;
    let k = (prf / lattice).floor();
    let frac = prf - k * lattice;

    // Penalize distance to the lattice: residuals near multiples of 12.5
    // tend to be reusable; ragged residuals are not.
    score += 0.6 * frac;

    // Dead-space cliff: post_residual < smallest plausible item (10) is waste.
    if pr < 10 {
        score -= 15.0; // perfect fill, strongly favored
    } else if pr <= 20 {
        score -= 5.0;  // near-perfect fill
    } else if pr > 50 {
        score += 8.0;  // large leftover: wasteful unless new bin
    }

    // Modulo classes of post_residual: leftovers divisible by 5 are more
    // likely to be exactly consumed by future items.
    if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize new-bin alternative implicitly by
    // lowering this bin's score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when all
    // open bins would leave large dead space. Give it a moderate baseline.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.1 * mean_residual - (fitting_bins_count as f64) * 5.0;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: keep space fresh
        }
        return score;
    }

    // Tightness coupling: reward placing into bins whose residual is close
    // to the item (best-fit flavor), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * tight * (0.5 + 0.5 * progress);

    // Congestion: many open bins with high mean residual -> consolidate,
    // favor filling existing bins harder.
    if open_bins_count > 3 && mean_residual > cap * 0.4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are heavily penalized (non-linearly).
    let dead_zone = 25.0;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 0.9;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 35.0;
    }

    // Tight-fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * fill_ratio * 20.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + progress * 2.0);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: bonus if leftover can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leftover that is just barely below the next item (awkward gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Mean-residual coupling: bins deviating far below mean residual are
    // good candidates to be emptied first.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32 as f64 * 80.0
            + open_bins_count as f64 * -1.0
            + mean_residual * 0.3;
        score = 100.0 - pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post fit (small residual) is good.
    let fit_ratio = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= fit_ratio * 8.0;

    // Aggressive 2-step lookahead: reward when the next item fits exactly
    // into the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next).abs();
        if post >= next {
            // Next item can follow: reward closeness of exact match.
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0; // perfect 2-item packing
            }
        } else {
            // Post residual too small for next item: penalize dead space
            // proportional to how wasted it is relative to next item.
            score += 6.0 * (1.0 - post / next.max(1.0));
        }
    }

    // Relative to mean residual: prefer bins whose post residual sits near
    // the mean (keeps bin portfolio balanced), slight bonus for below-mean.
    let post_f = post_residual as f64;
    score += 0.5 * (post_f - mean_residual).abs();
    if post_f < mean_residual {
        score -= 2.0;
    }

    // Last-chance bin: strongly discourage opening a new bin when only this
    // bin fits, unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current item is large
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 40.0; // large item: fresh bin is fine
        }
    }

    // Late in the stream: consolidate harder, avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.3;

    // Small penalty for many open bins to encourage closing gaps.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale residual by a convex factor.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Reward bins whose leftover exactly accommodates the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space more strongly
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Perfect closure bonus: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0; // tiny dead space nearly as good
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large item, high mean residual waste elsewhere) or late in the stream
    // with few bins. Penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_elsewhere = (mean_residual - post_residual as f64).abs();
        let mut new_bin_bonus = 14.0 * (item_size as f64 / bin_capacity as f64);
        new_bin_bonus += 8.0 * (mean_residual / bin_capacity as f64);
        new_bin_bonus -= 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        new_bin_bonus += 6.0 * progress;
        score -= new_bin_bonus;
        // If residual after placement in a fresh bin is large, discourage.
        score += 0.15 * post_residual as f64;
    }

    // Mild preference for bins below mean residual (balancing load).
    score += 0.05 * (post_residual as f64 - mean_residual);

    // Slight decay of residual penalty over stream to consolidate early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear coupling: residual squared scaled by progress (dead space penalized more late)
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0 * (0.5 + progress);

    // Smooth interaction between post_residual and next item: reward if next item fits snugly
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).max(0.0);
        score -= 15.0 * (-gap / 25.0).exp();
        score += 8.0 * (gap / bin_capacity as f64);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize bins far below mean residual (keeps residuals balanced), smooth cubic term
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev * dev * dev;

    // Slight preference to fill tighter bins early, smoother later (polynomial in progress)
    score -= (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.1;

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residual mod small moduli
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Reward tight fits strongly (small post_residual)
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    } else if post_residual <= 20 {
        score -= 40.0;
    }

    // Dead-space penalty: leftovers that few future items can use
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Modulo arithmetic on post_residual: harmonics of common item sizes
    let modpen = |m: u32, pr: u32| -> f64 {
        if pr % m == 0 { -15.0 } else { 0.0 }
    };
    score += modpen(10, post_residual);
    score += modpen(20, post_residual);
    score += modpen(25, post_residual);
    score += modpen(50, post_residual);

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use leftover at all: penalize proportionally
            score += 30.0 * (next_item_size as f64) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a bin is usually worse than fitting,
    // unless the fit is terrible and there are many open bins.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.55 + 40.0;
        // open early in stream (many items to come) is fine; late is wasteful
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 * progress;
        // if current fit is poor, opening a fresh bin becomes attractive
        let fit_quality = 1.0 - frac; // high when item fills bin well
        if fit_quality < 0.35 && open_bins_count > 3 {
            score -= 120.0;
        }
        // exact-fit bonus for empty bin (item == capacity)
        if item_size >= bin_capacity {
            score -= 1000.0;
        }
    }

    // Mild preference to fill already-open bins rather than fragment many bins
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is below mean (consolidating small leftovers)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item are toxic.
    // Items in [1,100]; treat residual < 10 as unusable dead space (min item size fallback).
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // Heavily penalize creating unusable slivers.
        score += (dead_threshold - pr) * 6.0;
    }

    // Nonlinear waste curve: quadratic blowup on medium dead gaps.
    let waste = (pr / bin_capacity as f64).powi(2);
    score += waste * 25.0;

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 1.5;

    // Mean-residual coupling: penalize bins far below mean residual (fragmented bins).
    score += (mean_residual - pr).abs() * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, big bonus for chaining.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 20.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // Next item won't fit here; slight penalty for blocking.
        score += 5.0;
    }

    // New-bin candidate handling: make empty bin attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by how poor the current fits are.
        score = 45.0 + pr as f64 * 0.5;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: bin becomes perfectly full
    // after the next item as well.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect two-step match: huge bonus.
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize dead space that neither this nor the next item can fill usefully.
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    } else {
        // Last item: prefer the fullest bin.
        score -= 40.0;
    }

    // Penalize leaving residuals that are hard to reuse (small, awkward slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward using bins that are tighter than average (consume large residuals first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer filling it rather than wasting its uniqueness.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless the current residual
    // is genuinely awkward for the lookahead stream.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 45.0 * (1.0 - pressure);
        if next_item_size > 0 && next_item_size >= item_size {
            score += 20.0; // next item likely needs a large fresh residual anyway
        }
    }

    // Late in the stream: consolidate aggressively, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
