pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = r * (1.0 + 2.0 * rn * rn);

    // Smooth coupling: as the stream progresses, penalize large residuals more strongly
    // (early on, leaving slack is fine; late, we want bins closed out tightly)
    let late_penalty = rn.powf(3.0) * (1.0 + 8.0 * progress * progress);
    score += late_penalty * cap;

    // Dead-space term: residuals too small for the next item are wasted —
    // smooth quadratic in (residual - next_item) mismatch
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let mismatch = (r - nx).max(0.0) / cap;
        score -= 6.0 * progress * (1.0 - mismatch) * (r / (r + nx + 1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins
    let pressure = (open_bins_count as f64).ln1p() * (mean_residual / cap);
    score += 4.0 * pressure * (1.0 - rn);

    // New-bin candidate: empty bin should only win when existing fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) + pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25
    let r25 = post_residual % 25;
    let r10 = post_residual % 10;

    // Perfect-fit classes (post_residual == 0) are ideal
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize awkward dead-space classes: small odd remainders are hard to fill
        if r10 <= 2 && post_residual < 10 {
            score += 25.0; // tiny unusable sliver
        }
        if r25 == 5 || r25 == 10 {
            score -= 6.0; // quarter/half-friendly classes
        }
        if post_residual % 20 == 0 {
            score -= 4.0; // divisible-by-20 classes pair well with mid-size items
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            if next_waste % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's remainder: dead-space risk grows
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 0.5;
        if crowded && fitting_bins_count <= 2 {
            score -= 12.0 * (0.5 + progress);
        } else {
            score += 30.0; // prefer reusing existing space
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer tight fits
    score -= mean_residual * 0.05;
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Fractional tightness bonus: reward filling > 70% of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.7 {
        score -= 10.0 * (fill_ratio - 0.7);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

