    // Threshold: the smallest plausible item (1..100 range, assume min ~10) leaves gaps < 10 as dead.
    let dead_threshold = 10.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 8.0; // unusable gap penalty
    }

    // Reward tight fits: post_residual near 0 is ideal.
    score -= 60.0 * (-pr / 12.0).exp();

    // Open-bin pressure: discourage spreading into many bins; favor filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: if mean residual is high, prefer bins that reduce it the most.
    score += mean_residual * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit in open bins is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, growing with stream progress (late bins are worse).
        score += 55.0 + 40.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if the item is large and would leave a big gap elsewhere, new bin is more attractive.
        score -= (item_size as f64) * 0.4;
    }

    // Lookahead: if next item would fit perfectly in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-gap / 15.0).exp();
    }
    // Penalize placements that block a large next item from fitting well anywhere.
    if next_item_size > post_residual && bin_residual >= next_item_size {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item fills the bin exactly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: strongly reward when the next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more slack: mild reward scaled by tightness.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize proportionally to wasted potential.
            let unusable = (next_item_size - post_residual) as f64;
            score += 60.0 * (unusable / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is below the mean (tight bins absorb items well).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize creating small dead spaces (< 10, unusable for typical items) unless exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild preference for filling existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    } else {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual nonlinearly.
    if post_residual > 0 {
        score -= 40.0 / (post_residual as f64).sqrt();
    } else {
        // Perfect fill is ideal.
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless the fit elsewhere is bad or lookahead demands it.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins get more attractive late in the stream (fewer future chances to consolidate).
        let mut new_penalty = 45.0 - 20.0 * progress;
        // If lookahead item fits snugly in the residual left by this item in an open bin,
        // opening a new bin is less attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            new_penalty += 15.0;
        }
        // If the item leaves a tiny dead space that nothing (>=1) can use, new bin is fine.
        if post_residual > 0 && post_residual < 5 {
            new_penalty -= 20.0;
        }
        // Many open bins already: discourage spreading.
        new_penalty += (open_bins_count as f64).ln() * 4.0;
        score += new_penalty;
    }

    // Prefer bins whose residual deviates below the mean (consolidate fragmented space).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Lookahead coupling: if next item would fit exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't fit here; slightly penalize leaving awkward gaps.
        score += (post_residual.min(next_item_size) as f64) * 0.1;
    }

    // Mild time-decay: early on, be conservative with residual space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let tightness = 1.0 + 2.0 * progress * progress;
    score *= tightness;

    // Reward tight fits more strongly as the stream progresses
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Penalize leaving dead space below typical small-item size
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless residual is very small
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 12.0 + 5.0 * open_pressure * (1.0 - progress);
    }

    // Lookahead: reward bins whose post-residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * match_quality * match_quality;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Mild diversity pressure relative to mean residual
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near 0 are good,
    // mid-range residues (dead space ~ half of typical items) are bad.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual / 10) % 10; // coarse decade class 0..9
    let class_bonus = match class {
        0 => -12.0, // perfect fill class
        1 => -6.0,
        2 => -3.0,
        3 => 0.0,
        4 => 4.0,  // awkward ~30-40 dead space
        5 => 5.0,
        6 => 3.0,
        7 => 0.0,
        8 => -2.0,
        _ => -4.0,
    };
    score += class_bonus;

    // Lookahead coupling: reward bins whose residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
            if post_residual == next_item_size {
                score -= 15.0; // perfect chain fill
            }
        } else {
            // next item won't fit here: residual becomes dead weight
            score += 0.35 * pr;
        }
    } else {
        // last item: prefer fullest packing
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Many open bins with large mean residual: discourage wasting space in a fat bin
    // when alternatives exist; encourage consolidating into tight bins.
    if open_bins_count > 2 {
        let tightness = 1.0 - (bin_residual as f64) / cap;
        score -= 3.0 * tightness;
        score += 0.5 * (mean_residual - pr).abs();
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let poor_fit = post_residual as f64 > 0.55 * cap;
        if poor_fit && next_item_size > 0 && next_item_size > post_residual {
            score -= 8.0; // opening a bin is better than creating dead space
        } else {
            score += 14.0; // prefer existing bins otherwise
        }
        // early stream: cheaper to open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * (1.0 - progress);
    }

    // Integer division threshold: post_residual divisible by common item sizes
    // (10..80 multiples of 5/10) is reusable -> reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (size 1..100) are wasted; penalize hard.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect or near-perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead space that cannot hold the lookahead item is extra bad.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Bonus when the residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin before opening a new one: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    // over spreading; new empty bin should look unattractive.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        score += 35.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins tighter than the average residual (good fill).
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Late in the stream, squeeze every bin harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 150.0;
        } else {
            // dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Reward tightness relative to mean residual
    score -= (post_residual as f64 - mean_residual).abs() * -0.3; // tighter than mean favored
    if (post_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // Last chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize new bin when a good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 200.0;
        if fitting_bins_count > 0 && post_residual > 40 {
            score += 100.0;
        }
        // open new bin if nothing fits well
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
    }

    // Prefer bins with small residual overall (best-fit bias)
    score += (bin_residual as f64) * 0.2;

    // Late stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    let mut score = 2.0 * poly * cap;

    // Smooth penalty for wasted residual relative to mean residual
    let mean_gap = norm_pr - mean_residual / cap;
    score += 3.0 * mean_gap * mean_gap * cap;

    // Reward tight fits with smooth exponential term
    score -= 5.0 * (-pr / 12.0).exp();

    // Lookahead coupling: penalize if next item cannot use the remaining space
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr - nx).max(0.0) / cap;
        score += 2.0 * (1.0 - usable) * (1.0 - usable);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure toward consolidation as stream progresses
    score += 0.5 * progress * norm_pr * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lies in "useful"
    // small-item classes (multiples of 10 up to ~30) are preferred.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold class 0..=10
    match class {
        0 => score -= 6.0,            // near-perfect fit, tiny dead space
        1 => score -= 4.5,            // leftover 10..19 still highly usable
        2 => score -= 3.0,            // leftover 20..29 moderately usable
        3 => score -= 1.0,            // leftover 30..39
        4 | 5 => score += 2.0,        // 40..59 half-empty: wasteful
        6 | 7 => score += 5.0,        // 60..79 mostly empty
        _ => score += 8.0,            // 80+: barely used bin
    }

    // Modulo coupling: if the next item exactly divides into post_residual
    // (perfect modular fit), strongly reward this bin.
    if next_item_size > 0 && pr >= next_item_size && pr % next_item_size.max(1) == 0 {
        score -= 5.0;
    }
    // If next item cannot fit in post_residual, penalize slightly (fragmentation risk).
    if next_item_size > pr {
        score += 1.5;
    }

    // Last-chance bin: only one fitting bin -> reward using it to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate: it must not win unless current placements are bad.
    if bin_residual == bin_capacity {
        score = cap - 15.0; // baseline: slightly worse than a decent fit (score ~ pr - 6)
        // Opening a fresh bin is attractive late in the stream or when open bins
        // are on average nearly full (mean_residual small).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = mean_residual / cap;
        score -= 12.0 * openness;      // open bins have room -> prefer them
        score -= 4.0 * (1.0 - progress); // early stream: consolidate more
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can host both current and next item comfortably
            if item_size + next_item_size <= bin_capacity {
                score -= 6.0;
            }
        }
    }

    // Slight bonus for packing into bins with above-average residual (balance load).
    if bin_residual as f64 > mean_residual {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
        // But if the new bin would fit the next item tightly, soften the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let next_gap = bin_capacity - next_item_size;
            if next_gap < 15 {
                score -= 25.0;
            }
        }
    } else {
        // Slight preference for tighter existing bins.
        score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.1;
    }

    // Lookahead: penalize creating a gap that next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual already does this),
    // but boost the reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: reward if the NEXT item fits exactly
    // into the post_residual (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual chain continues; scale by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder: dead space risk
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste.min(40.0);
        }
    }

    // Compare post_residual relative to mean residual of open bins:
    // placing into a bin whose residual is far below mean preserves
    // larger shared space.
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.25 * (post_residual as f64 - mr).max(-50.0).min(50.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is large relative
    // to capacity (open bins would strand big dead space otherwise) or
    // when post_residual would be small enough to be reusable.
    if bin_residual == bin_capacity {
        // base penalty so open bins win when they fit well
        score += 35.0;
        // large items justify fresh bins
        score -= 0.5 * item_size as f64;
        // small items should almost never open new bins
        if item_size <= 30 {
            score += 40.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // if many bins are open, prefer consolidating
        score += 1.5 * open_bins_count as f64;
    }

    // Mild penalty for leaving residuals that are hard to fill
    // (typical awkward zone 51..70 given items up to 100... keep generic:
    // residuals just above half capacity are least reusable).
    let pr = post_residual as f64;
    if pr > 0.0 {
        let awkward = 1.0 - ((pr - 25.0).abs() / 25.0).min(1.0);
        score += 8.0 * awkward;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is already low; add quadratic penalty for mid-range waste.
    let pr = post_residual as f64;
    score += 0.15 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 100.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: only one bin can fit this item; strongly favor using it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: penalize leaving a residual that cannot host the next item, reward leaving one that can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Reward residuals that leave a "good window" for the next item.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.08 * gap;
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (1.0 + open_bins_count as f64 * 0.02);

    // Mean residual coupling: if this bin's residual is far below mean (already tight), favor it.
    let res_gap = mean_residual - bin_residual as f64;
    score += 0.05 * res_gap;

    // Time horizon: early in stream, tolerate spreading (favor new bins slightly); late, pack tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 3.0 - t * 2.0;

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 0.1 * open_bins_count as f64;
        // But if item is large and mean residual is small, new bin is more acceptable.
        score -= 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual, with non-linear (quadratic) coupling
    let mut score = post + 0.6 * (post / cap) * post;

    // Tight-fit reward: non-linear bonus when item fills most of the residual
    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: post_residual too small to hold typical future items
    let dead = (post - 10.0).max(0.0);
    score += 0.15 * dead * (1.0 - progress);

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 10.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 0.05 * nxt * (1.0 - progress);
        }
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 4.0 * progress;
    }

    // Mean-residual coupling: favor bins deviating below mean (keeps large residuals distributed)
    score += 0.05 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -12.0,                    // perfectly divisible residual: reusable
        1..=3 => -4.0,                 // small slivers still pairable with tiny items
        4..=7 => 3.0,                  // mid dead-space band
        _ => 8.0,                      // 8..=9: awkward residue
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual.
    let q = post_residual / 25;
    score -= match q {
        0 => 6.0,   // residual < 25: near-dead space
        1 => 0.0,
        2 => -5.0,
        _ => -8.0,  // residual >= 75: very reusable
    };

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 2.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current residual is poor and
    // mean residual across open bins is low (bins nearly full anyway).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_score = bin_capacity as f64
            - mean_residual.min(bin_capacity as f64) * 0.5
            + open_bins_count as f64 * 2.0
            - progress * 5.0;
        score = score.max(new_bin_score);
        if post_residual as f64 > mean_residual + 20.0 {
            // existing bin is roomy; discourage new bin
            score += 20.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 25.0;
    } else if fill_ratio > 0.75 {
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space relative to bin capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Pressure from number of open bins: discourage spreading too thin.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0; // next item can't use this sliver
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are very full.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0 + open_bins_count as f64 * 1.5;
        // If this bin is the only fitting option among open bins, opening new is bad.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
        // Early in the stream, opening bins is cheaper (future packing freedom).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
        // If mean residual is tiny, open bins are nearly full: new bin fine.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual (keeps variety).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (dead-space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: reward proportionally to how snugly it fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 150.0 - slack_after_next as f64;
            if slack_after_next == 0 {
                score -= 500.0; // perfect 2-item chain
            }
        } else {
            // Next item won't fit here: penalize leaving residual that is
            // simultaneously too small for next_item but larger than needed.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare residual against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a brand-new bin when existing bins fit reasonably well,
    // unless the item is large and the new bin is genuinely needed.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 - 30.0 * progress;
        if fitting_bins_count > 0 && item_size <= bin_residual - item_size {
            score += 40.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 25.0; // large next item may benefit from a fresh bin
        }
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
