pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - pr / cap; // how well item fills bin

    // Base: prefer small post residual, but with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits with a smooth cubic coupling of tightness and progress
    score -= 30.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let dead = (pr - mean_residual).max(0.0) / cap;
    score += 20.0 * dead * dead;

    // Last-chance bonus: smooth decay of preference for wasting the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill = nxt / cap;
            score -= 12.0 * fill * (1.0 - progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Mild pressure to reuse existing bins as open count grows
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (1/4, 1/3, 1/2 of C)
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;

    // Penalize dead space: small residuals that few items can use
    if post_residual < quarter {
        score += (quarter - post_residual) as f64 * 2.0;
    }
    // Reward post_residuals in "harmonic sweet spots" where next items fit
    if post_residual == quarter || post_residual == third || post_residual == half {
        score -= 12.0;
    }

    // Modulo arithmetic on post_residual: multiples of small classes are reusable
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does the next item fit exactly / at all?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect lookahead fit
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic class match: next item leaves another sweet spot
            let nxt_post = post_residual - next_item_size;
            if nxt_post == quarter || nxt_post == third || nxt_post == half {
                score -= 10.0;
            }
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer only if current bin would leave bad dead space
    if bin_residual == bin_capacity {
        // neutral baseline, adjusted by how wasteful keeping item elsewhere is
        score += 5.0;
        if post_residual < quarter {
            score -= 10.0; // fresh bin beats creating tiny dead space
        }
    }

    // Progression: as stream advances, tighten packing (favor fuller bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.3;

    // Spread-awareness: if mean residual is high, prefer bins below it (balance)
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot host the smallest
    // item (size 1..10 range) or only tiny fragments are pure waste.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 4.0;
    } else if post_residual > dead_threshold && post_residual < 20 {
        // Semi-dead zone: only small items fit; penalize moderately.
        score += 18.0 - (post_residual - dead_threshold) as f64 * 1.2;
    }

    // Reward tight fits (near-zero post_residual).
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a chained perfect fit — strongly favor it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= dead_threshold {
        // Next item would leave a fresh dead gap — penalize.
        score += 15.0;
    }

    // Last-chance bin: only one bin can fit this item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.5 * progress);

    // Mean residual coupling: if this bin is much emptier than average,
    // slightly deprioritize it so fuller bins drain first.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (i.e., item leaves large dead space everywhere else) or few bins open.
    if bin_residual == bin_capacity {
        score = 70.0 + open_bins_count as f64 * 4.0 - post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
