            let snug = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 50.0 + 30.0 * snug;
        } else {
            // Dead space that next item cannot use: penalize, worse when gap is small-but-unusable.
            let gap = post_residual as f64 - nxt;
            if gap < 0.0 {
                score += 20.0 + (nxt - post_residual as f64).min(80.0);
            }
