    } else {
        // Last item: strongly prefer tightest fit.
        score -= 200.0;
    }

    // Relative to mean residual: bins with residual near the item are attractive.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness.abs());

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize the fresh-bin candidate mildly, unless open bins are very full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if mean_residual < 20.0 {
            score += 150.0; // open bins still roomy: don't open a new one
        } else if pressure > 0.8 {
            score -= 80.0; // open bins nearly full: new bin is fine
        } else {
            score += 40.0;
        }
    }

    // Late in the stream: prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward low post_residual non-linearly.
    if post_residual == 0 {
