        score -= 0.3 * item_size as f64;
        // If the only fitting bin is this new one anyway, keep neutral.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Prefer bins with residual closest to item (best-fit flavor),
        // reward below-mean residual usage.
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 15.0 * tightness;
        // Slightly prefer bins with residual below mean (concentrate filling).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Time-horizon modulation: early on, be pickier about dead space;
    // late in the stream, just fill anything available.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
