    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: reward proportionally to how well next item fills the gap.
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 10.0 + 8.0 * fill;
            if next_item_size == post_residual {
                score -= 15.0; // perfect chain
            }
        } else {
            // Next item won't fit here; penalize leaving a gap that traps the stream.
            score += 4.0;
            if post_residual < 20 {
                score += 6.0;
            }
        }
    } else {
        // Last item: prefer tightest packing, close bins fully.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is usually wasteful unless
    // current bins have poor fits (large mean residual / many open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 3.0 + mean_residual * 0.4;
        // Base cost of a fresh bin; discounted early in the stream.
        score = cap - 30.0 * (1.0 - progress) + pressure;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > 50 {
            score -= 10.0; // big follow-up item: fresh bin may be wise
        }
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild penalty for too many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items are waste.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits strongly.
    score -= 30.0 * (item_size as f64 / bin_capacity as f64);

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64).max(1.0);
    score += 10.0 * open_pressure;

    // Prefer bins whose residual is close to the item (relative fit quality).
    score += 0.3 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 15.0;
    }
    // Penalize if next item cannot fit in post residual but could fit elsewhere easily.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as f64) < dead_threshold {
        score += 12.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 8.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // Strong reward for perfect 2-item match (gap small)
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Extra bonus for exact match
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit: penalize proportional to overflow
            score += 0.5 * (nxt - pr);
        }
    }

    // Compare against mean residual: prefer bins whose post residual is near mean
    // (avoids creating outliers with unusable dead space).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.3 * dev;

    // Penalize large dead space (waste) nonlinearly.
    if pr > 0.0 && pr < 10.0 {
        score -= 10.0; // tiny leftover is great (nearly full bin)
    } else if pr > 50.0 {
        score += 0.2 * (pr - 50.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good existing fit exists.
    if bin_residual == bin_capacity {
        let mut base = 15.0 + 0.5 * item_size as f64;
        // If next item pairs well with current item in a fresh bin, encourage opening.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair <= bin_capacity as f64 {
                base -= 0.4 * (bin_capacity as f64 - pair);
            }
        }
        // Late in the stream, discourage proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        base += 10.0 * progress;
        // If many bins can fit, opening new bin is wasteful.
        if fitting_bins_count > 2 {
            base += 20.0 * (fitting_bins_count as f64 - 2.0);
        }
        score += base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual super-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tight * tight;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves more waste — mild reward scaled by fit quality.
            let nl = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 6.0 * nl;
        } else {
            // next item won't fit here: penalize leaving residual just below next size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(30.0);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to keep options open.
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Prefer filling bins that are already relatively empty (consolidate waste).
    let rel_fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 2.0 * rel_fill;

    // Global state coupling: if mean residual is high, encourage using open bins
    // rather than fragmenting; if low, new bins are cheap.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, squeeze existing bins hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tight;

    // New-bin candidate: make it moderately attractive only when the current bin
    // would be left with awkward residual or many bins exist already.
    if bin_residual == bin_capacity {
        let awkward = (post_residual > 0 && post_residual < 10) as f64;
        score += 18.0 - 12.0 * awkward - 4.0 * progress;
        // If the item nearly fills a fresh bin, opening is great.
        if item_size >= 70 { score -= 25.0; }
    }

    // Slight preference for balancing load across many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let poly = 0.5 * pr_norm * pr_norm + 0.3 * pr_norm * pr_norm * pr_norm;
    score += poly * (0.5 + progress) * cap * 0.4;

    // Reward tight fits: quadratic bonus shrinking with residual.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 8.0;

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * (1.0 - pr_norm);
    }

    // Penalize bins far below mean residual (wasteful spread) — smooth cubic term.
    let mean_gap = (mean_residual - pr) / cap;
    score += 0.5 * mean_gap * mean_gap * mean_gap * cap;

    // Lookahead: reward leaving space for the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_after = if pr >= nx { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((pr - nx).abs() / cap);
        score -= fit_after * closeness * closeness * 5.0;
        // Penalize if this placement blocks the next item badly.
        if pr > 0.0 && pr < nx {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for many open bins, encouraging consolidation.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep neutral-ish, penalize slightly unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 2.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with mild scaling.
    score *= 1.0 + 0.01 * (post_residual as f64 / bin_capacity as f64);

    // Harmonic class of post_residual: mod-10 buckets reward "clean" residues.
    let pr = post_residual;
    let class = pr % 10;
    score += match class {
        0 => -6.0,               // perfectly aligned residual
        1..=3 => 2.0,            // sliver space, likely dead
        4..=6 => 0.0,            // neutral
        7..=9 => -2.0,           // chunky residual, still usable
        _ => 0.0,
    };

    // Penalize residuals that no plausible item (1..=100) can ever fill well.
    if pr > 0 && pr < 10 {
        score += 8.0; // dead space band
    }
    // Integer-division threshold: residual in [10, 20) can only host tiny items.
    if pr >= 10 && pr < 20 && next_item_size > pr && next_item_size != 0 {
        score += 4.0;
    }

    // Lookahead coupling: reward residual that exactly hosts next item (harmonic pairing).
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 12.0;
        } else if pr >= next_item_size && pr - next_item_size < 10 {
            score -= 6.0;
        } else if next_item_size > pr {
            score += 5.0; // next item won't fit here
        }
        // modulo harmony: next_item_size and pr share a divisor class
        if pr != 0 && next_item_size % 10 == pr % 10 && pr >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it competitive only when fits are bad.
    if bin_residual == bin_capacity {
        // New bin: score = capacity - item (waste potential). Bias by stream phase.
        let phase = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * phase; // later in stream, mildly discourage hoarding new bins
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 5.0; // roomy new bin beats cluttered mean
        }
        if fitting_bins_count > 0 && post_residual < 20 {
            score += 20.0; // don't open a bin for a near-full item
        }
    }

    // Congestion: many open bins -> favor consolidation (lower score for tight fits).
    let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * congestion * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual anchor: penalize bins far above mean residual (wasteful outliers).
    if (post_residual as f64) > mean_residual + 30.0 && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Penalize wasting a large bin on a small item (big hole created).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.8;

    // Prefer bins whose residual is close to mean (balanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    }
    // Penalize leaving a gap the next item just barely misses.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 20.0;
    }

    // Slight stream-progression urgency: pack tighter as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - waste_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: prefer small post_residual strongly (non-linear).
    score += 0.35 * (post * post) / cap;

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // heavily reward this bin (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // next item fits: reward closeness of the chain match
            score -= 18.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 25.0; // perfect two-item packing
            }
        } else {
            // next item will NOT fit here: mild penalty scaled by overflow size
            score += 4.0 * (nxt - post) / cap;
        }
        // If post residual is too small for anything useful (dead space), penalize
        if post < 10.0 && post < nxt {
            score += 12.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: penalize opening a new bin unless the item is huge
    // relative to residual or many bins are already open and tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0
            - 10.0 * (item_size as f64 / cap)
            - 6.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) + (item_size as f64) <= cap {
            score += 10.0; // item + next could share a fresh bin: slight extra penalty
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
