pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Base: penalize leftover space, but non-linearly (quadratic/cubic coupling with progress)
    let mut score = pr * (1.0 + 0.8 * progress) + 30.0 * fit_norm * fit_norm * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses (cubic interaction)
    let tightness = 1.0 - fit_norm;
    score -= 25.0 * tightness * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead coupling: smooth reward if next item can use the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_ratio = (next_item_size as f64) / pr.max(1.0);
        score -= 12.0 * slack_ratio * (1.0 - slack_ratio) * (0.5 + progress);
    }

    // Last-chance bonus: smooth sigmoid-like weighting on fitting_bins_count
    let last_chance = 1.0 / (1.0 + (fitting_bins_count.saturating_sub(1)) as f64);
    score -= 15.0 * last_chance * tightness;

    // Mild penalty for fragmenting when many bins are open relative to mean residual
    let mean_gap = (mean_residual - pr).abs() / cap;
    score += 5.0 * mean_gap * mean_gap * (open_bins_count as f64).sqrt() * 0.1;

    // New-bin candidate: penalize gently unless it yields a very large residual advantage
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 measure "wasted" capacity
    let harm = post_residual % 10;
    score += (harm as f64) * 1.5; // penalize residuals not on harmonic grid

    // Integer-division thresholds: residual buckets of 25 (quarter capacity)
    let quarter = post_residual / 25;
    match quarter {
        0 => score -= 8.0,   // residual < 25: nearly sealed bin, good
        1 => score += 2.0,   // 25..49: awkward dead zone
        2 => score += 0.5,   // 50..74: still useful
        _ => score += 4.0,   // >=75: bin barely used, discourage
    }

    // Reward tight fits (best-fit core)
    score -= (bin_residual as f64 / (item_size as f64 + 1.0)) * 2.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // harmonic alignment: next item leaves residue on the 10-grid
            let r2 = (post_residual - next_item_size) % 10;
            score -= 6.0 - (r2 as f64) * 0.4;
        } else {
            // next item won't fit here; penalize leaving large residual
            if post_residual > 40 {
                score += 5.0;
            }
        }
    } else {
        // last item: any residual is pure waste; prefer minimal
        score += (post_residual as f64) * 0.3;
    }

    // Progress-aware new-bin handling
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when mean residual is low or stream is early
        let fresh_bonus = 6.0 * (1.0 - progress) + (mean_residual / bin_capacity as f64) * 8.0;
        score = 55.0 - fresh_bonus;
    } else {
        // Prefer denser bins when many bins are open
        score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // even the smallest item (1..10) are wasted forever -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals in 10..=20 can only host tiny items; moderate penalty scaled
    // by how small the gap is relative to capacity.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild penalty if the leftover after the lookahead item becomes dead space.
        let post2 = post_residual as i64 - next_item_size as i64;
        if post2 > 0 && post2 < 10 {
            score += 15.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit
    // leaves a large unusable gap; encourage consolidation otherwise.
    score += (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Slight preference for tighter-than-average bins.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    // Progress-aware tightening: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward when item exactly fills the bin.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward residuals that can exactly host the next item,
    // penalize residuals that are just barely too small for it (dead space).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // next item fits: mild reward proportional to leftover after next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item doesn't fit: penalize near-miss dead space more strongly
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Compare against mean residual across open bins.
    // Prefer bins whose post-residual is below the mean (tight packing),
    // penalize bins that stay far above the mean (wasteful).
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - pr) * 0.15;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // But if item is large relative to capacity and existing bins would leave
        // big dead space, opening new is less bad: relax the penalty.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 100.0;
        // If no open bins at all, opening is necessary.
        if open_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Small progression-aware nudge: later in the stream, prefer tightening
    // existing bins even more (closing them out) rather than spreading load.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0 * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to modulate exploration vs exploitation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Detect the brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Best-fit sharpening: reward near-perfect fills (small post_residual) ----
    let perfect_fit_bonus = ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(4);
    score -= 12.0 * perfect_fit_bonus;

    // ---- Lookahead coupling: if the next item fits snugly into the resulting residual,
    // reward this placement (chaining); if the residual is dead space for the next item,
    // penalize proportionally to how large the next item is. ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * chain_tightness * (1.0 - 0.5 * progress);
        } else {
            let dead = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            // Dead space is worse early (long future to suffer from it).
            score += 10.0 * dead * (1.2 - 0.5 * progress);
        }
    }

    // ---- Last-chance bonus: if this is the only bin that fits the item, strongly prefer it
    // over opening a new bin. ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // ---- Congestion pressure: many open bins with large mean residual -> prefer consolidating
    // into existing bins rather than spawning more. ----
    if open_bins_count > 2 {
        score += 2.0 * (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64).max(0.0);
    }

    // ---- New-bin candidate handling: opening a new bin is fine for large items (they leave
    // useful residual) but wasteful for small items when a decent fit exists. ----
    if is_new_bin {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items justify a fresh bin; small items are penalized.
        score += 6.0 * (1.0 - item_frac);
        // Early in the stream, opening bins is cheap (plenty of future items to fill them);
        // late in the stream, prefer consolidation.
        score += 4.0 * progress;
    }

    // ---- Mild waste penalty: residual that can never host even the smallest item is pure loss. ----
    if post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = (norm_pr * norm_pr) * (1.0 - progress) - (norm_pr * progress * progress);
    score += 30.0 * coupling;

    // Reward near-perfect fills more aggressively as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: bonus if next item fits the post residual (smooth)
    if next_item_size > 0 {
        let fit_next = (post_residual >= next_item_size) as i32 as f64;
        let slack = (post_residual as f64 - next_item_size as f64).abs() / cap;
        score -= 8.0 * fit_next * (1.0 - slack);
        score += 0.5 * (next_item_size as f64 / cap) * (1.0 - fit_next) * progress;
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize slightly unless residuals of open bins are poor
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - progress) - 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: prefer tight fits.
    score -= 2.0 * (item_size as f64) / (bin_capacity as f64);

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "awkward" residue classes that few item sizes can fill.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                    // perfect fit: strong reward
        1..=9 => 6.0,                // tiny sliver: nearly dead space
        10..=24 => 2.0,              // small but fillable by small items
        25..=49 => 1.0,              // mid class
        50..=74 => 0.5,              // half-full: quite reusable
        _ => 0.2,                    // large residual: very reusable
    };
    score += class;

    // Modulo-10 harmonic penalty: residues near multiples of 10 are more
    // likely matchable by common item sizes; odd/prime-ish residues worse.
    let m = (pr % 10) as f64;
    score += 0.3 * (m - 5.0).abs() / 5.0;

    // Integer-division thresholds: if post_residual still fits the next item,
    // this bin chains nicely — reward that lookahead compatibility.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 3.0;
        // Extra reward if the pair (item, next) nearly fills the bin.
        let pair_left = (pr - next_item_size) as f64;
        if pair_left <= 10.0 {
            score -= 2.0;
        }
    } else if next_item_size > pr {
        // Next item won't fit here; penalize proportionally to wasted chain.
        score += 1.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate handling: keep fresh bins neutral-to-slightly-high so
    // they only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.02 * open_bins_count as f64;
    }

    // Late in the stream, consolidation matters more: favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference to balance residuals toward the mean.
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for typical items) are heavily penalized.
    let dead_zone_low = 1.0;
    let dead_zone_high = 19.0;
    if post_residual >= dead_zone_low as u32 && post_residual <= dead_zone_high as u32 {
        // Quadratic ramp inside the dead zone: smaller gaps are worse.
        let center = (dead_zone_low + dead_zone_high) / 2.0;
        let d = (post_residual as f64 - center).abs();
        score += 55.0 - 3.0 * d * d / (dead_zone_high - dead_zone_low);
    }

    // Reward tight fits (small post_residual outside dead zone).
    if post_residual > dead_zone_high as u32 {
        score -= 18.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 70.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow.
        score += 25.0 + 12.0 * pressure;
    } else {
        score -= 4.0 * pressure;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= dead_zone_high as u32 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item would be blocked by a dead-space gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Late in the stream, tighten up: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mild preference for bins below mean residual (balance residuals).
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: next item fits tightly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // tight fit reward, decaying with slack
        score -= 200.0 * (1.0 - slack / 50.0).max(0.0);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here afterwards: penalize leaving a large awkward residual
        let waste = next_item_size - post_residual;
        score += 30.0 * (waste as f64 / 100.0);
    }

    // Penalize creating tiny unusable dead space (0 < post_residual < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Perfect closure bonus: bin exactly filled
    if post_residual == 0 {
        score -= 300.0;
    }

    // Last-chance bin: only fitting bin, strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Prefer filling bins below mean residual (compact the average)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Discourage opening a new bin when existing bins fit well (post_residual small)
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty so good fits in open bins win
        score += 60.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin can host next item at residual bin_capacity - item
            let pr = (bin_capacity - item_size) as f64;
            if (pr - next_item_size as f64).abs() < 5.0 {
                score -= 400.0;
            }
        }
    }

    // Late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 18.0 * tightness * tightness;
    }

    // Penalize leaving dead space that no typical item could use
    if post_residual < 10 {
        score -= 25.0; // perfect fill is excellent
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual > 40 {
        score += 10.0; // large leftover fragments the bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= bin_residual {
            // placing here forces next item elsewhere; mild penalty
            score += 4.0;
        }
        // If next item is large, prefer keeping big residuals open
        if next_item_size > 60 && post_residual < next_item_size as u32 {
            score += 6.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> consolidate
    let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    if pressure > 2.0 {
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when current item is huge or no good fits
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 20.0 * desperation;
        if item_size > 70 {
            score -= 10.0; // huge items are fine in a fresh bin
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 6.0; // big next item makes a fresh bin more valuable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let x = (pr / cap).clamp(0.0, 1.0);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; later, strongly prefer tight fits.
    let tightness = (1.0 - x) * (1.0 - x);           // quadratic tightness reward
    let progress_boost = 1.0 + 2.0 * progress * progress; // grows quadratically with stream
    score -= tightness * progress_boost * 18.0;

    // Cubic dead-space penalty: large residuals late in the stream are costly.
    score += x * x * x * (10.0 + 20.0 * progress);

    // Interaction with mean residual: prefer bins whose residual is below average
    // (tighter than average) when they fit well.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (4.0 + 6.0 * progress);

    // Reward exact / near-exact fits smoothly.
    let fit_ratio = (item_size as f64 / bin_residual.max(1) as f64).clamp(0.0, 1.0);
    score -= (fit_ratio * fit_ratio) * (6.0 + 10.0 * progress);

    // Lookahead coupling: if next item could use the post_residual, reward leaving it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr / nx).clamp(0.0, 1.0);
        score -= usable * usable * 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: make it attractive only when it is genuinely better,
    // i.e. when existing fits are loose and we are early; otherwise penalize.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        let spread = (mean_residual / cap).clamp(0.0, 1.0);
        score = 12.0 * progress + 20.0 * (1.0 - spread) - 10.0 * early * early;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues mod 10 as "dead-space classes"
    let post = post_residual as i64;
    let class = post % 10;
    // Penalize small nonzero dead space (unusable for typical items)
    if post > 0 && post < 10 {
        score += 50.0;
    }
    // Reward post_residual in "useful" harmonic classes (multiples of 10, and >= 20)
    if class == 0 && post >= 20 {
        score -= 15.0;
    }
    // Class 5 residue: half-slot, moderately useful
    if class == 5 {
        score -= 5.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward if next item exactly fills, or leaves a good class again
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 200.0;
            } else if next_post % 10 == 0 {
                score -= 40.0;
            } else if next_post < 10 {
                score += 30.0; // would create tiny dead space next step
            }
            score -= next_item_size as f64 * 0.5;
        } else {
            // Next item won't fit here: penalize less if post_residual is tiny anyway
            if post_residual >= 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: empty bin should only win when nothing else is attractive.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        score += 120.0;
        // If many bins open and mean residual is high, opening new bin is fine
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 60.0;
        }
        // Late in stream, prefer filling existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 50.0;
        // Large items prefer fresh bins (avoid fragmenting)
        if item_size > 60 {
            score -= 40.0;
        }
    }

    // Prefer tighter fits generally: reward small post_residual relative to item
    score -= (item_size as f64) * 0.3;

    // Discourage spreading across too many bins when residuals are fragmented
    if open_bins_count > 10 {
        score += 2.0 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1..10 band)
    // are worthless — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium unusable-ish gaps (10..20) are risky since most items are >= 10;
    // a gap of exactly 10 is fine, slightly larger is a trap.
    if post_residual > 10 && post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 0.8 * (item_size as f64 / (item_size + post_residual) as f64) * 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferating bins mildly when placing
    // into an existing one; encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to what we fill (avoid wasting big
    // residual on a small item when mean residual is small).
    score += 0.3 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate logic: opening a fresh bin is only good if the fit
    // into this open bin would be poor, or if lookahead suggests the fresh
    // residual will serve the next item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 90.0;
        // If this bin is the only fitting bin and the fit is decent, opening
        // new is bad — but the -50 above already applies to that bin.
        // Reward opening a new bin when the post_residual here (which equals
        // capacity - item_size) is a clean, reusable gap for the next item.
        if next_item_size > 0 {
            let nr = post_residual as i64 - next_item_size as i64;
            if nr == 0 {
                score -= 120.0; // next item fits perfectly in the fresh bin
            } else if nr > 0 && nr < 10 {
                score += 30.0; // next item would leave dead space
            }
        }
        // Late in the stream, avoid opening bins for poor fits.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0; // perfect chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 90.0 - gap * 4.0;
            } else {
                score += gap * 0.3; // leftover too big/small: partial penalty
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score -= 50.0 - gap * 3.0; // next item nearly fills remaining space
            } else {
                score += gap * 0.2;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize new-bin candidate unless open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Allow opening a new bin early in stream or when next item is huge
        // and current bin would leave a large unusable residual.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if post_residual > 30 && next_item_size > post_residual {
            score -= 180.0;
        }
        if progress < 0.1 {
            score -= 40.0;
        }
    }

    // Mild preference for tighter bins among equally good candidates.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Slight penalty for spreading across too many bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual is already favored by base).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; slight penalty for stranding capacity.
            score += 3.0 * (post_residual as f64) / (next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer fuller bins relative to the fleet average.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild penalty for spreading across too many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when residual is huge and item is large.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let no_alternative = fitting_bins_count == 0;
        score = if no_alternative {
            -50.0
        } else {
            bin_capacity as f64 - 10.0 * large_item + 5.0
        };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 + 3.0 * progress) - 2.0 * pr_norm * progress;
    score += 10.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space when the item is large relative to residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr) / bin_capacity as f64;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * pr_norm * progress;

    // Diverge from mean residual: prefer bins that keep residuals balanced
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues near multiples of
    // common item sizes are more reusable, dead space otherwise.
    let pr = post_residual;
    if pr > 0 {
        // Class A: residual exactly matches a plausible next item (10..=80 grid)
        let mut harmonic_bonus = 0.0;
        if pr >= 10 && pr <= 80 {
            harmonic_bonus += 12.0; // residual itself is a legal item size
        }
        // modulo classes: residuals divisible by 10 pack well with grid items
        if pr % 10 == 0 {
            harmonic_bonus += 6.0;
        }
        // residual + next item leaves a clean residue
        if next_item_size > 0 && pr >= next_item_size {
            let after_next = pr - next_item_size;
            if after_next % 10 == 0 {
                harmonic_bonus += 8.0;
            }
            if after_next == 0 {
                harmonic_bonus += 20.0; // perfect two-item closure
            }
        }
        score -= harmonic_bonus;
    } else {
        score -= 40.0; // exact fit: perfect closure
    }

    // Penalize large dead space quadratically (unusable fragments)
    if pr > 0 && pr < 10 {
        score += 25.0; // tiny sliver, likely dead
    }
    if pr > 80 {
        score += 0.0; // roomy bin, still useful
    } else if pr > 0 {
        let frac = pr as f64 / cap;
        score += frac * frac * 15.0; // moderate dead-space penalty
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: prefer a fresh bin only when no open bin
    // offers a good harmonic fit (post_residual small or clean class).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = cap * 0.55;
        // late in the stream, opening new bins is safer (less leftover waste)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score -= progress * 20.0;
        // if next item is large, a fresh bin gives flexibility
        if next_item_size >= 60 {
            new_bin_score -= 10.0;
        }
        // many open bins with low mean residual: consolidate instead
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            new_bin_score += 15.0;
        }
        score = score.min(new_bin_score);
        // never let the new bin beat a genuinely tight fit
        if post_residual <= 10 && bin_residual < bin_capacity {
            score = score.max(post_residual as f64 - 40.0);
        }
    }

    // Slight preference for bins whose residual is close to mean (balance load)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium gaps that likely fit nothing (next item can't use them) are penalized too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open and this bin fits well.
    if bin_residual != bin_capacity {
        score -= 2.0 + 0.15 * open_bins_count as f64;
    } else {
        // New-bin candidate: only attractive when few open bins or this is a last-chance situation elsewhere.
        score += 1.0 + 0.10 * open_bins_count as f64;
        // But allow new bin if the item would leave a large gap anywhere (big item into fresh bin).
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before a new bin opens.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Late in stream: consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 4.0 * progress;
    }

    // Prefer bins whose residual is above the mean (keeps flexibility).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward exact match between
    // post_residual and next_item_size (perfect chain placement).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact 2-step closure: bin becomes perfectly full after next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space the next item cannot use.
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 10.0;
    }

    // Relative to mean residual: bins tighter than average are good targets.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize so we only open fresh bins when current fits are bad.
    if bin_residual == bin_capacity {
        score += 6.0;
        // But opening a new bin is attractive early in the stream.
        score -= 4.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // Or when the item fits nothing else.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild penalty for very small post residuals (unusable slivers),
    // unless they are exactly zero (perfect fill).
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically, scaled by how full the stream is.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64 * (0.5 + t);

    // Strong reward when this bin is the only fitting option (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize small leftovers that become dead space.
            score += 6.0;
        }
    }

    // Prefer bins tighter than average (best-fit flavor), damped over time.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.5 * diff * (1.0 - 0.5 * t);

    // New-bin candidate: only attractive when nothing fits well or residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).abs();
        if fitting_bins_count == 0 || (post_residual as f64) < fragmentation * 20.0 {
            score -= 15.0;
        } else {
            score += 25.0;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.15 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 8.0 * poly;

    // Penalize waste scaled by open-bin pressure
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).powi(2);
    score += 4.0 * pressure * norm_pr * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 6.0 * tight * tight * (0.5 + 0.5 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 3.0 * fit_next * (nx / cap) * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins deviating from mean residual late in stream
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * progress - 1.5 * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 create
    // "dead space classes". Residuals that are multiples of 10 are more
    // likely to be reusable by future items, so reward them.
    let post = post_residual;
    let residue_class = (post % 10) as f64;
    if post > 0 {
        if post % 10 == 0 {
            score -= 6.0; // perfectly aligned residual, highly reusable
        } else if post < 10 {
            score += 12.0 + (10 - post) as f64; // tiny dead space, nearly unusable
        } else {
            score += residue_class * 0.8; // penalize misaligned residuals
        }
    } else {
        score -= 15.0; // perfect fill: strongly reward
    }

    // Integer-division thresholds on post_residual relative to capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post > half {
        score -= 4.0; // bin still half-empty, keep it attractive
    } else if post > quarter {
        score -= 1.5;
    } else if post > 0 {
        score += 3.0; // narrow slot, deprioritize unless last chance
    }

    // Coupling with the lookahead item: if the next item fits exactly into
    // post_residual, this is a harmonic pairing — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size < post {
            let pair_res = post - next_item_size;
            if pair_res % 10 == 0 {
                score -= 5.0;
            }
            score += (pair_res % 10) as f64 * 0.5;
        }
        // If next item cannot fit here anyway, mild penalty for wasted lookahead
        if next_item_size > post && post > 0 {
            score += 2.0;
        }
    }

    // Last-chance bin logic: if this is the only fitting bin, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: keep the empty bin neutral-to-slightly
    // unattractive so we prefer filling existing bins, but attractive when
    // open bins are fragmented (high mean residual spread / many bins).
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 * 0.7 + mean_residual * 0.05;
        score += 4.0 - fragmentation * 0.3;
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing else fits: must open new bin
        }
    }

    // Stream progression: late in the stream, prefer tight packing
    // (aggressively minimize post_residual) since fewer chances remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.6 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 12.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize gaps that cannot fit any plausible future item (below min size 1 is fine,
    // but gaps just under common small sizes are dead weight).
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize leaving a gap that next item cannot use and that is small (dead space lock-in).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 10.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make empty bins unattractive unless residuals elsewhere are tiny/dead.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
    }

    // Align with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: post_residual == next_item_size -> strong bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score += 0.35 * lookahead_gap;
        }
        // If next item can chain into this bin's remainder, extra reward.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (good fits).
    let res_f = post_residual as f64;
    let dev = res_f - mean_residual;
    score += 0.25 * dev;

    // Penalize leaving dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect closure: item exactly fills the bin.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    // New-bin candidate: mild penalty so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if lookahead would perfectly fill a fresh bin, allow opening.
        if next_item_size == bin_capacity {
            score -= 60.0;
        }
    }

    // Stream progression: later in the stream, tighten up (avoid waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.10 * res_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small but nonzero.
    if post_residual == 0 {
