    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize slightly, scaled by how much space is wasted.
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with below-average residual (concentrate waste in few bins).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (residual_f - mean_residual);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced early, increased late.
        score += 10.0 + 40.0 * progress;
        // Opening a new bin is cheaper if many bins are already open (spread load)
        // and the item is large relative to capacity.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    } else {
        // Existing bin: mild reward late in stream.
        score -= 5.0 * progress;
    }

    // Fragmentation guard: avoid leaving residuals that are too small to be useful
    // for typical items (below 10) but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (small post_residual); later, tolerate slack
    // to keep bins flexible. Coupling term is a smooth cubic in norm_pr scaled
    // by a smooth progress-based weight.
    let w = 0.5 + 0.5 * progress; // weight grows smoothly from 0.5 to 1.0
    let poly = norm_pr * norm_pr * (3.0 - 2.0 * norm_pr); // smoothstep-like in [0,1]
    score += w * poly * 20.0;

    // Reward near-perfect fits more aggressively via an exponential dip
    if post_residual == 0 {
        score -= 15.0;
    } else {
        let tightness = (-norm_pr * 8.0).exp(); // large when post_residual small
        score -= 6.0 * tightness * (1.0 - progress);
    }

    // Penalize dead space that cannot fit the lookahead item (smooth coupling)
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let waste = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 5.0 * waste * (1.0 + progress);
    } else if next_item_size > 0 {
        // reward bins whose leftover still fits the next item
        score -= 3.0 * (1.0 - norm_pr);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mild penalty when many bins are open and this one is relatively full
    // (encourage consolidation across the pool, smoothly scaled)
    let rel_fullness = 1.0 - norm_pr;
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * rel_fullness;

    // Deviation from mean residual: prefer bins near the mean to keep pool balanced,
    // with a smooth quadratic coupling
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev / cap;

    // New-bin candidate: keep it neutral-to-slightly-high so real bins with
    // good fits win, but poor fits in all bins let the new bin win.
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residues modulo common item sizes ---
    // Residuals that are multiples of 10 are "harmonically perfect" (likely exact
    // future fits for the 10..80 regime); reward them strongly.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 20 == 0 {
        -14.0
    } else {
        // awkward residue: penalize dead space
        let r = (pr % 10) as f64;
        2.0 + 0.35 * r
    };
    score += harmonic_bonus;

    // Integer-division thresholds on post_residual: small residuals are fine,
    // mid-range residuals are wasteful.
    let pr_div = pr / 10; // floor class 0..10
    score += match pr_div {
        0 => -4.0,
        1 => 0.0,
        2 => 1.5,
        3 => 2.5,
        _ => 4.0,
    } as f64;

    // --- Lookahead coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chain fit: reward, scaled by how tight the chained fit is
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot chain here: mild penalty, worse if gap is small
            let gap = (next_item_size - pr) as f64;
            score += 3.0 + 0.15 * gap.min(50.0);
        }
    }

    // --- Last-chance bin: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tightest (already via post_residual)
        score += 1.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (high mean residual fragmentation) or few bins fit the item.
        let fragmented = (mean_residual - post_residual as f64).abs();
        score += 45.0
            - 0.25 * mean_residual
            - 8.0 * (fitting_bins_count as f64)
            - 5.0 * fragmented.min(20.0);
        // late in the stream, discourage proliferation of near-empty bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // --- Mean residual regularization: avoid extremes vs. population ---
    score += 0.08 * (post_residual as f64 - mean_residual).abs();

    // Slight preference to keep number of open bins low early on
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (size 1) are still usable, but residuals that
    // fall into the classic "dead zone" (1..=9 in typical streams, scaled
    // here for unknown distributions) waste capacity. Penalize heavily.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, prefer tightening existing
    // bins over spreading; add mild penalty proportional to open count.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual can't host the next item -> likely dead space.
        score += 10.0;
    }

    // Prefer bins tighter than the mean residual (better packing density).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild progression term: early in the stream, slightly discourage
    // hoarding near-perfect bins; later, be stricter about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual <= 9 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - match_gap / (bin_capacity as f64)).max(0.0);
    }

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Favor tight fits relative to mean residual across open bins.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild preference for keeping fewer open bins when many are open.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Slight progression bias: as stream advances, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline, discouraged unless residuals are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that cannot hold even the smallest future item (size >= 1),
    // scaled by how much of the bin is wasted.
    if post_residual > 0 && post_residual < item_size {
        score += 2.5 * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fill is extremely desirable.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 3.0 * fill;
        } else {
            // Next item will not fit here: penalize leaving large residuals that trap it.
            let leftover = (next_item_size as f64) - (post_residual as f64);
            score += 0.02 * leftover;
        }
    } else {
        // Last item: prefer closing bins completely.
        score -= 2.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin offers
    // a reasonable fit. Compare against mean residual across open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin; grows with number of open bins.
        score += 3.0 + 0.15 * open_bins_count as f64;
        // If open bins are fragmented (high mean residual but poor fits), opening fresh
        // can be justified: reduce penalty when mean residual is large.
        score -= 0.02 * mean_residual;
        // Early in the stream, new bins are cheaper; late, consolidation matters.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 4.0 * progress;
        // Large items justify fresh bins more (they leave little residual anyway).
        score -= 0.02 * item_size as f64;
    } else {
        // Existing bin: slight reward for keeping bins consolidated.
        score -= 0.5;
        // Prefer bins with residual below the mean (using up the most-fragmented space).
        if (bin_residual as f64) < mean_residual {
            score -= 0.8;
        } else {
            score += 0.4;
        }
    }

    // Mild global pressure: many open bins -> encourage filling existing ones harder.
    score -= 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Smooth interaction: reward tight fits more strongly as stream progresses
    score -= (1.0 - fit_norm) * (1.0 + 6.0 * p2 + 4.0 * p3) * 12.0;

    // Smooth penalty for large post-residual dead space, weighted by progress
    score += fit_norm * fit_norm * (2.0 + 10.0 * progress) * cap * 0.25;

    // Coupling with mean residual: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.15 * (1.0 + progress);

    // Last-chance bonus (smooth via inverse fitting count)
    if fitting_bins_count == 1 {
        score -= 8.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        score -= 4.0 / fitting_bins_count as f64;
    }

    // Lookahead: reward bins whose post-residual can host the next item (smooth margin)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let margin = (pr - ns) / cap;
            score -= 10.0 * (1.0 - margin * margin);
        } else {
            let gap = (ns - pr) / cap;
            score += 6.0 * gap * gap * cap * 0.1;
        }
    }

    // Mild preference for consolidating into fewer bins early
    score += open_bins_count as f64 * (1.0 - progress) * 0.05;

    // New-bin candidate: penalize opening a bin unless residuals are tight
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).max(0.0).min(1.0);
        score += 18.0 - 14.0 * tightness * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i32; // decile class of residual
    score += match class {
        0 => -8.0,           // near-perfect fit: reward heavily
        1 => -4.0,           // small dead space: still good
        2 | 3 => 2.0,        // awkward mid-small residual
        4 | 5 => 5.0,        // half-ish residual: mediocre
        6 | 7 => 7.0,
        8 | 9 => 9.0,        // large residual left: wasteful placement
        _ => 10.0,
    };

    // Modulo-10 harmonic band on post_residual (classic dead-space traps).
    let m = (post_residual % 10) as f64;
    score += 0.3 * m;

    // Lookahead: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0; // chain placement possible: strong reward
            // exact harmonic match bonus
            let gap = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // penalty scaled by how badly next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.05 * miss;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 2 {
        score += 1.0; // many alternatives: be pickier
    }

    // New-bin candidate: keep it as a fallback with moderate default score,
    // but allow opening a new bin when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score = 25.0 + frac * 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 3.0;
        }
        if fitting_bins_count == 1 {
            score += 20.0; // never open new bin when only one fits
        }
    }

    // Progression: slightly tighten tolerance late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * frac;

    // Mean-residual coupling: prefer bins close to mean (balanced packing).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit any plausible
    // future item are worthless. Penalize unusable small gaps heavily.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.10);
    if (post_residual as f64) < dead_threshold {
        score += 30.0 + (dead_threshold - post_residual as f64) * 4.0;
    } else if (post_residual as f64) < 20.0 {
        // semi-dead zone: moderate penalty
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: post_residual close to 0 (but not dead) is great.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Lookahead coupling: if the next item fits exactly into the resulting
    // residual, strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 5 {
            score -= 15.0;
        } else {
            score -= 5.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item can't use this residual: it's likely dead space
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Mean residual context: if this bin is much emptier than average,
    // using it consolidates space; if it's the fullest, slight penalty.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // New-bin candidate handling: opening a new bin wastes the residual of
    // the empty bin slot; make it costly unless current bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
        // If no open bin leaves a usable residual, allow new bin more readily
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual (perfect chaining), reward when it still fits.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            // reward proportional to how snugly the next item fits
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space that is too small
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: just minimize waste
        score += 5.0;
    }

    // Penalize residual far below mean (fragmented bin) unless it's a tight fit.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.15 * (-dev);
    } else {
        score -= 0.05 * dev;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so we only open
    // a new bin when open bins have genuinely bad residuals.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Early in the stream, be more willing to spread items (favor new bins);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    // Mild penalty for leaving very small unusable slivers (1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: penalize high post_residual relative to capacity
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powf(1.7) * bin_capacity as f64;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here afterwards; slight penalty for leaving awkward gap
        score += 0.15 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Few fitting bins: scarcity pressure
    if fitting_bins_count > 0 {
        score -= 1.5 / fitting_bins_count as f64;
    }

    // Global state coupling: prefer filling bins whose residual is below mean (tighter bins)
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in stream, consolidate aggressively; early, allow new bins
    let horizon = 1.0 - progress;
    if bin_residual == bin_capacity {
        // new-bin candidate: cheap early, expensive late
        score += 8.0 * progress - 2.0 * horizon;
        // open new bin if item is large and current bins are fragmented
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 5.0;
        }
    } else {
        // late stream: reward using existing bins more
        score -= 4.0 * progress;
    }

    // Penalize many open bins with large residuals (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual penalized more heavily as stream progresses
    let progress_coupling = norm_pr * (1.0 + 3.0 * progress * progress);
    score += 20.0 * progress_coupling * norm_pr;

    // Quadratic dead-space penalty, modulated by mean residual
    let dead = norm_pr * norm_pr;
    let mean_coupling = 1.0 + (mean_residual / cap - norm_pr).abs();
    score += 15.0 * dead * mean_coupling;

    // Cubic interaction between item size and progress: big items early favor tight fills
    score -= 10.0 * norm_item * norm_item * (1.0 - progress) * (1.0 - norm_pr);

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_kernel = (norm_pr - nx).abs();
        score -= 8.0 * (-4.0 * fit_kernel * fit_kernel).exp() * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward when few fitting bins
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 12.0 * scarcity * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Penalize opening new bins when many open bins exist and progress is high
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 25.0 * crowd * (0.3 + 0.7 * progress) * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes
    // (multiples of 10 or >= 20), penalize dead space below 10.
    let post = post_residual as u32;
    if post == 0 {
        score -= 60.0; // perfect fill
    } else if post < 10 {
        score += 45.0; // dead space: nearly unusable
    } else if post % 10 == 0 {
        score -= 12.0; // harmonic multiple of 10
    }

    // Integer-division thresholds: residual buckets of 25
    let bucket = post / 25; // 0..4
    score -= bucket as f64 * 8.0;

    // Lookahead: if the next item fits exactly into the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 55.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            if slack < 10.0 {
                score -= 25.0; // near-exact chain
            } else {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize small remainders
            if post < next_item_size {
                score += 8.0;
            }
        }
    } else {
        // last item: prefer tightest fill
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (would leave big residual anyway) or few bins open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score += 25.0 - 30.0 * frac;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mean residual coupling: when open bins are loose on average, prefer bins
    // tighter than the mean (small residual = tight fit).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let pr = post_residual as f64;
    score += pr;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Dead space zone: residuals too small for typical items (1..100 unknown, but
    // gaps below ~10 are nearly unusable; gaps in [10, 25] risk stranding).
    if pr > 0.0 && pr < 10.0 {
        score += 60.0; // absolute dead space
    } else if pr >= 10.0 && pr <= 25.0 {
        score += 12.0 * (1.0 - pr / 25.0); // risky gap
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few bins exist or fit is good.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin starts with residual = capacity - item_size; the base pr term
        // already covers fit quality. Add pressure scaled by open bins and progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // Opening a new bin is attractive if no open bin fits well.
        if post_residual > 30 {
            score -= 5.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        score -= 25.0;
        // Unless it creates dead space.
        if pr > 0.0 && pr < 10.0 {
            score += 30.0;
        }
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is large and would not fit after this placement, mild penalty
    // for consuming a bin that could host it.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins whose residual is near/below the mean
    // (close them out) when mean is high.
    if !is_new_bin && mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 6.0 * (1.0 - rel);
        } else {
            score += 3.0 * (rel - 1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's post-residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus: post_residual close to next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack * 0.15);
    }
    // Penalize post-residual too small to ever fit the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }
    // Penalize unusable tiny residual (< 10, minimum item size).
    if post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual: bins tighter than average are preferred.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current bin leaves bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin is fine if it can host next item too
        }
    }

    // Late in stream, consolidate: prefer existing bins over opening new ones.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize dead space: post_residual that is too small for any plausible item (min size 1..100 unknown, use 10 as soft floor).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // nearly unusable sliver
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 + (post_residual as f64 - next_item_size as f64).sqrt() * 5.0;
        } else {
            // next item won't fit here: mild penalty proportional to waste
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
        }
    } else {
        // last item: prefer filling bins as fully as possible
        score -= item_size as f64 * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when open bins exist and item is small.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so it's only chosen when fits are terrible.
        score += 35.0;
        if open_bins_count > 0 {
            // Larger items justify a fresh bin more (they leave large residual usable).
            let large = (item_size as f64 / bin_capacity as f64) > 0.6;
            if !large {
                score += 25.0;
            } else {
                score -= 20.0;
            }
        }
        // Early in stream, opening bins is cheap; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Prefer bins whose residual is already below mean (consolidating fragmentation).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff.min(50.0) * 0.4;
        } else {
            score += (-diff).min(50.0) * 0.1;
        }
    }

    // Slight penalty for proliferating bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like basis
    score += poly * pr * pr / cap;      // penalize large residuals more as stream advances

    // Dead-space penalty: squared normalized residual, weighted by progress.
    let norm_res = pr / cap;
    score += 8.0 * norm_res * norm_res * (0.5 + t);

    // Reward tight fits: subtract for small post-residual, amplified late in stream.
    let tightness = 1.0 - norm_res;
    score -= 6.0 * tightness * tightness * (0.3 + 0.7 * t);

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mean-residual context: bins with residual far below mean are more precious.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 3.0 * dev;

    // Crowding: mildly discourage spreading across many bins early.
    score += (open_bins_count as f64) * (1.0 - t) * 0.15;

    // New-bin candidate: make an empty bin moderately attractive only when
    // the residual would otherwise be badly fragmented.
    if bin_residual == bin_capacity {
        score = 25.0 - 15.0 * t + 0.5 * pr / cap;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are heavenly.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class by integer division thresholds of post_residual.
        let cls = match post_residual {
            0..=9 => 0,
            10..=19 => 1,
            20..=34 => 2,
            35..=49 => 3,
            50..=69 => 4,
            _ => 5,
        };
        score -= (5 - cls) as f64 * 6.0;

        // Modulo-10 harmonic bonus: residuals divisible by 10 pair well with
        // common item sizes (multiples of 10).
        if post_residual % 10 == 0 {
            score -= 8.0;
        }

        // Coupling with next item: reward residuals that exactly or nearly
        // accommodate the lookahead item.
        if next_item_size > 0 && next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 60.0;
            } else if gap <= 10 {
                score -= 25.0 - gap as f64;
            } else {
                score -= 5.0;
            }
        } else if next_item_size > 0 {
            // Next item won't fit here: penalize small dead zones more than
            // large usable ones via a harmonic sine-shaped term.
            let frac = post_residual as f64 / cap;
            score += (frac * std::f64::consts::PI).sin() * 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when no
    // open bin offers a decent fit (post_residual small or lookahead match).
    if bin_residual == bin_capacity {
        score += 55.0 + 0.15 * open_bins_count as f64;
    }

    // Slight pressure toward tight bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).abs() * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Dead-space penalty: small unusable gaps are the worst outcome ---
    // Define "unusable" as post_residual smaller than the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        // unreachable in practice, but kept for safety
        score += 1000.0;
    }
    // Small residual gaps (below typical item scale) are penalized super-linearly.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Medium gaps that cannot host the lookahead item are also dead-ish.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward if post_residual can still host the next item (keeps bin alive).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // --- Tight fit reward: prefer bins where the item fills most of the residual ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // --- Perfect fit bonus ---
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Open bins pressure: when many bins are open, consolidate ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // --- Mean residual coupling: penalize bins whose residual is far above mean
    // (they are wasteful) unless they are the only fitting option ---
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_diff;

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // --- New-bin candidate handling: only attractive when nothing fits well ---
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base cost of opening a bin; reduced when current bins are crowded.
        let mut new_bin_cost = 55.0;
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0; // forced open
        }
        // If open bins have lots of slack, opening is less urgent.
        new_bin_cost += 0.1 * mean_residual;
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals too small to hold typical future items
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 200.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 150.0 + 0.5 * next_item_size as f64;
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
        // perfect chain: next item exactly fills the remainder
        if post_residual == next_item_size {
            score -= 250.0;
        }
    }

    // Prefer tight fits relative to mean residual
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no good open option exists
    if bin_residual == bin_capacity {
        score += 60.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && bin_residual >= next_item_size + item_size {
            score -= 40.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward (best-fit core)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that nothing (even the next item) could use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidation into existing bins
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Time horizon: early stream, be picky about large residuals; late stream, just fill
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins already tight are precious, loose bins absorb
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        // Penalize opening new bins normally, but relax late in stream
        score += 30.0 + desperation - 15.0 * t;
        // If next item is large and this item is small, new bin keeps flexibility
        if next_item_size > 60 && item_size < 40 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Smooth progress-dependent decay of residual value: late stream, small residuals matter more
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 30.0 * poly;

    // Reward tight fits with a smooth quadratic bonus
    let tight = 1.0 - norm_pr;
    score -= 12.0 * tight * tight;

    // Lookahead: penalize if next item cannot use this residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr - nx).max(0.0) / cap;
        score += 10.0 * (1.0 - usable) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep neutral-ish, slightly penalized early, relaxed late
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits strongly (non-linear in post_residual).
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(4);

    // Harmonic class of post_residual: dead-space classes.
    // Residuals <= 10 are effectively unusable for min-size items -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with common item sizes; odd/prime residuals create fragmentation.
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 8.0;
    } else if r10 == 5 {
        score += 2.0;
    } else if r10 % 2 == 1 {
        score += 3.5;
    }

    // Integer-division thresholds: can the next item fit here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: strong reward, scaled by snugness.
            let snug = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - snug / (bin_capacity as f64));
            if post_residual % next_item_size == 0 {
                score -= 10.0; // exact divisor: perfect harmonic pairing
            }
        } else {
            // Next item won't fit here; if residual is small this bin is "done"
            // which is fine, but mid-range residuals are wasted.
            if post_residual >= 10 {
                score += 6.0;
            }
            // If next item barely misses, penalize (near-miss fragmentation).
            let miss = next_item_size - post_residual;
            if miss <= 5 {
                score += 4.0;
            }
        }
    } else {
        // Last item: only tightness matters.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // (would leave awkward residual elsewhere) or no good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 60 {
            score -= 12.0; // big items start fresh bins happily
        } else if fitting_bins_count <= 1 {
            score -= 5.0;
        } else {
            score += 15.0 + 10.0 * (1.0 - progress); // early: prefer filling
        }
        // Discourage hoarding many open bins late in the stream.
        score += (open_bins_count as f64).powf(0.7) * 2.0;
    }

    // Mean-residual coupling: if average residual is high, prefer bins that
    // reduce dispersion (move residual toward mean).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (low post_residual), but strictly penalize
    // "dead space": small unusable gaps that no item (min size 1..100 range,
    // practically >=10) can fill.
    score += post_residual as f64;

    // Strict dead-space penalty: gaps that are small but nonzero are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0; // only fillable by small items
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure, ideal
    }

    // Reward using an existing bin vs opening a new one (bin count pressure).
    if bin_residual != bin_capacity {
        // existing bin: subtract pressure term scaled by how many bins are open
        score -= 8.0 + (open_bins_count as f64) * 0.5;
    } else {
        // new-bin candidate: penalize mildly; only chosen when fits are bad
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin to avoid bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving a gap that the next item can still fit into.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 10.0;
            // extra reward if the next item would nearly fill the leftover
            let gap_after_next = post_residual as f64 - next_item_size as f64;
            if gap_after_next < 5.0 {
                score -= 8.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // leftover too small for the lookahead item: penalize mildly
            score += 6.0;
        }
    }

    // Late-stream pressure: as the stream progresses, favor consolidating
    // into existing bins rather than spawning new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: if open bins are generally loose (high mean
    // residual), discourage opening yet another bin.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when the next item fits exactly
    // into the post-residual (perfect chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: post_residual consumed exactly by next item
        } else if post_residual >= next_item_size {
            // next item fits, penalize proportional leftover slack after the chain
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack_after_next / bin_capacity as f64);
            score += 0.3 * slack_after_next;
        } else {
            // next item does NOT fit into this bin's leftover: dead space risk
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Compare post_residual relative to mean residual across open bins:
    // leaving more than average residual is wasteful; leaving less is good.
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item,
    // unless the new bin enables a perfect lookahead chain.
    if bin_residual == bin_capacity {
        let mut bonus = 12.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            bonus -= 10.0;
        }
        // Late in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        bonus *= 1.0 + progress;
        score += bonus;
    }

    // Slight penalty when many bins are already open (consolidation pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tightly bounded so it never
    // overwhelms the residual term for very small post_residual).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * (1.0 - tight).powi(6);

    // Penalize dead space that cannot fit the lookahead item: prefer bins
    // whose post_residual can still host next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
            // Extra reward when the lookahead item would fit snugly too.
            let nxt_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 4.0 * (1.0 - nxt_tight).powi(4);
        } else {
            // Dead space for the next item; worse when dead space is large
            // but still below the next item's size (unusable gap).
            let gap = (post_residual as f64).max(0.0);
            score += 2.0 + 3.0 * (gap / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Mild penalty when many bins compete equally (encourage consolidation).
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer filling existing bins harder (penalize leaving big residuals).
    let fill = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 1.5 * mean_residual / bin_capacity as f64 * (1.0 - fill);

    // Time horizon: early in the stream, be slightly more willing to open
    // new bins (avoid fragmentation later); late in the stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus early-stream discount.
        score = bin_capacity as f64 * 0.9 - 6.0 * (1.0 - progress);
        // If item nearly fills a fresh bin, opening is attractive.
        score -= 5.0 * (item_size as f64 / bin_capacity as f64).powi(2);
    } else {
        // Late stream: reward using open bins more aggressively.
        score -= 4.0 * progress;
    }

    // Encourage opening new bins when existing open bins are already crowded
    // (small mean residual means little room left anywhere).
    if mean_residual < 15.0 && bin_residual == bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= poly * 400.0 * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 60.0 * progress;

    // Penalize dead space relative to mean residual, scaled by progress
    score += (pr - mean_residual).abs() * (0.3 + 0.7 * progress);

    // Penalize when this bin is the only fitting bin (last-chance pressure)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: favor bins that can also fit the next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 12.0 * (pr - next_item_size as f64) / cap;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Mild penalty on opening new bins early, stronger later
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover space divides the capacity
    let pr = post_residual as u32;
    if pr > 0 {
        // Harmonic penalty: capacity / gcd(post_residual, capacity) -> fewer classes = better
        let gcd = {
            let (mut a, mut b) = (pr, bin_capacity);
            while b != 0 { let t = a % b; a = b; b = t; }
            a
        };
        let harmonic = cap / gcd as f64;
        score += harmonic * 0.5;

        // Exact fraction classes: post_residual at 1/2, 1/4, 1/5, 1/10 of capacity are prime reuse spots
        let frac = pr as f64 / cap;
        for (f, w) in [(0.5, 6.0), (0.25, 4.0), (0.75, 4.0), (0.2, 3.0), (0.4, 2.0), (0.6, 2.0), (0.8, 2.0), (0.1, 1.5), (0.3, 1.0), (0.7, 1.0), (0.9, 1.0)] {
            if (frac - f).abs() < 0.005 {
                score -= w;
            }
        }
    } else {
        score -= 10.0; // perfect closure
    }

    // Integer division threshold on post_residual: small dead zones are toxic
    if pr > 0 && pr < 10 {
        score += 15.0 * (10 - pr) as f64 / 10.0;
    }

    // Lookahead coupling: can next item exactly fill post_residual? (harmonic complement)
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let npr = pr - next_item_size;
            if npr < 10 { score -= 8.0; } // chain of small fills
            score -= (npr as f64).ln().max(0.0);
        } else {
            // next item cannot fit here; bin will sit idle -> mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bin fit would be very poor
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual as f64 / cap > 0.5 { score += 8.0; } // opening fresh bin wastes capacity
        if next_item_size > 0 && next_item_size >= item_size { score -= 4.0; }
    }

    // Stream progression: tighten packing later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0 * (10.0 - dead); // tiny gap -> big penalty
    }
    // Medium gaps (10..30) can only fit small future items: moderate penalty.
    if dead >= 10.0 && dead < 30.0 {
        score += 0.6 * (30.0 - dead);
    }

    // Perfect or near-perfect fits are rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave the bin with a tiny dead gap, penalize.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual as u32 - next_item_size) < 10 && (post_residual as u32 - next_item_size) > 0 {
        score += 12.0;
    }

    // New-bin candidate: keep it neutral-ish but slightly penalized so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Late in the stream, opening new bins is more acceptable.
        score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mean residual coupling: prefer bins close to mean residual (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: prefer minimal post residual (tight packing).
    let mut score = post;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next > 0.0 && next <= post {
        let slack = post - next;
        // Perfect chain (post == next) gets a big bonus.
        score -= 40.0 * (1.0 - slack / cap) - 20.0;
    } else if next > 0.0 {
        // Next item cannot fit here: penalize wasted space, scaled by progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * (post / cap) * (0.5 + progress);
    }

    // Compare against mean residual: bins with residual below mean are
    // "tight" bins; placing there is good (consolidates fragmentation).
    score -= 0.5 * (mean_residual - post);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current item leaves
    // terrible dead space in every open bin. Penalize fresh bin mildly,
    // heavily if item is small relative to capacity.
    if bin_residual == bin_capacity {
        let small_item = item_size as f64 / cap;
        score += 8.0 * (1.0 - small_item);
        // Open a new bin only if it enables a perfect next-item fit.
        if next > 0.0 && (cap - item_size as f64 - next).abs() < 1.0 {
            score -= 30.0;
        }
    }

    // Slight preference for fewer open bins (encourage closing tight bins).
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect packing, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize unusable dead space: residual too small for any plausible item (min size 1, but
    // small leftovers are waste). Use a soft quadratic penalty on small positive post_residual.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 8.0;
        }
    }

    // Lookahead: reward if next item fits into the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 + 0.5 * next_item_size as f64;
        } else {
            // Penalize leaving a gap that just barely misses the next item.
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += 0.3 * gap;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin gets a dynamic penalty that decays over the stream
    // and grows with how many bins are already open, so we only open bins when truly needed.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 120.0 + 8.0 * open_bins_count as f64 - 60.0 * progress;
        // If no open bin can fit at all, opening is unavoidable: drop the penalty.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Global state coupling: if mean residual is large, prefer bins above the mean
    // (drain fatter bins first), keep smaller residuals for future small items.
    if bin_residual as f64 > mean_residual {
        score -= 15.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits with smooth polynomial coupling of post_residual to progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score -= (1.0 - norm_pr) * (1.0 + 2.0 * progress) * 8.0;
    score -= norm_pr * norm_pr * (1.0 - progress) * 4.0;

    // Penalize residuals that cannot fit the next item (dead space), smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= (1.0 - (pr - nxt) / cap) * 6.0;
        } else {
            score += (nxt - pr) / cap * 10.0 * (0.5 + progress);
        }
    }

    // Last-chance bonus: only bin that fits -> strong reward.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Coupling with mean residual: prefer bins deviating from mean (keep diversity).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05 * (1.0 - progress);

    // New-bin candidate: smooth penalty growing with open bins and progress,
    // relaxed when the item fits poorly everywhere (high post_residual gap).
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 6.0 + (open_bins_count as f64).ln() * 3.0 + progress * 5.0;
        if pr >= 20.0 {
            score -= (pr / cap) * 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual ---
    // Class 0: post_residual == 0 (perfect fit) -> strong reward
    if post_residual == 0 {
        score -= 250.0;
    }
    // Class 1: tiny dead space (1..=9) -> unusable for items >=10, penalize
    else if post_residual <= 9 {
        score += 60.0;
    }
    // Class 2: post_residual divisible by 10 -> aligns with 10-multiple item sizes
    else if post_residual % 10 == 0 {
        score -= 40.0;
    }
    // Class 3: post_residual divisible by 5 -> half-harmonic
    else if post_residual % 5 == 0 {
        score -= 20.0;
    }

    // Integer-division threshold on post_residual: floor(post/25) harmonic bands
    let band = post_residual / 25; // 0..4
    score -= (band as f64) * 15.0;

    // --- Lookahead harmonic coupling ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: big reward, scaled by how tightly it fits
            let slack = post_residual - next_item_size;
            score -= 120.0;
            if slack == 0 {
                score -= 80.0; // chain of perfect fits
            } else if slack % 10 == 0 {
                score -= 25.0;
            }
        } else {
            // next item cannot use this residual: dead-space penalty grows
            // with harmonic closeness (mod 10 residue mismatch)
            let mismatch = post_residual % 10;
            score += 30.0 + (mismatch as f64) * 3.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        // This is the only bin that fits; strongly favor using it
        score -= 90.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild penalty to prefer tighter fits elsewhere
        score += (fitting_bins_count as f64).ln() * 10.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline score of full capacity, discounted by stream position
        // and by how desperate the open-bin situation is.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64;
        score -= 70.0 * progress; // later in stream, slightly prefer reuse... but:
        if fitting_bins_count == 0 {
            score -= 400.0; // nothing fits anywhere: must open
        }
        if fitting_bins_count == 1 {
            score += 60.0; // a last-chance open bin exists: prefer it over new bin
        }
        // Avoid opening new bins when mean residual is large
        score += (mean_residual - 20.0).max(0.0) * 4.0;
        // Harmonic: new bin residual is 100, divisible by 10/25 -> small bonus
        score -= 15.0;
    }

    // --- Open-bin pressure: many open bins -> consolidate ---
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * 2.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Any residual below the minimum item size (1) is impossible, but
    // residuals that are too small for typical future items are "dead".
    // Treat gaps < 10 as fully dead; gaps 10..=30 as partially dead.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits strongly (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer reusing existing bins
    // over opening new ones; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // heavily reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize leaving a mid-size gap
            score += 8.0;
        }
    }

    // Late in the stream, tighten up: dead space matters more as bins close out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.3 * progress;

    // Slight nudge toward bins below mean residual (balancing).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the new residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to tightness of the pair fit.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 120.0 - pair_waste * 0.8;
        } else {
            // Next item cannot use the residual: penalize residual slightly more.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize residuals far below mean (fragmented dead space), reward large residuals kept tight.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 50.0;
        }
    }

    // Early in stream: be slightly more open to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 20.0;

    // Discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, keep bins flexible; late, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual) more strongly as the stream progresses.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 10.0 * tightness * (1.0 + progress);

    // Penalize residual that is too small to be useful later (dead space).
    // Assume future items are at least ~1; residuals below 10 are nearly dead.
    if post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Last-chance bin: strong bonus to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Reward bins whose residual is above the mean (use the roomiest bins first),
    // unless this bin is the tightest fit.
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Lookahead: if the next item could exactly fill the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item closure
        } else if next_item_size < post_residual {
            // Leaving just enough room for the next item is good.
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            // Post-residual too small for the next item: mild penalty, scaled by waste.
            let waste = (post_residual as f64) / (next_item_size as f64);
            score += 5.0 * waste.min(2.0);
        }
    }

    // New-bin candidate: default mild penalty so we prefer existing bins,
    // but allow opening a new bin when existing fits are poor and bins are many.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.6 * (bin_capacity as f64);
        if poor_fit && open_bins_count > 3 {
            score -= 20.0; // better to open fresh bin than stuff badly
        } else {
            score += 15.0; // discourage opening new bins by default
        }
    }

    // Late-stage urgency: strongly prefer filling bins to completion.
    if progress > 0.8 && post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth polynomial coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Quadratic dead-space penalty, stronger late in the stream
    score += 30.0 * progress * norm_pr * norm_pr;

    // Penalize very tight fits slightly less as stream progresses (want to close bins)
    let tightness = (item_size as f64 / cap) * (1.0 - norm_pr);
    score -= 10.0 * progress * tightness;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item could use the post_residual, reward leaving useful space
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            score -= 8.0 * (1.0 - (next / pr).powi(2));
        } else {
            score += 5.0 * ((next - pr) / cap);
        }
    }

    // Mild penalty when this bin's residual deviates from mean (keep balance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make empty bins moderately attractive only when few bins fit
    if bin_residual == bin_capacity {
        score = pr + 12.0 + 15.0 * (fitting_bins_count as f64).recip() - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes
    // relative to capacity fractions. Small leftovers in "good" classes get rewarded.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Perfect / near-perfect fits
    if pr == 0 {
        score -= 50.0;
    } else if pr <= tenth {
        score -= 25.0;
    } else if pr <= fifth {
        score -= 10.0;
    }

    // Modulo-10 harmonic classes: leftovers divisible by 10 pair well with
    // typical item granularities.
    let m10 = (pr % 10) as f64;
    score -= (10.0 - m10) * 0.4;

    // Dead-space band: leftovers that no item (min size 1..100 unknown) can use well.
    // Penalize mid-range leftovers (awkward zone) more than extreme small ones.
    if pr > fifth && pr < quarter * 2 {
        score += 8.0;
    }

    // Next-item lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item can't fit here; slight penalty proportional to overflow
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when many bins are already open with room.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // But if mean residual of open bins is small, a fresh bin is fine.
        score -= mean_residual * 0.2;
    }

    // Prefer filling bins with large residual less tightly early on (keep flexibility),
    // tighten later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 / cap) * (1.0 - progress) * 5.0;

    // Slight preference for bins below mean residual (balance via tightest-fit bias)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.97;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly with little waste
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Next item won't fit here: penalize proportionally to wasted potential
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // Penalize small unusable dead space (< 10, minimum item size)
    if post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fits relative to mean residual
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer denser bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // Prefer bins where post_residual matches next item size exactly.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and few bins fit it.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (item_size as f64) / (bin_capacity as f64);
        let scarcity = (fitting_bins_count as f64).max(1.0).recip();
        let new_bin_bonus = 60.0 * pressure * scarcity * (0.3 + 0.7 * progress);
        score -= new_bin_bonus;
        // Keep fresh-bin option slightly penalized so tight existing fits win.
        score += 5.0;
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers).
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.05 * diff;

    // Mild preference for bins that are already fairly full.
    score += 0.1 * (bin_residual as f64);

    // Time horizon: early in the stream, be more selective about tight fits;
    // late in the stream, exploit tightness more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * tightness;

    // Discourage proliferation of open bins with large residuals.
    score += 0.01 * (open_bins_count as f64) * (bin_residual as f64) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a convex polynomial penalty
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: as stream advances, weight residual fit more strongly
    let progress_coupling = progress * (pr * pr) / (cap * cap);
    score += 4.0 * progress_coupling;

    // Dead-space penalty: residuals too small to be useful later
    let dead = if pr > 0 { (cap / pr.max(1.0)).ln() } else { 10.0 };
    score += 6.0 / (dead * dead + 1.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 5.0 * (n / cap) * (1.0 - norm_pr.abs() - n / cap).abs().min(1.0);
        } else {
            score += 2.0 * (n / cap) * (1.0 + progress);
        }
    }

    // Mean residual alignment: prefer bins close to mean residual (balanced packing)
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // Mild pressure against opening many bins
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // --- Harmonic class of the post-residual (mod-10 classes) ---
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "harmonically useful" (multiples of 5/10) are less wasteful
    let harmonic_bonus = match class {
        0 => 6.0,                    // perfectly aligned residual
        5 => 3.0,                    // half-aligned
        2 | 4 | 6 | 8 => 1.0,        // even, mildly reusable
        _ => 0.0,                    // odd dead space
    };
    score -= harmonic_bonus;

    // --- Integer-division thresholds on post_residual ---
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if pr == 0 {
        score -= 40.0;               // perfect fill: extremely desirable
    } else if pr < eighth {
        score += 12.0;               // tiny unusable sliver -> penalize
    } else if pr <= quarter {
        score -= 2.0;               // small but reusable
    }

    // --- Lookahead coupling: can the next item land in the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or near-exactly: reward proportional to tightness
            let gap = (pr - next_item_size) as f64;
            if gap == 0.0 {
                score -= 25.0;       // perfect chained fill
            } else if gap <= 5.0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item would NOT fit here: mild penalty scaled by overflow
            let over = (next_item_size - pr) as f64;
            score += (over / 20.0).min(8.0);
        }
    } else {
        // last item: any residual is pure waste
        score += 5.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;               // only bin that fits: strongly prefer using it
    } else if fitting_bins_count > 3 {
        score += 1.5;                // plenty of alternatives: less urgency
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are poor
        // and current item leaves a bad harmonic class in every open bin.
        let mean_bad = mean_residual / cap; // normalized mean residual
        score = 30.0 + mean_bad * 40.0 + (open_bins_count as f64) * 0.5;
        // If this item would leave a harmonically clean residual in an open bin,
        // discourage the new bin instead.
        if class == 0 || pr == 0 {
            score += 25.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // --- Mild best-fit sharpening relative to mean residual ---
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 100.0;
    }
    // General dead-space penalty: quadratic in wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 40.0;

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover: dead space confirmed.
        score += (post_residual as f64) * 0.8;
    }

    // Late in the stream, be more frugal with open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Prefer bins below mean residual (balancing leftovers for future items).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Slight preference for leaving room usable by typical items (>=10)
        if post_residual >= 10 {
            score -= 5.0;
        } else if post_residual > 0 {
            // dead space penalty
            score += 8.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good fills), penalize loose bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New empty bin candidate: neutral-ish baseline; only attractive when current bins
    // would leave large dead space relative to the lookahead item.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_residual - item_size) as f64;
        let waste_if_reuse = post_residual as f64;
        if waste_if_reuse > waste_if_open + (next_item_size as f64) * 0.5 {
            score -= 20.0; // opening a new bin keeps space better organized
        } else {
            score += 30.0; // discourage opening new bins when reuse is decent
        }
    }

    // Progression: early in stream, slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: strongly reward small post_residual (good fit).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that is too small to be useful later.
    // Items are 1..100; residual below ~10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 8.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Relative waste vs mean residual: prefer bins whose remaining space
    // deviates favorably (small residual relative to the fleet mean).
    score += 5.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Early in the stream: be more willing to spread load across bins
    // (keep residuals flexible); late: consolidate into tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 12.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling existing ones rather than opening more.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // NEW-BIN CANDIDATE handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Base penalty: prefer reusing open bins when reasonably good fits exist.
        score += 55.0;
        // But if the item is large and no tight fit exists, a fresh bin is fine:
        // reward when post residual leaves a big usable chunk.
        if item_size >= 60 {
            score -= 20.0;
        }
        // If next item would fit in the fresh bin's post residual, opening
        // a new bin preserves flexibility.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Late in stream with many open bins, strongly discourage new bins.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 + progress * 2.0);
    score -= 40.0 * poly;

    // Penalize large residuals late in the stream (dead space)
    score += norm_pr * norm_pr * 20.0 * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 15.0 * (0.3 + 0.7 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - (slack / cap)) * (1.0 - progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for many open bins relative to progress
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate handling: neutralize baseline for empty bin
    if bin_residual == bin_capacity {
        score -= 3.0;
    }

    // Smooth interaction with mean residual
    score += 0.05 * (pr - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and integer-division bands.
    let pr = post_residual;
    let band = pr / 10;                 // integer division band 0..10
    let residue = pr % 10;              // harmonic residue class
    score += residue as f64 * 0.6;      // prefer residuals aligning to decade boundaries
    score -= (band as f64).powi(2) * 1.5; // strongly favor small post-residual bands

    // Capacity-fraction classes: reward leaving residual near useful fractions of C.
    let frac = pr as f64 / cap;
    for (target, w) in [(0.0, 6.0), (0.1, 3.0), (0.2, 4.0), (0.3, 2.5), (0.5, 2.0)] {
        let d = (frac - target).abs();
        score -= w * (1.0 - d.min(1.0));
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next fits perfectly: reward, especially if residual class matches
            let slack = pr - next_item_size;
            score -= 8.0;
            score -= (slack % 10 == 0) as i32 as f64 * 4.0;
        } else {
            // next item would strand this residual: penalize by stranded fraction
            score += (next_item_size - pr) as f64 * 0.25;
        }
    } else {
        // last item: just minimize waste
        score -= 10.0;
    }

    // Last-chance bin: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // penalize opening a new bin, scaled by stream progress and open bins
        score += 20.0 + 0.3 * open_bins_count as f64;
        // but if the item perfectly fills a fresh bin's harmonic class, allow it
        if item_size % 10 == 0 {
            score -= 15.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    } else {
        // reward using existing bins relative to mean residual state
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
    }

    // Perfect fill bonus
    if pr == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    if post_residual == 0 {
        // Perfect fit is strongly rewarded.
        score -= 40.0;
    }

    // Penalize leaving residual that cannot fit the lookahead item while this bin could otherwise hold it later.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward a bin whose residual can accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it mildly unattractive unless open bins are very fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
    } else {
        // Prefer tighter existing fits: deviation from perfect fill.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += waste_ratio * 30.0;
        // Favor bins with below-mean residual (tighter bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the leftover exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: next item exactly fills this bin after current placement.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight two-step fit; penalize slack quadratically.
            score -= 40.0 - 0.6 * slack - 0.02 * slack * slack;
        } else {
            // Next item cannot use the leftover; leftover risks becoming dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(80.0);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score += 0.25 * post_residual as f64;
    }

    // Compare post_residual against mean residual across open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        // Creating larger-than-average residual: mild penalty for fragmentation.
        score += 0.15 * (pr - mean_residual);
    } else {
        // Compacting a below-average residual bin is good.
        score -= 0.10 * (mean_residual - pr);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline with slight pull toward using it only
    // when open bins leave large residuals.
    if bin_residual == bin_capacity {
        score += 12.0 - 0.1 * mean_residual;
        // Discourage new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress);
    }

    // Slight preference for tighter fits as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential preference for small post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny sliver is wasted
    } else if post_residual >= 10 {
        score -= 2.0; // usable leftover is good
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly in the post residual, reward; if it wastes, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 2.0; // next item won't fit here anyway
        }
    }

    // New-bin candidate logic: only attractive when current fit is poor or bin nearly full.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        let many_bins = open_bins_count as f64 > 2.0 + mean_residual / 10.0;
        if poor_fit || many_bins {
            score -= 9.0;
        } else {
            score += 14.0; // keep using open bins when fit is decent
        }
    }

    // Time horizon: early in stream, be conservative (favor filling existing bins);
    // late in stream, allow more aggressive tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * fit_ratio;

    // Global residual pressure: high mean residual means open bins are roomy; prefer them.
    if bin_residual < bin_capacity {
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;

    // Base: post residual, non-linearly warped by stream progress.
    let mut score = pr * (1.0 + 0.8 * t * (1.0 - t) * 4.0);

    // Quadratic coupling: penalize large residuals more as stream progresses.
    score += 0.006 * pr * pr * (0.5 + t);

    // Tight fit reward (small post residual) via smooth cubic term.
    let tight = 1.0 - pr / cap;
    score -= 12.0 * tight * tight * tight * (1.0 - t * 0.5);

    // Fill fraction coupling with item size.
    let fill = it / cap;
    score -= 8.0 * fill * (1.0 - pr / cap);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + t);
    }

    // New-bin candidate: penalize unless post residual is large enough to be useful.
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };
        // Favor new bin if item is small and future items could use the leftover space.
        score = 18.0 + 30.0 * fill - 20.0 * lookahead_bonus * (1.0 - fill) + 10.0 * t;
    }

    // Lookahead: reward leaving residual close to next item size (smooth kernel).
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (-20.0 * d * d);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation).
    score += 0.15 * mean_residual * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in "dead zones"
    // (0 < post_residual < 10) are nearly unusable -> penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Modulo-class bonus: residuals divisible by common item granularities
    // (10, 20, 25, 50) tend to pair with future items.
    let r = post_residual;
    if r % 10 == 0 && r > 0 {
        score -= 12.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 8.0;
    }
    if r % 20 == 0 && r > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 70.0;
        } else if next_item_size <= r && (r - next_item_size) < 10 {
            score -= 30.0;
        } else if next_item_size > r {
            // Next item cannot use this bin's leftover: leftover is dead weight
            score += (r as f64) * 0.35;
        }
        // Harmonic match: next item divides the leftover cleanly
        if next_item_size > 0 && r % next_item_size == 0 && r > 0 {
            score -= 18.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or open-bin residuals are all poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score += 45.0;
        // Large items justify new bins (avoid stranding big items in crowded bins)
        if item_size > 50 {
            score -= 30.0;
        }
        if item_size > 70 {
            score -= 20.0;
        }
        // If mean residual across open bins is too small to hold typical items,
        // opening fresh capacity is fine.
        if mean_residual < (item_size as f64) {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        score += 40.0 * progress;
    } else {
        // Prefer tighter existing bins: reward low post_residual.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
        // Many open bins: discourage spreading items across all of them.
        if open_bins_count > 4 {
            score += 2.0 * ((open_bins_count as f64).ln());
        }
    }

    // Global tie-break: slight preference for bins whose residual stays
    // in a "harmonic" reusable class (multiples of 10 up to 50).
    if r >= 10 && r <= 50 && r % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

