    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln() * 6.0;
    if bin_residual < bin_capacity {
        score -= pressure;
    } else {
        score += pressure;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item is large and this placement leaves a gap it cannot use.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (fill emptier-of-space bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight progression scaling of dead-space penalty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
