    }

    // Late in the stream, prefer closing bins out (smaller post residual weighted more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.05 * progress;

    // New-bin candidate: mildly discourage unless residuals are generally large.
    if bin_residual == bin_capacity {
        let avg_open_res = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if avg_open_res < item_size as f64 * 1.1 || next_item_size == 0 {
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead: if next item fits into post_residual, strongly reward chaining.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.25 * (next_item_size as f64);
        } else {
            // penalize wasting residual that next item nearly fits
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 0.6 * gap;
            }
        }
    } else {
        // last item: prefer fullest packing
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation (favor bins below mean residual).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
        score += 0.5 * (open_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, opening new bins is cheap; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, cheaper early, expensive late.
        score = 55.0 + 45.0 * progress - 10.0 * (item_size as f64 / 100.0);
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // room for a big follower
        }
    } else if progress > 0.7 {
        score += 10.0 * progress; // late stream: penalize leaving loose residuals
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (low post residual) to build dense bins.
    // Late stream: relax slightly, but still punish dead space super-linearly.
    let p = 1.0 + 2.0 * progress; // polynomial exponent drifts 1 -> 3 as stream advances
    let mut score = post.powf(p);

    // Interaction: x^2 * progress rewards using bins well when stream is mature.
    score -= 8.0 * x * x * progress;

    // Penalize bins whose residual is far below the mean (fragmented leftovers)
    // with a smooth cubic in normalized deviation.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 4.0 * dev * dev * dev;

    // Lookahead coupling: if next item fits exactly into post residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * gap;
        if next_item_size as u32 == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for proliferating open bins, smoothed by progress.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * frac * frac; // penalize wasted fraction quadratically

    // Harmonic class of post_residual: dead space is worst when it can't
    // hold a "typical" small item. Class by modulo bands.
    let pr = post_residual;
    if pr > 0 {
        let m = pr % 10;
        // residuals that are multiples of 10 are "harmonic" — more reusable
        score -= 4.0 * (1.0 - (m as f64 / 9.0)) * 0.5;
        // tiny unfillable residues (1..=5) are near-dead space
        if pr <= 5 {
            score += 12.0;
        } else if pr <= 10 {
            score += 4.0;
        }
    }

    // If lookahead item fits the post residual, big reward (chaining)
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0;
        // extra reward if post_residual is an exact harmonic multiple
        if pr % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // lookahead can't use this bin's residue: penalize proportionally
        score += 3.0 * (next_item_size - pr).min(20) as f64 / 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // penalize opening new bins normally
        score += 25.0;
        // but if existing residuals are all tiny/fragmented, relax penalty
        score -= 15.0 * (1.0 - pressure.min(1.0));
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big upcoming item: fresh bin is fine
        }
    }

    // Late in the stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is below the mean (fill fuller bins first)
    score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // classic dead space: nothing (10..80) can ever use it
        } else if post_residual < 25 {
            score += 25.0 * (1.0 - post_residual as f64 / 25.0); // hard-to-fill gap
        }
    } else {
        score -= 40.0; // perfect fit: fully consume the bin
    }

    // Reward tight packing relative to bin size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; new-bin
    // candidates should be penalized when many bins are already open.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * pressure; // opening a new bin is costly
    } else {
        score -= 1.5 * pressure; // mild reward for consolidating into open bins
    }

    // Prefer bins whose residual is close to the item (good fit geometry).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * fit_gap;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0; // this placement strands the next item
    }

    // Stream progression: early on, be slightly more willing to open bins for
    // diversity; late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // leaves other bins large; slightly favor bins near/below the mean.
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.5;
    }
    // Next item cannot follow into this bin: penalize proportionally.
    else if next_item_size > 0 && next_item_size <= bin_capacity {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward filling bins tighter than the current mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(50.0) * 0.4;
    } else {
        score += (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress;
    }

    // Discourage leaving dead space that nothing (min size 1..10) can use.
    if pr > 0.0 && pr < 10.0 {
        score -= 5.0; // tiny waste is fine, bin is nearly perfect
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post_residual amplifies wasted space.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect-fit bonus: zero waste is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Reward residual that can still host the next item proportionally to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Penalize leaving residual too small for the next item (dead space risk).
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or all open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / (bin_capacity as f64); // high = open bins are full-ish
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / (bin_capacity as f64);
        // Penalize new bins mildly; discount when bins are crowded or item is large.
        let new_bin_penalty = 55.0
            - 30.0 * crowding
            - 25.0 * big_item
            - 10.0 * progress;
        score += new_bin_penalty.max(0.0);
        // A fresh bin for a big item that leaves useful residual is fine.
        if big_item > 0.5 && post_residual >= 20 {
            score -= 10.0;
        }
    }

    // Mild preference to spread load early (keeps flexibility), tighten late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.05 * (post_residual as f64);

    // Slight penalty when many bins are open: encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    // Nudge toward bins whose residual is close to the item (relative fit).
    let fit_ratio = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual, with a non-linear (quadratic) coupling
    let mut score = post * (1.0 + 0.015 * post / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, tight fits matter more.
    let tightness = 1.0 - (post / cap).powi(2);
    score -= 8.0 * progress * tightness;

    // Penalize post_residual that would exactly fit the lookahead item poorly
    // (i.e., leaving a gap that next item barely misses, creating dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            // next item fits: mild reward proportional to remaining slack after that
            score -= 3.0 * (1.0 - (gap / cap).powi(2));
        } else {
            // next item doesn't fit: penalize dead space smoothly
            score += 4.0 * ((-gap) / cap).powi(2) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Slight penalty when many bins are open relative to progress (fragmentation).
    score += 0.5 * (open_bins_count as f64 / (1.0 + progress * 10.0));

    // Encourage balance with mean residual: prefer bins near the mean.
    let dev = (post - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate shaping: empty bin should win only when item is large
    // relative to typical residual or fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item / cap).powi(2);
        score += 10.0 - 6.0 * big_item - 8.0 * scarcity - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues near multiples of common item sizes
    // are more reusable. Reward post_residual that is a "harmonic" leftover.
    let pr = post_residual;
    let cap = bin_capacity;

    // Fraction of capacity remaining after placement
    let frac = pr as f64 / cap as f64;

    // Penalize tiny unusable leftovers (dead space) more than linearly.
    if pr < 10 {
        score += 40.0 * (10 - pr) as f64;
    }

    // Reward large reusable residuals mildly super-linearly.
    score -= 0.35 * frac * frac * cap as f64;

    // Harmonic classes: check if post_residual is divisible-friendly w.r.t. common sizes.
    // A residual that can host next_item_size exactly (or with small slack) is valuable.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            // Perfect fit for next item: strong reward.
            if slack == 0 {
                score -= 25.0;
            } else if slack < 10 {
                score -= 12.0;
            } else {
                // Harmonic divisibility: residual divisible by next_item_size
                if pr % next_item_size == 0 {
                    score -= 6.0;
                }
                // Reward proportional to how well next item fits
                score -= 3.0 * (next_item_size as f64 / cap as f64);
            }
        } else {
            // Next item cannot fit here; residual must be saved for later.
            // Penalize small residuals that become dead space.
            if pr < 25 {
                score += 15.0 * (25 - pr) as f64 / 25.0;
            }
        }
    } else {
        // Last item: prefer tightest fit, no future concerns.
        score -= 10.0;
    }

    // Integer-division thresholds on post_residual (harmonic bands of capacity).
    let band = pr / 25; // 0,1,2,3 harmonic quarters
    score -= 4.0 * band as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids wasting residual capacity).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != cap {
        score -= 18.0;
    }

    // New-bin candidate (empty bin): only attractive when current residual is poor
    // or next item needs more room than this bin would leave.
    if bin_residual == cap {
        let mut new_bin_score = 45.0; // base cost of opening a new bin
        if next_item_size > 0 && next_item_size > pr {
            // Next item can't fit after this placement: new bin gains value
            new_bin_score -= 20.0;
        }
        if pr < 15 {
            new_bin_score -= 25.0; // nearly dead residual, better to open new bin
        }
        // Early in stream, slightly cheaper to open bins (builds flexibility)
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= 5.0 * (1.0 - progress);
        // Many open bins: discourage proliferation
        new_bin_score += 1.5 * open_bins_count as f64;
        score = score.max(new_bin_score);
        return new_bin_score;
    }

    // Mild preference for bins below mean residual (balance load) to keep
    // mid-sized residuals available across bins.
    let mean_frac = mean_residual / cap as f64;
    if frac > mean_frac {
        score += 2.0 * (frac - mean_frac);
    } else {
        score -= 1.0 * (mean_frac - frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest possible
    // item (size 1) are fine, but residuals that fall into the "unusable gap"
    // band (below the typical small-item threshold) are wasted space.
    let dead_threshold = 10.0f64; // smallest historical item size
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Penalize unusable slivers heavily — proportional to how close to zero.
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Perfect fits are gold: reward zero post_residual strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave enough room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Remaining space can't host the next item: mild dead-space penalty.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // (penalize opening new ones); when few bins are open, be more tolerant.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins accumulate and stream progresses.
        score += 25.0 * pressure * (0.5 + progress);
    } else {
        // Reward using existing bins, scaled by how "tight" the fit is.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 6.0 * pressure * tightness;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins), reducing fragmentation across the bin set.
    score += (mean_residual - bin_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it attractive only when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mildly penalize so that any decent existing fit wins; but if the
        // item would leave a huge dead space everywhere, new bin competes.
        score += 15.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.1;
        }
        // Late in stream, prefer closing out open bins instead of spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        return score;
    }

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect two-step match: strongly reward.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits after this placement: reward proportional to snugness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.15;
        } else {
            // Next item won't fit here: penalize wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.2;
        }
    }

    // Prefer bins tighter than average (good fits), punish loose bins.
    let diff = mean_residual - post_residual as f64;
    score -= diff * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many options, prefer the most snug (post_residual already does this).
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Avoid leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to plausibly fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a large but unusable gap.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer the fullest possible packing.
        score -= 20.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with below-average residual (keep tight bins tight, use loose bins).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // New-bin candidate handling: penalize opening a new bin, more so later in the
    // stream and when other bins fit, but relax when many bins are open and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 20.0 + 25.0 * progress;
        if fitting_bins_count > 1 {
            new_bin_penalty += 30.0;
        }
        // If open bins are highly fragmented (high mean residual spread), new bin is ok.
        if mean_residual > 40.0 && open_bins_count > 3 {
            new_bin_penalty -= 25.0;
        }
        // Big items early: opening fresh bins for large items can help.
        if item_size >= 60 && progress < 0.3 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for reusing bins when many are open (consolidation pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear tightness reward: strongly favor small post residuals.
    let tight = (1.0 - pr / cap).powi(2);
    score -= 14.0 * tight * (1.0 + progress);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is increasingly penalized.
    let prn = pr / cap;
    score += 10.0 * prn * prn * (0.5 + progress);

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64 / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly discourage opening a new bin when this is
    // the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate: penalize unless it is genuinely better than
    // cramming (poor fit into a nearly full bin).
    if bin_residual == bin_capacity {
        let cram_penalty = if fitting_bins_count == 0 { 0.0 } else {
            (item_size as f64 / cap).powi(2) * 20.0
        };
        score += 6.0 + cram_penalty - 10.0 * (1.0 - progress);
        // If no open bin fits, new bin is the only choice.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual
    // (keep big gaps for big items).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Harmonic class of post_residual in quarters of capacity:
    // class 0 = tight fit (heavily rewarded), higher classes = progressively penalized dead space
    let class = (post_residual * 4) / bin_capacity.max(1);
    score += match class {
        0 => -3.0,
        1 => 0.0,
        2 => 1.5,
        _ => 2.5,
    };

    // Lookahead (k=2): reward bins that can also swallow the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    }
    // If the next item can't fit this bin even before placement, the residual is final dead space
    if next_item_size > 0 && next_item_size > bin_residual {
        score += 2.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New empty bin candidate: penalize so existing bins are preferred,
    // penalty grows with the number of viable alternatives
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 2.0 * fitting_bins_count as f64;
        // Opening a fresh bin is more attractive for large items late in the stream
        if item_size >= bin_capacity / 2 {
            score -= 2.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score += 3.0;
        }
    }

    // Mild coupling with the fleet's mean residual: prefer bins whose leftover
    // lands near the fleet average (keeps residual classes coherent)
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": residuals too small to be useful for typical items.
    // A residual below the minimum item size (1) is impossible, but residuals
    // below a practical threshold waste capacity. Penalize small-but-nonzero gaps.
    if post_residual > 0 {
        // Waste ratio: fraction of the bin lost to residual.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        // Dead-space penalty grows super-linearly for small unusable gaps.
        if post_residual < 10 {
            score += 25.0 * (10.0 - post_residual as f64);
        } else {
            score += 5.0 * waste_ratio * waste_ratio * (bin_capacity as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: proximity of item to residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    // Open-bins pressure: encourage reusing existing bins when many are open,
    // penalize opening new bins under pressure.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Allow new bin early in the stream or when open bins are nearly full.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If mean residual across open bins is small, opening new bin is fine.
        score -= 0.3 * mean_residual.max(0.0);
        if progress > 0.5 && mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins, especially when many are open.
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 20.0;
        } else if next_fit_gap < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual after placement can't hold next item: slight penalty if tiny.
        if post_residual < 10 {
            score += 8.0;
        }
    }

    // Mild preference for filling bins more completely overall.
    score -= 0.05 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), with a slight quadratic penalty
    // on leftover space to punish wasteful placements.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // --- 2-step lookahead: reward bins whose leftover can host the next item ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // Exact or near-exact chaining: strongly reward.
            let gap = post_residual as f64 - next;
            if gap == 0.0 {
                score -= 30.0;
            } else if gap <= 10.0 {
                score -= 20.0 - gap;
            } else {
                score -= 10.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item will not fit here: penalize proportionally to the shortfall,
            // unless post_residual itself is tiny (dead space is already accounted).
            let shortfall = next - post_residual as f64;
            score += 3.0 * shortfall / bin_capacity as f64 * 10.0;
        }
    }

    // --- Mean residual coupling: prefer bins below/above mean appropriately ---
    // Tightening a loose bin (residual above mean) is good; draining an already
    // tight bin is discouraged.
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= (res - mean_residual) * 0.3;
    } else {
        score += (mean_residual - res) * 0.3;
    }

    // --- Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin. ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mild preference for diversity of options.
        score += 1.0 * (fitting_bins_count as f64 - 1.0);
    }

    // --- New-bin candidate handling: an empty bin gets a mild penalty so it is
    // only chosen when open bins would create large dead space or break lookahead. ---
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
        // If next item is large, a fresh bin offers flexibility.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // --- Stream progression: early on, slightly favor consolidating into fewer bins;
    // late, allow new bins more readily. ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 10.0;
        // Penalize dead space that no plausible item can use later.
        if post_residual < 10 {
            score -= 8.0;
        } else if post_residual < 30 {
            score += (post_residual as f64) * 0.15;
        }
    }

    // Lookahead: bonus if the next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / bin_capacity as f64) * 6.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Post-residual too small for lookahead: dead space penalty.
        score += (post_residual as f64) * 0.25;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: baseline penalty so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening new bins is more attractive early when few bins are open.
        score -= (open_bins_count as f64).sqrt() * 2.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins whose residual is near the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    // Prefer fuller bins overall.
    score -= (1.0 - bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_item * progress;
    score += 40.0 * coupling;

    // Smooth penalty for large dead space weighted by progress
    score += 15.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space close to next item size (smooth kernel)
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        score -= 20.0 * (-40.0 * d * d).exp();
    }

    // Slight preference for tighter bins relative to mean residual
    score += 5.0 * ((pr - mean_residual) / cap);

    // Mild penalty for opening many bins early
    score += 0.5 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are prized because tiny leftovers are likely
    // fillable by small future items, whereas mid-range leftovers are dead space.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Dead-space zones: leftover in (0.25, 0.5) or (0.6, 0.9) of capacity is
    // hard to fill with items of size 1..100 typical classes.
    if frac > 0.25 && frac < 0.5 {
        score += 18.0 * (0.5 - frac);
    }
    if frac > 0.6 && frac < 0.9 {
        score += 12.0;
    }

    // Exact / near-exact fills are excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Harmonic residue class via modulo: leftover divisible by common item
    // sizes (multiples of 5 / 10) pairs well with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot ever fit (too big for residual but
    // stream continues), mildly penalize leaving a stranded gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // partial credit scaled by how much would remain after next item
            let r2 = post_residual - next_item_size;
            score -= 10.0 * (1.0 - (r2 as f64) / cap);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize so we prefer reusing open bins
    // with decent fits, but allow opening when all fits are terrible.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // if current item is large relative to capacity, new bin is fine
        score -= 0.2 * item_size as f64;
        // late in the stream, opening bins is less costly in expectation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // many open bins with high mean residual: better to pack into them
        score += 0.15 * mean_residual;
    }

    // Mild preference to fill fuller bins first (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - post_residual as f64).signum() * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=9) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium gaps (10..=19) only useful for tiny items; mild penalty.
    else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: penalize opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // But if this bin is the last chance, opening new is acceptable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid proliferation.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with residual close to item (best-fit style sharpening).
    let waste = (bin_residual - item_size) as f64;
    score += 0.3 * waste * waste / bin_capacity as f64;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item leaves a near-dead gap, penalize slightly.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 && post_residual >= next_item_size {
        score += 5.0;
    }

    // Late in stream: consolidate, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 10.0 * progress;
    }

    // Mean-residual coupling: if mean residual is low, cherish existing bins.
    if !is_new_bin && mean_residual < 20.0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: if the NEXT item fits exactly into post_residual,
    // this is a perfect chain placement — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 300.0;
        }
        // Penalize if placing here leaves post_residual that next item
        // cannot use and next item would fit better elsewhere.
        if next_item_size > post_residual && post_residual > 0 {
            score += 40.0;
        }
    }

    // Compare against mean residual: bins tighter than average are more
    // valuable to fill now (reduce fragmentation).
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.5;
    } else {
        score += (resid_f - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins already exist with
    // reasonable space, unless the item is large and fits poorly everywhere.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 150.0;
        if open_bins_count > 0 && resid_f >= 0.0 {
            // new bin acceptable only for large items
            if item_size >= 60 {
                score -= 100.0;
            }
            if waste > 40.0 {
                score += 20.0;
            }
        }
    }

    // Slight late-stream tightening: pack tighter as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += resid_f * 0.1 * progress;

    // Mild pressure to prefer fuller bins when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more than linearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Reward leaving exactly enough room for the next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Reward leaving room for the next item if it's large.
        if post_residual >= next_item_size {
            score -= (next_item_size as f64 / 100.0) * 10.0;
        }
    } else {
        // Last item: strongly prefer zero waste.
        score -= 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New empty bin candidate: penalize opening new bins unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // Open new bin when mean residual is low (bins are full) or few bins fit.
        score += 60.0 - 45.0 * (1.0 - crowding) - 20.0 * progress;
        if fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Mildly prefer bins with residual close to item size (best-fit flavor with coupling).
    let diff = bin_residual as f64 - item_size as f64;
    score += (diff / bin_capacity as f64) * 8.0;

    // Global state: with many open bins, consolidate into emptier bins.
    if open_bins_count > 4 {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), mildly non-linear
    let mut score = pr * (1.0 + 0.02 * (pr / cap));

    // Non-linear polynomial coupling with stream progress:
    // early in the stream tolerate waste; later, penalize waste quadratically.
    let waste_penalty = (pr / cap).powi(3) * (1.0 + 3.0 * progress);
    score += waste_penalty * cap * 0.5;

    // Reward bins whose residual after placement still accommodates the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 4.0 + 6.0 * (1.0 - nxt / cap) * (1.0 - progress);
        } else {
            // small residual that can't host next item: penalize proportionally
            score += 2.0 * (nxt / cap) * (pr / cap).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 10.0 * progress;
    }

    // Many open bins: encourage consolidation into existing bins
    let openness = open_bins_count as f64;
    score -= 0.3 * (openness.ln() + 1.0) * (1.0 - pr / cap);

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins)
    score += 0.5 * (pr - mean_residual) / cap;

    // New-bin candidate: penalize opening a fresh bin unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 6.0 + 6.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: waste buckets on capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Penalize dead space in awkward "harmonic" classes: tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space below minimum item size
    }

    // Reward residual classes that future items (1..100 unknown) can reuse:
    // prefer residuals near common capacity fractions (multiples of 25, 50).
    for k in 1..4u32 {
        let target = (bin_capacity / 4) * k;
        let d = (post_residual as i64 - target as i64).abs() as f64;
        score -= 12.0 / (1.0 + d);
    }

    // Modulo-10 class coupling of post_residual and next item size.
    let pr10 = post_residual % 10;
    let nx10 = next_item_size % 10;
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: big reward, stronger when classes align
            score -= 20.0 + (if pr10 == nx10 { 8.0 } else { 0.0 });
        } else {
            // lookahead won't fit: penalize, scaled by how badly
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Tight fit bonus: harmonic closeness to exact fill.
    score -= 30.0 / (1.0 + (post_f / cap_f * 10.0).abs());

    // Discard near-perfect residual waste classes (post in (0,5]) extra penalty
    if post_residual > 0 && post_residual <= 5 {
        score += 15.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // cost of opening a new bin, discounted late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 40.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 10.0; // even fresh bin can't host lookahead anyway
        }
    }

    // Slight tie-break toward bins with residual closest to mean (balance).
    score += (post_f - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residual in the "unusable gap" band.
    // Gaps of 1..=9 are dead space (min item size is small, but tiny gaps are rarely useful);
    // gaps just below next_item_size are dead space relative to the lookahead item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0 * (10 - post_residual) as f64; // unusable tiny gap
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.8; // can't host next item
        } else {
            // Usable gap: mild reward scaled by how well it hosts the next item
            if next_item_size > 0 && post_residual >= next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                score -= 6.0 * (1.0 - slack / bin_capacity as f64);
            }
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residual is ample elsewhere
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins have poor fits / high fragmentation
        let fragmentation = (mean_residual - item_size as f64).abs();
        let pressure = open_bins_count as f64 * (1.0 + progress);
        score += pressure * 2.0;
        // Reward opening a new bin when mean residual is fragmented (far from item size)
        score -= fragmentation.min(40.0) * 1.5;
        // Penalize opening bins early in the stream
        score += (1.0 - progress) * 15.0;
    } else {
        // Existing bin: slight preference for fuller bins (lower residual)
        score += (bin_residual as f64 / bin_capacity as f64) * 4.0;
        // Mild reward when bin residual is close to item size (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score -= 5.0 * (1.0 - tightness / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference for tight fits
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain
        }
        // Penalize dead space unusable by next item
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: just prefer minimal waste
        score += 5.0;
    }

    // Compare post_residual against mean residual: keep balanced bins
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - pr) * 0.05;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when a reasonable fit exists
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        // But allow new bin if item is large and fits poorly everywhere (implicit via post_residual)
    }

    // Slight late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small for typical items (waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if next item fits almost perfectly afterward.
            let second_post = post_residual - next_item_size;
            if second_post < 5 {
                score -= 6.0;
            }
        } else {
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than new ones.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bin pressure is high or stream is late.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * pressure + 10.0 * progress;
    } else {
        score -= 3.0 * pressure.min(2.0);
    }

    // Prefer bins with residual below the mean (consolidating smaller leftovers).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Early stream: be slightly greedy toward best-fit; late stream: avoid fragmenting.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let norm_post = post / cap;

    // Base: quadratic penalty on leftover space (dead space is doubly bad late in stream)
    let mut score = post * (1.0 + 1.5 * norm_post);

    // Stream-progress coupling: leftover space hurts more as the stream matures
    score += 20.0 * norm_post * norm_post * (0.5 + progress);

    // Reward near-perfect fits smoothly (post_residual close to 0)
    let fit_quality = (-norm_post).exp();
    score -= 30.0 * fit_quality;

    // Lookahead coupling: reward residuals that could host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = ((post - nxt) / cap).exp();
            score -= 12.0 * slack;
        } else {
            let gap = ((nxt - post) / cap).exp();
            score += 8.0 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for scattering across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - post).abs() / cap;

    // New-bin candidate: neutral-ish base so it loses only when a real fit is good
    if bin_residual == bin_capacity {
        score = cap + 10.0 * progress + 0.5 * (item_size as f64);
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if (cap - item_size as f64) >= nxt {
                score -= 10.0;
            }
        }
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post residual (tight fit)
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead space"
    // (small, hard to fill later) get penalized; medium residues are fine.
    let dead_zone = 10u32.min(post_residual);
    score += (dead_zone as f64) * 2.5; // small leftovers are worst

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Classify post_residual by harmonic class (mod 10 bands)
    let class = post_residual / 10;
    match class {
        0 => score += 12.0,          // 0-9: nearly dead
        1 => score += 2.0,           // 10-19: marginal
        2 | 3 => score -= 3.0,       // 20-39: useful
        4 | 5 => score -= 6.0,       // 40-59: very useful
        6 | 7 => score -= 2.0,       // 60-79: okay
        _ => score += 4.0,           // 80+: mostly empty bin, wasteful use
    }

    // If this bin is the last chance to fit, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0;
            } else if slack <= 15 {
                score -= 10.0;
            } else if slack <= 40 {
                score -= 4.0;
            }
        } else {
            // next item can't use this residual -> residual likely dead
            score += (post_residual.min(next_item_size) as f64) * 0.3;
        }
    }

    // Prefer filling bins when many bins are open (reduce bin proliferation)
    score -= (open_bins_count as f64) * 0.5;

    // Slight preference toward bins below mean residual (balance / empty bins first)
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // New-bin candidate: keep it attractive only when item is large relative
    // to residual capacity of open bins; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 18.0; // default penalty for opening a new bin
        if item_size > 60 {
            score -= 14.0; // big items justify fresh bins
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // pair of big items coming
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let item = item_size as f64;
    let capacity = bin_capacity as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fits = fitting_bins_count as f64;

    let progress = if total_items > 0 {
        ((step_index as f64) / (total_items as f64)).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let base_dead_floor = (capacity * 0.10).clamp(4.0, 12.0);
    let dead_floor = if next > 0.0 {
        base_dead_floor.min(next.max(1.0))
    } else {
        1.0
    };

    if residual >= capacity - 0.5 {
        let mut new_bin_score = post;

        if fits < 0.5 {
            new_bin_score -= 1000.0;
        } else {
            new_bin_score += 40.0 + 1.30 * open + 14.0 * progress;
            new_bin_score += if fits < 1.5 { 18.0 } else { 6.0 };
        }

        if post > 0.0 && post < dead_floor {
            new_bin_score += 26.0 + 2.2 * (dead_floor - post);
        }

        if next > 0.0 {
            if post + 0.5 >= next {
                new_bin_score -= 4.0 + 0.04 * next.min(80.0);
            } else {
                new_bin_score += 5.0 + 0.28 * (next - post).min(capacity);
            }
        }

        return new_bin_score;
    }

    if post <= 0.5 {
        let mut exact_fit_score = -70.0 - 0.10 * residual - 8.0 * progress - 0.02 * item;
        if fits <= 1.0 {
            exact_fit_score -= 10.0;
        }
        return exact_fit_score;
    }

    let mut score = post;

    let dead_deficit = (dead_floor - post).max(0.0);
    if dead_deficit > 0.0 {
        let severity = dead_deficit / dead_floor;
        score += 15.0 + 65.0 * severity * severity + 1.1 * dead_deficit;
    }

    if next > 0.0 {
        if post + 0.5 < next {
            score += 6.0 + 0.42 * (next - post).min(capacity);
            if dead_deficit > 0.0 {
                score += 8.0;
            }
        } else {
            score -= 0.07 * next.min(60.0);
        }
    }

    score += 0.07 * (residual - mean_residual).clamp(-25.0, 25.0);

    if fits <= 1.0 {
        score -= 30.0 + 0.70 * open + 10.0 * progress + 0.05 * item;
    } else {
        score -= 2.0 / fits + 0.15 * open + 0.01 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0);
        } else {
            // next item cannot follow here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0) * 0.5;
        }
    }

    // Compare against mean residual: a tight fit relative to average is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Penalize bins with residuals far from mean (encourages uniform packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // late in the stream, opening fresh bins is slightly more acceptable
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: strongly favor placements that leave little waste,
    // especially small dead space that could become unusable.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size is worthless
        score -= 6.0;
    } else if post_residual < 20 {
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 0.5 {
            score -= 30.0;
        } else if post_residual as f64 >= nr {
            score -= 4.0;
        } else {
            // Next item won't fit here; slight penalty for wasting residual
            score += 3.0 * (nr - post_residual as f64) / bin_capacity as f64;
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin when
    // decent alternatives exist, but allow it when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual - post_residual as f64).abs()
        } else {
            0.0
        };
        // Base cost of opening a new bin
        score += 20.0;
        // If few bins fit the item, opening fresh is more attractive
        if fitting_bins_count <= 1 {
            score -= 22.0;
        }
        // Late in the stream, prefer consolidating into open bins
        score += 15.0 * progress;
        // If mean residual of open bins is large, they can absorb the item
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
        // Fragmentation coupling: many scattered residuals justify a new bin
        score -= 5.0 * (fragmentation / bin_capacity as f64);
    }

    // Prefer filling bins with larger residuals early (keep small residuals
    // flexible), but flip preference late in the stream to close bins out.
    let residual_weight = 0.4 - 0.6 * progress;
    score += residual_weight * (bin_residual as f64 - mean_residual);

    // Mild penalty for proliferating open bins mid-stream
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear coupling of post_residual with stream progress
    score += norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0 * (0.5 + progress);

    // Penalize small-but-nonzero dead space (non-linearly)
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.2;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward residual matching next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += diff * 0.5 * (1.0 - progress);
        if next_item_size as f64 <= pr {
            score -= 5.0;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += open_bins_count as f64 * 0.3;

    // Mean residual coupling
    score += (mean_residual - pr) * 0.1;

    // New-bin candidate: mildly penalize opening a new bin unless residuals are bad
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction buckets (C=100).
    let item_class = item_size / 20; // 0..4 (tiny, small, medium, large, huge)
    let post_class = post_residual / 20;

    // Reward tight fits: post_residual near zero, or in "harmonically useful"
    // residual classes that other items can still fill (e.g. 0, 10, 20, 25, 50).
    match post_residual {
        0 => score -= 30.0,
        10 | 20 | 25 | 50 => score -= 12.0,
        _ => {}
    }
    if post_residual <= 5 {
        score -= 8.0;
    }

    // Penalize dead space: post_residual that is too small for the smallest
    // plausible item (<= 9) is wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25) stay fillable; odd remnants are penalized.
    if post_residual % 10 != 0 && post_residual % 25 != 0 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits: the closer the chain fit, the better.
            let chain_gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_gap as f64 / 20.0).max(0.0);
        } else {
            // Next item won't fit here after placement; slight penalty scaled
            // by how much it overflows.
            let overflow = next_item_size - post_residual;
            score += (overflow as f64).min(30.0) * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize moderately so we only open a new
    // bin when no open bin offers a decent fit. The penalty shrinks when many
    // bins are open and mean residual is high (fragmentation pressure).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0;
        let frag = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        new_bin_penalty -= frag * 10.0;
        if open_bins_count > 8 {
            new_bin_penalty -= 4.0;
        }
        // Big items justify fresh bins more than tiny ones.
        if item_class >= 3 {
            new_bin_penalty -= 6.0;
        }
        score += new_bin_penalty.max(2.0);
    }

    // Mild preference for fuller bins overall (best-fit bias) via
    // bin_residual fraction, modulated by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_frac * (4.0 + 6.0 * progress);

    // Post-class harmonic alignment: keep post_residual classes aligned with
    // common item classes to encourage future pairing.
    if post_class == item_class && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 30 {
        // 10..30 gap: only usable by small items; partial penalty.
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but encourage consolidating when few bins are open.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
        // New bin is attractive only if the item would leave a large dead
        // space in any existing bin (poor fit).
        if post_residual == 0 || fit_ratio > 0.7 {
            score -= 10.0;
        }
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 5 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; mild penalty for stranding space.
        score += 4.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (filling below-average residual bins first keeps larger
    // residual bins flexible).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item fits exactly into post_residual (perfect 2-step match)
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }

    // Reward when next item fits, scaled by tightness of the current fit
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 20.0 + 15.0 * tightness;
    }

    // Penalize dead space: post_residual too small to hold the next item
    if next_item_size > 0 && next_item_size > post_residual {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.3 * waste;
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins)
    score += 0.2 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // new-bin candidate: only attractive if it enables a perfect next-item match
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 5.0;
        } else {
            score += 25.0;
        }
    }

    // Early-stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residuals that are too small to fit anything useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // Penalize bins that would leave a residual just below the next item size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing),
    // penalize outliers that hoard space.
    score += 0.25 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: early in the stream, be more willing to open bins (new-bin cheap);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New-bin candidate: baseline cost of opening a fresh bin; becomes less attractive
    // as the stream progresses or when many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64 + 20.0 * progress;
        // Opening a new bin is attractive if the item is large and no bin fits well.
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Slight preference for emptier bins when few bins are open (flexibility reserve).
    score -= 0.05 * (bin_residual as f64) / (open_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space quadratically (dead space grows super-linearly bad).
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Tight fit reward: smooth polynomial coupling between fill ratio and progress.
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill * (0.5 + progress);

    // Perfect fit (post_residual == 0) heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining),
    // penalize if post residual is a "trap" — too small for anything useful.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap) * (nx / cap);
        } else {
            // dead space that next item cannot use: penalize more as stream progresses
            score += 4.0 * (1.0 - pr / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate handling: make an empty bin attractive only when it
    // enables a good long-term packing (large item, early stream, or many bins).
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        // Prefer opening a new bin for large items or when residuals elsewhere are fragmented.
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap - 20.0 * size_ratio * (1.0 - progress) - 8.0 * fragmentation * (1.0 - size_ratio);
        // Late in the stream, discourage opening new bins unless nothing else fits well.
        score += 30.0 * progress * (1.0 - size_ratio);
    }

    // Mild coupling with mean residual: prefer bins deviating below the mean
    // (consolidate waste into fewer bins).
    let dev = (mean_residual - pr) / cap;
    score -= 3.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common small sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut usable = 0.0;
        if pr % 10 == 0 { usable += 6.0; }
        if pr % 20 == 0 { usable += 4.0; }
        if pr % 25 == 0 { usable += 3.0; }
        if pr % 5 == 0 { usable += 2.0; }
        if pr >= 10 && pr <= 30 { usable += 3.0; } // small but re-usable chunk
        score -= usable;

        // Penalize dead space: residuals that can't fit any typical item (1..100
        // unknown distribution -> anything below ~10 is risky unless stream is long)
        if pr < 10 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strongly reward
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += 2.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make it moderately attractive when open bins are
    // fragmented, unattractive when a decent fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalty decays as stream progresses (less future to amortize a bin)
        score += 12.0 * (1.0 - 0.5 * progress);
        if open_bins_count > 0 && post_residual <= 100 - item_size {
            // residual of a fresh bin after placement = capacity - item
            if post_residual >= 50 { score -= 4.0; }
        }
        if mean_residual > 40.0 && fitting_bins_count > 2 {
            score += 6.0; // open bins are roomy; don't open another
        }
    }

    // Tie-break with mean residual: prefer bins tighter than average
    let avg = mean_residual;
    if (bin_residual as f64) < avg {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // A residual gap is "dead" if it's smaller than the smallest plausible item (1..100 range).
        // Penalize gaps < 10 extremely hard, and gaps < item_size/2 moderately.
        if post_residual < 10 {
            score += 500.0;
        } else if post_residual < item_size {
            // gap cannot fit the same-size item again; soft penalty scaled by gap tininess
            score += (10.0 - (post_residual as f64 / 10.0)) * 20.0;
        }
        // Nonlinear coupling: penalize gaps that cannot fit the lookahead item
        if next_item_size > 0 && post_residual < next_item_size {
            score += 30.0;
        }
    } else {
        // Perfect fill is strongly rewarded
        score -= 200.0;
    }

    // Reward tight fits: fraction of bin used by this placement
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 60.0;

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when other bins fit
    if bin_residual == bin_capacity {
        score += 250.0 + 40.0 * open_bins_count as f64;
        // If the next item is large and current item is small, opening a fresh bin is less bad
        if next_item_size > 50 && item_size < 30 {
            score -= 100.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier-but-usable space)
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host
    // the next item (chained packing), penalize near-misses that strand space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 30.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space: this bin cannot host the next item either
            score += 12.0;
        }
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize wasting a large fresh bin on a small item when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // opening a new bin is fine if item + next item pair well here
            score -= 10.0;
        }
    }

    // Early in the stream, be more willing to consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.10 + 0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Reward high fill ratio non-linearly (favor tight fits)
    score -= 30.0 * fill * fill * fill;

    // Penalize small dead space that is hard to reuse: smooth interaction
    let dead = pr / cap;
    if dead > 0.0 {
        score += 25.0 * dead * dead * (1.0 - fill);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward leaving space that can still fit the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 12.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 8.0 * (ni - pr) / cap;
        }
    }

    // Mild penalty for opening new bins late in the stream when many bins exist
    score += 0.15 * open_bins_count as f64 * progress;

    // Slight preference for bins with residuals near the mean (balanced packing)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but avoid tiny unusable slivers.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill is always best
    } else if post_residual < 10 {
        score += 40.0; // dead space: too small for any item
    }

    // Harmonic class of the leftover: modulo-10 classes on post_residual.
    // Leftovers that are multiples of 10 are "harmonic" (likely reusable by future items).
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 12.0;
    } else {
        score += 6.0;
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 10; // 0..=9 coarse class
    score += match class {
        0 => 45.0,           // 1..9: unusable sliver
        1 => 8.0,            // 10..19: fits only tiny items
        2 => -2.0,           // 20..29: decent
        3 => -6.0,           // 30..39: good
        4 => -4.0,           // 40..49: okay
        5 => 2.0,            // 50..59: half-empty bin, mild penalty
        6 => 6.0,
        7 => 10.0,
        8 => 14.0,
        _ => 0.0,            // near-empty bin (only new-bin candidate reaches here)
    };

    // Lookahead coupling: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // Harmonic lookahead: gap being a multiple of 10 means next-next fits too.
            if gap % 10 == 0 { score -= 25.0; } else { score += gap as f64 * 0.4; }
        } else {
            // Next item won't fit here; leftover becomes a waiting buffer.
            // Penalize proportionally to how much of the residual is wasted relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: just minimize waste.
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is a dead sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        if post_residual < 10 {
            score -= 20.0; // even a sliver fill is fine when it's the last chance
        }
    }

    // New-bin candidate (empty bin): make it moderately attractive only when
    // the item is large relative to capacity or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / bin_capacity as f64);
        score = 30.0 - frac * 55.0 + pressure * 4.0;
        // Discourage new bin if a harmonic leftover elsewhere would be wasted badly.
        if mean_residual > 40.0 && frac < 0.5 {
            score += 25.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0; // fragmentation ahead; fresh bin helps
        }
    }

    // Stream progression: early on, be tolerant of loose fits to build flexible bins;
    // later, tighten up and chase near-perfect fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 + progress * (100.0 - post_residual.min(100)) as f64 * 0.25;

    // Mean-residual coupling: when average leftover is large, penalize adding more waste.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (sizes >= 1)
    // are still wasted; residuals in (0, 10] are near-unusable, penalize heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits generally: tighter fit relative to capacity lowers score.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Pressure from open bins: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // Many alternatives: mild penalty so best-fit competition decides.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space relative to next item
            score += 3.0;
        }
    }

    // Mean residual coupling: placing into a bin far below mean residual wastes spread.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate baseline: keep it moderately attractive only when
    // open bins are crowded or the fit here would leave large dead space.
    if bin_residual == bin_capacity {
        score = 55.0 + 2.0 * open_bins_count as f64 - 0.3 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly -> heavy reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves a third-level residual: partial reward
            let chain_residual = post_residual - next_item_size;
            score -= 200.0 - chain_residual as f64;
        } else {
            // next item does NOT fit here: penalize wasted residual relative to next item
            let waste = next_item_size - post_residual;
            score += waste as f64 * 1.5;
        }
    }

    // Compare post_residual against mean residual: leaving much more residual
    // than average suggests creating a poorly-utilized bin.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize new-bin candidate unless residual of open bins is very tight
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / bin_capacity as f64).abs();
        // open a new bin only when existing residuals are large (poor fits likely)
        score += 400.0 * (1.0 - tightness);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // pair potential in fresh bin
            score -= 100.0;
        }
    }

    // Early in stream, be slightly more willing to open bins (future flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 100.0 * (1.0 - progress);
    }

    // Small tie-breaker favoring bins with tighter residual
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively for large items.
    let tight_fit_bonus = (post_residual as f64 / bin_capacity as f64).powf(1.8) * 20.0;
    score += tight_fit_bonus;

    // Penalize dead space: post residual that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins (favor fresh bins slightly);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it, less so early on.
        let new_bin_penalty = 8.0 + 14.0 * progress;
        // But if no open bin fits well, opening new bin is attractive: compare with mean residual.
        if mean_residual < item_size as f64 {
            score -= 5.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: reward bins whose residual is close to mean (balanced usage) early,
        // but prefer fuller bins (residual below mean) later.
        let dev = bin_residual as f64 - mean_residual;
        score += if progress < 0.5 { dev * 0.05 } else { -dev * 0.08 };
    }

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8 * (1.0 - progress);

    // Small reward for placing large items into bins with just enough space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 && fill_ratio <= 1.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Stream-progress coupling: tighten residual tolerance as stream progresses.
    let tightness = 0.5 + 0.5 * progress;
    score *= (1.0 + tightness * norm_pr * (1.0 - norm_pr) * 2.0);

    // Penalize large dead space relative to mean residual of open bins.
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 10.0 * (1.0 - (nxt / cap));
        } else {
            score += 8.0 * (nxt / cap);
        }
    }

    // Mild pressure against proliferating open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by residue classes.
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let prf = pr as f64;

    // Dead-space penalty grows sharply for residuals that cannot fit the smallest
    // plausible future items (harmonic classes: 0 = perfect, 1 = usable, 2 = dead).
    let class: u32 = if pr == 0 { 0 } else if pr >= 10 && pr <= 100 { 1 } else { 2 };
    match class {
        0 => { score -= 25.0; }
        1 => {
            // Usable residual: reward proportional to fraction of capacity, but
            // penalize awkward residues (prime-ish / odd classes) that pair poorly.
            let frac = prf / cap;
            score -= 12.0 * frac;
            if pr % 10 == 0 { score -= 6.0; }          // round classes pair well
            if pr % 2 == 1 { score += 1.5; }           // odd leftovers less flexible
            if pr % 5 == 0 { score -= 2.0; }
        }
        _ => {
            // Dead space: strong penalty, worse the smaller the residual.
            score += (10.0 - prf) * 2.0 + 15.0;
        }
    }

    // Integer-division thresholds on post_residual vs next item lookahead.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Bin could still host the next item: reward harmonic pairing.
            let pair = pr / next_item_size.max(1); // integer division threshold
            score -= 4.0 + 2.0 * (pair.min(3) as f64);
            if pr == next_item_size { score -= 8.0; }  // exact pairing is ideal
        } else {
            score += 3.0; // next item won't fit here
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        score += 1.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate: opening a bin is expensive unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < 25.0;
        let penalty = if crowded { 8.0 } else { 18.0 };
        score += penalty - 4.0 * progress;
        // Don't open new bins when a decent fit exists elsewhere.
        if class == 1 && pr <= 40 { score += 6.0; }
    }

    // Mild preference for bins with residual close to the item (tight fit),
    // using capacity-fraction coupling.
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 3.0 * tight.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=9)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is the ideal outcome: strong reward.
        score -= 60.0;
    }

    // Tight fit reward: the smaller the post_residual relative to capacity, the better,
    // but only when it stays usable (>= 10) or zero.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin open
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chaining perfect placements).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward proportional to how well it chains.
        score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize leaving a gap the lookahead can't use.
        score += 10.0 * (post_residual as f64 / 10.0);
    }

    // Open-bin pressure: discourage opening new bins when many are already open,
    // but encourage consolidation when few bins exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early (few open bins is fine, but prefer using them),
        // penalize more as the stream progresses and open bin count grows.
        score += 12.0 + 20.0 * progress + 0.8 * open_bins_count as f64;
        // Allow a new bin if all existing fits are bad (large dead space elsewhere is
        // handled by the penalties above making them unattractive).
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Using an existing bin reduces pressure slightly with more open bins.
        score -= 0.3 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins),
    // pushing toward consolidating loose space.
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)) - 60.0;
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 150.0;
        }
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare against mean residual: prefer tightening bins above the mean
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // current item is large relative to capacity or few bins fit
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 30.0 * (1.0 - pressure) - 40.0 * scarcity;
        // late in stream, discourage hoarding empty bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
    }

    // Slight preference for tighter bins generally
    score += 0.3 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Lookahead: reward bins where the next item also fits the post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }
    // Penalize leaving a gap that exactly fails to fit the next item (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins below mean residual (consolidate waste)
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Late in the stream, prefer tighter packing (reduce bin spread)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.05;

    // New-bin candidate: penalize opening a new bin unless item is huge
    if bin_residual == bin_capacity {
        let big_item_bonus = if item_size > bin_capacity / 2 { 5.0 } else { 0.0 };
        score += 60.0 - big_item_bonus + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, squeeze harder into existing bins
    let squeeze = 1.0 + 1.2 * progress * progress * (1.0 - progress * 0.3);
    score *= squeeze;

    // Reward filling a bin completely (near-zero residual) with a smooth bonus
    let fill_bonus = -8.0 * (1.0 - norm_pr).powi(6);
    score += fill_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let exact = ((pr - nxt) / cap).abs();
        if nxt <= pr {
            score -= 6.0 * (1.0 - exact) - 3.0 * exact * exact;
        } else {
            // penalize residuals that no plausible next item can use
            let unusable = (pr - nxt) / cap;
            score += 4.0 * unusable * unusable;
        }
    }

    // Penalize bins with residuals far from the mean (fragmentation), smooth term
    let dev = (pr - mean_residual) / cap;
    score += 2.5 * dev * dev;

    // Mild penalty for spreading across many bins early on
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: make it attractive only when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = norm_pr; // = 1.0 for empty bin baseline; compare via mean residual
        let avg_waste = mean_residual / cap;
        score = pr - 4.0 * (avg_waste - 0.25).max(0.0) * cap + 2.0 * progress;
        let _ = poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover matches small
    // "harmonic" sizes (mod classes) are more reusable.
    let pr = post_residual;
    let class = pr % 10; // harmonic sub-class
    let harmonic_bonus: f64 = match class {
        0 => 6.0,               // exact decade residual -> very reusable
        1..=4 => 3.0,           // small leftover, still flexible
        5 => 4.0,               // half-decade
        _ => 0.0,               // awkward leftover
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: prefer post_residual that can host
    // common item sizes via integer division count.
    let hosts = if pr > 0 { pr / 10 } else { 0 };
    score -= (hosts.min(8)) as f64 * 1.5;

    // Penalize large dead space that likely becomes unusable.
    if pr > 0 && pr < 10 {
        score += 8.0; // near-full bin: tiny dead space, but item fits perfectly -> actually good
        score -= 12.0; // net reward for tight fit
    }

    // Tight-fit reward scaled by how close item is to residual.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= tightness * 10.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // exact chain fit (harmonic pairing)
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally to mismatch
        let mismatch = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += mismatch * 0.3;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are nearly full or mean residual is small.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // reward opening new bin when existing residuals are small
        score -= pressure * 25.0;
        // penalize opening new bins early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 8.0;
        // penalize more when many bins are already open
        score += open_bins_count as f64 * 1.2;
    }

    // Mild preference for consolidating into fewer bins.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the minimum item (1..=100 interface) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // likely dead space for typical item sizes
    } else if post_residual == 0 {
        score -= 20.0; // perfect fill: strongly favored
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Prefer bins whose residual is close to the item (minimize slack).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += slack * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // or no good fit exists.
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size >= 60 {
            score -= 10.0; // large items are fine in fresh bins
        }
    }

    // Lookahead: if next item would fit the post-residual exactly, reward it.
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 5.0;
    }

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with little slack left.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / 40.0).max(0.0);
    }
    // Next item does NOT fit here: penalize proportional to how badly it misses.
    else if next_item_size > 0 && next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        score += 0.5 * miss;
    }

    // Reward small post_residual (tight fit) relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.6 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless no existing bin fits well.
    if bin_residual == bin_capacity {
        let tight_exists = next_item_size > 0 && post_residual == next_item_size;
        if !tight_exists && fitting_bins_count > 0 {
            // Compare wasted space: opening new bin wastes bin_capacity - item_size.
            let new_waste = (bin_capacity - item_size) as f64;
            let best_existing_waste = mean_residual - item_size as f64;
            if new_waste > best_existing_waste + 10.0 {
                score += 30.0;
            } else {
                score += 5.0;
            }
        }
        // Early in stream, prefer consolidating into few bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Slight penalty for very tiny dead space that is hard to reuse (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is already favored by base term.

    // Lookahead: penalize if next item could have fit better in this bin's
    // current residual than in post_residual (i.e., placing item now "wastes"
    // space the next item needed).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits after placement: reward combo packing
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else if next_item_size <= bin_residual {
            // next item fit before placement but not after: dead-space risk
            score += 4.0 + 0.08 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize creating small unusable slivers (< smallest item size ~ 10),
    // scaled by how unusable they are.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // New-bin candidate handling: an empty bin has large residual. Make it
    // attractive only when no good fit exists (this bin's fit is loose) or
    // late in the stream when consolidation matters less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when item is large (poor fit anywhere) or few open bins
        let new_bin_bonus = 20.0 * fit_quality + 3.0 * (1.0 - progress);
        score -= new_bin_bonus;
        // But discourage hoarding many open bins early
        score += 0.4 * open_bins_count as f64;
    } else {
        // Favor bins whose residual is close to the item (minimize waste ratio)
        let waste = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
        score += 5.0 * waste;
        // Slightly prefer bins below mean residual (consolidate fuller bins)
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    // Mild time-horizon coupling: early on, be conservative (avoid opening
    // extra bins); late, pack tightly regardless.
    score -= 2.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight-fit reward: small post_residual favored, amplified over stream time.
    let tightness = 1.0 - (pr / cap);
    score -= 18.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space: unusable residuals (smaller than min plausible item).
    let dead = if pr < 10.0 { 1.0 - pr / 10.0 } else { 0.0 };
    score += 25.0 * dead * dead;

    // Lookahead: reward if next item fits the post-residual, penalize if it wastes a large residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins below mean residual (keeps large residuals spread out).
    score += 0.15 * (pr - mean_residual);

    // Mild crowding penalty: discourage proliferation of open bins late in stream.
    score += 0.5 * open_bins_count as f64 * progress * 0.1;

    // New-bin candidate: neutral-ish residual (cap), penalized more early when consolidation is cheap.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    let r = post_residual;
    let m5 = (r % 5) as f64;
    let m10 = (r % 10) as f64;
    let m25 = (r % 25) as f64;

    // Reward residuals that fall on "harmonic" grid points (divisible by 10/25),
    // since future items drawn from typical streams align with these classes.
    score -= 6.0 * if r % 10 == 0 { 1.0 } else { 0.0 };
    score -= 4.0 * if r % 25 == 0 { 1.0 } else { 0.0 };
    score -= 2.0 * if r % 5 == 0 { 1.0 } else { 0.0 };
    score -= 0.3 * m5;
    score -= 0.15 * m10;

    // Perfect fit: extremely desirable.
    if r == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 stream).
    if r > 0 && r < 10 {
        score += 25.0;
    }

    // Coupling with next item via integer division thresholds.
    if next_item_size > 0 {
        if next_item_size <= r {
            // Next item fits here: strong reward, scaled by tightness of fit.
            let tight = 1.0 - (r - next_item_size) as f64 / bin_capacity as f64;
            score -= 18.0 * tight;
            // Harmonic bonus if the pair leaves a class-aligned residual.
            let r2 = r - next_item_size;
            if r2 % 10 == 0 { score -= 6.0; }
            if r2 % 25 == 0 { score -= 4.0; }
        } else {
            // Next item cannot use this residual: penalize proportionally to wasted class.
            score += 0.25 * (next_item_size - r) as f64;
            let q = (next_item_size / r.max(1)) as f64;
            score += 3.0 * q;
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly so we prefer filling open bins,
    // but allow opening when mean residual of open bins is small.
    if bin_residual == bin_capacity {
        score += 40.0;
        score -= 0.5 * mean_residual;
        // Early in the stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If the item is large and open bins are crowded, new bin is attractive.
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // Prefer tighter fits among open bins: reward small post_residual relative to item.
    score += 0.1 * (bin_residual - item_size) as f64;

    // Mild penalty for spreading across many open bins.
    score += 0.4 * open_bins_count as f64;

    // Fractional capacity alignment of the item itself.
    let frac = item_size as f64 / bin_capacity as f64;
    score -= 5.0 * (frac * 4.0).round() / 4.0 * 0.0; // placeholder no-op
    let _ = m25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals that are too small to be useful are costly.
    // Treat gaps below the smallest plausible item as near-wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: heavily reward closing the bin.
        score -= 40.0;
    } else {
        // Mild superlinear penalty on leftover space to prefer tight fits.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr / bin_capacity as f64;
    }

    // Reward fitting into bins where the leftover can hold the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover can't fit next item: penalize proportionally to wasted potential.
        score += 0.15 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so this term
    // penalizes it relative to existing bins).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        // Consolidation bias: prefer fuller bins when many bins are open.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Early in the stream, be more willing to open fresh bins (long horizon ahead);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress * (1.0 - fill_proxy(bin_residual, bin_capacity));
    }

    // Prefer bins whose residual is close to the mean (avoid stranding outliers)
    // unless the fit is exceptionally tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

#[inline]
fn fill_proxy(bin_residual: u32, bin_capacity: u32) -> f64 {
    1.0 - bin_residual as f64 / bin_capacity as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Strong reward for exact match (post_residual == next_item_size)
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Penalize waste proportional to how much larger the leftover is than the next item
            let waste = post_residual as f64 - nxt;
            if waste > 0.0 {
                score += waste * 0.8;
            } else {
                // Next item won't fit here: leftover is likely dead space
                score += (-waste) * 0.15;
            }
        }

        // Pair-fill bonus: item + next item nearly fills the bin
        let pair_fill = item_size as f64 + nxt;
        if pair_fill >= bin_capacity as f64 * 0.95 {
            score -= 25.0;
        }
    }

    // Tightness reward: smaller post_residual relative to capacity is better
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize bins whose residual is far above mean (hoarding space)
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.2;
    }

    // Late in the stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // New-bin candidate: make it unattractive unless it is the only option
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual non-linearly (dead space is quadratic bad).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Reward filling bins to near-exactness.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let mut nb = 55.0 - 45.0 * fill_frac;
        // Penalize opening bins more when many are already open and mean residual is high.
        nb += open_bins_count as f64 * 1.5;
        nb += (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += progress * 25.0;
        score += nb;
    }

    // Lookahead: if the next item would fit perfectly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover; slight penalty proportional to waste.
            score += 3.0;
        }
    }

    // Mild preference for bins with residual close to mean (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer larger residuals slightly when item is small (save big gaps for big items).
    score += (bin_residual as f64 / bin_capacity as f64) * (item_size as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual, non-linearly (squared coupling)
    let mut score = pr * pr / cap;

    // Smooth progress coupling: tighten packing as stream advances
    score += pr * (0.5 + progress) * (pr / cap);

    // Reward filling bins deeply (item large relative to residual)
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= fill_ratio * fill_ratio * cap * 0.25;

    // Last-chance bin: strong bonus to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 1.5;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += cap * (0.8 + 0.4 * progress);
    }

    // Lookahead: if next item fits in post_residual, reward leaving useful space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (pr - nxt) * (1.0 + progress);
        } else {
            // post-residual too small for next item: penalize dead space
            score += (pr - nxt).abs() * 0.1 * (1.0 + progress);
        }
    }

    // Prefer bins below mean residual (consolidate emptier bins)
    score += (pr - mean_residual) * 0.05;

    // Slight preference to fill bins with many siblings (close them out)
    score -= open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit rewards (harmonic tiers on post_residual)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Harmonic class penalty: residual mod 10 fragmentation
    let cls = (post_residual % 10) as f64;
    score += cls * 0.8;

    // Dead space: tiny unusable-feeling residuals
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward if next item fits into the resulting residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // extra reward for near-perfect two-item packing
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill = item_size as f64 / cap;
        // Prefer fresh bins for large items; penalize for small items
        score += 35.0 * (1.0 - fill);
        score += 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if item_size >= (0.6 * cap) as u32 {
            score -= 22.0;
        }
        if item_size <= (0.25 * cap) as u32 {
            score += 20.0;
        }
        if (post_residual as f64) > mean_residual {
            score += 6.0;
        }
    } else {
        // Mild bias to reuse existing bins
        score -= 6.0;
        // Penalize wasting a large residual on a small item
        if (item_size as f64) < 0.35 * bin_residual as f64 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to ever be useful (below min item size 1... use 10 as safe floor)
    let dead_floor = 10u32;
    if post_residual < dead_floor && bin_residual != bin_capacity {
        score += 40.0 + (dead_floor - post_residual) as f64 * 3.0;
    }

    // Gap unusable for the NEXT item: likely dead space
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits strongly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 25.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation (favor existing bins over new)
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize when few bins are open or mean residual is high
        score += 20.0 + open_bins_count as f64 * 2.0 - mean_residual * 0.3;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Late in the stream, avoid leaving awkward mid-size gaps
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual <= 20 {
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is an excellent chaining placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual > next_item_size {
            // Next item fits: penalize leftover after the hypothetical next placement.
            let after_next = post_residual - next_item_size;
            score -= 150.0 - (after_next as f64) * 2.0;
        } else {
            // Next item does not fit: penalize proportionally to the gap.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 1.5;
        }
    } else {
        // Last item: prefer minimal post residual, close bins out aggressively.
        score -= 100.0;
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving this bin below-average residual spreads capacity better.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.8;
    } else {
        score += (pr - mean_residual) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: make it unattractive unless the item is large and
    // no good fit exists elsewhere. Penalize opening a new bin early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 300.0;
        // Large items justify fresh bins more often, especially later in the stream.
        if item_size >= 60 {
            score -= 200.0 + 150.0 * progress;
        }
        // If the next item is small and would fit anywhere, opening a bin wastes capacity.
        if next_item_size > 0 && next_item_size <= 30 {
            score += 100.0;
        }
    }

    // Mild pressure to prefer fuller bins as the stream progresses.
    score -= (bin_residual as f64 / bin_capacity as f64) * 20.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to ever be useful.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < next_item_size as f64 {
        score += 8.0; // residual likely unusable by the next item
    }

    // Lookahead: strongly favor bins whose post-residual exactly fits the next item.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 40.0;
    }
    // Reward leaving room for the next item when it's large.
    if next_item_size > 0 && post_residual as u32 >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: using the only bin that fits avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // When many bins are open, prefer consolidating into existing bins;
    // when few are open, opening a new bin is cheaper.
    let crowding = (open_bins_count as f64).ln() + 1.0;
    score += 3.0 * crowding;

    // Global residual balance: prefer bins near the mean residual (keeps spread even).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future to exploit them); late, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress;

    // New-bin candidate: open a fresh bin when the item fits poorly everywhere
    // or when the stream is young; penalize otherwise.
    if bin_residual == bin_capacity {
        let early_bonus = 15.0 * (1.0 - progress);
        let poor_fit_penalty = if fitting_bins_count > 0 && post_residual < 20 { -20.0 } else { 0.0 };
        score += 5.0 + early_bonus + poor_fit_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward near-perfect fits: smooth quadratic decay of residual waste
    let waste = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste).powi(6) * 30.0;

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize creating small unusable residuals (dead space) non-linearly
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: prefer bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += (gap / bin_capacity as f64) * 12.0;
        if post_residual as i64 == next_item_size as i64 {
            score -= 20.0;
        }
    }

    // New-bin candidate: keep it attractive early, discourage later in the stream
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let novelty = (open_bins_count as f64).ln().max(1.0);
        score += 20.0 + 60.0 * progress * novelty;
    } else {
        // Mild preference for filling already-open bins, stronger as stream progresses
        score -= 5.0 * progress;
        // Prefer bins tighter than the mean residual (compactness pressure)
        score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 8.0;
    }

    // Smooth polynomial coupling of progress with residual pressure
    let p2 = progress * progress;
    score += p2 * (post_residual as f64 / bin_capacity as f64) * 18.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo common item-size
    // divisors (2,4,5,10,20) indicate how "reusable" the leftover space is.
    let pr = post_residual;
    let mut harmony: f64 = 0.0;

    // Perfect-fit reward: zero post residual is ideal.
    if pr == 0 {
        harmony -= 60.0;
    } else {
        // Penalize tiny unusable slivers (< 10, minimum item size).
        if pr < 10 {
            harmony += 25.0;
        }
        // Harmonic divisibility bonuses: leftover divisible by common sizes
        // is more likely to be filled by future items.
        if pr % 10 == 0 { harmony -= 8.0; }
        if pr % 20 == 0 { harmony -= 6.0; }
        if pr % 5 == 0 { harmony -= 3.0; }
        if pr % 4 == 0 { harmony -= 2.0; }
        if pr % 25 == 0 { harmony -= 4.0; }
        // Integer-division thresholds: classify leftover into usable bands.
        let band = pr / 10; // 0..=10 bands
        match band {
            0 => harmony += 15.0,           // 1..9: dead space
            1 => harmony += 4.0,            // 10..19: only tiny items
            2 => harmony -= 2.0,            // 20..29
            3 | 4 => harmony -= 5.0,        // 30..49: mid items fit
            5 | 6 => harmony -= 7.0,        // 50..69
            _ => harmony -= 9.0,            // 70..99: large items fit
        }
    }

    // Lookahead coupling: reward when next item fits the post-residual
    // (chains placements), penalize near-miss slivers.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Exact harmonic match is best.
            if next_item_size == pr {
                harmony -= 20.0;
            } else {
                let gap = pr - next_item_size;
                if gap < 10 { harmony += 8.0; } else { harmony -= 6.0; }
            }
        } else {
            // Next item cannot use leftover: mild penalty scaled by overflow.
            harmony += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Capacity fraction: fill ratio of the bin after placement.
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    harmony -= 30.0 * fill * fill; // prefer fuller bins (best-fit flavor)

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        harmony -= 18.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-poor unless residual
    // would be very large and unusable, so we only open bins when needed.
    if bin_residual == bin_capacity {
        harmony += 12.0;
        // Opening fresh is attractive only if no open bin fits well.
        if fitting_bins_count == 0 {
            harmony -= 40.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    harmony -= 10.0 * progress * (1.0 - fill);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a tight fit worth prioritizing.
    let diff = mean_residual - pr as f64;
    harmony += 0.2 * diff;

    score += harmony;
    score
}

