    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Tightness relative to mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Slight bias to fill older/more crowded bins when many are open.
    score -= 0.5 * open_bins_count as f64;

    // Prefer smaller bins' residual overall (best-fit flavor, non-linear).
    score += (post_residual as f64) * (post_residual as f64) / (2.0 * bin_capacity as f64);

    // Penalize opening a new bin mildly unless residuals are large.
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
