pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills: squash small residuals aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Tightness ratio: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste — mild penalty proportional
            // to the leftover after the lookahead placement.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
            score += 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers.
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, using it
    // avoids opening a new bin — reward heavily unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
        if post_residual <= 20 {
            score -= 20.0;
        }
    }

    // Time horizon: early in the stream, be selective (penalize loose fits);
    // late in the stream, close out bins aggressively (favor smallest residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * (1.0 - progress);
    score -= 25.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with slack -> prefer consolidating into
    // bins whose residual is below mean (tighter bins), discourage dumping
    // into already-loose bins.
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev;
    }

    // New-bin candidate: an empty bin is attractive only when the item is
    // large (would leave open bins unusable anyway) or when no open bin is
    // a decent fit. Penalize opening new bins for small items.
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 15.0;
        } else if item_size <= 30 {
            score += 25.0;
        }
        // If few bins fit the item elsewhere, a fresh bin is reasonable.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress) - 12.0 * (norm_pr * (1.0 - norm_pr) * 4.0);

    // Reward tight fits more strongly later in the stream (smooth cubic coupling)
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize leaving residuals close to but below the next item size (dead space)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 && gap < 20.0 {
            score += 8.0 * (1.0 - gap / 20.0) * (1.0 + progress);
        }
        // Reward residuals that exactly accommodate the next item
        if (gap.abs() as u32) < 1 {
