    // Last-chance bonus: smooth function of fitting bins count
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins with high mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() * 0.1;

    // New-bin candidate: make it moderately attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        score = pr + 25.0 * (1.0 - progress) - 10.0 * (fitting_bins_count as f64).recip();
    }

    score
}

