    let crowding = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 1.5 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Global mean residual coupling: bins far below mean residual are less attractive
    // (save them for larger items); bins near mean absorb the item.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in the stream, close bins aggressively (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += desperation + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr
        + 12.0 * fit_ratio * fit_ratio * cap
        - 4.0 * fit_ratio * fit_ratio * fit_ratio * cap;

    // Tight fits are valuable: reward small post_residual non-linearly
    score -= 30.0 * (1.0 - fit_ratio).powi(3) * (item_size as f64 / cap);

    // Stream progress: early on, prefer keeping bins flexible; later, prefer filling bins tightly
    let flexibility = mean_residual.max(0.0);
    score += progress * pr * 0.5;
    score -= (1.0 - progress) * flexibility * 0.3 * (1.0 - fit_ratio);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * (gap / cap);
        }
    }

    // Penalize scattering across many open bins mildly
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral baseline; only chosen if open bins score poorly
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 20.0 * (1.0 - progress) - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small leftover" classes (1..=10, 11..=20, ...) are more reusable.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold class 0..10
    score += match class {
        0 => -30.0,                       // near-perfect fit: strongly reward
        1 => -15.0,
        2 => -5.0,
        3 => 0.0,
        4 => 5.0,
        5 => 10.0,                        // half-empty bin: mediocre
        6 => 8.0,
        7 => 6.0,
        8 => 4.0,
        9 => 2.0,
        _ => 0.0,
    };

    // Exact-fill bonus (post_residual == 0 is handled above via class 0,
    // but give an extra multiplicative-style reward).
    if pr == 0 {
        score -= 40.0;
    }

    // Modulo-5 harmony: if next item's size class matches the leftover class,
    // the bin is likely reusable by the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= pr {
            // lookahead fits: reward proportional to tightness of that fit
            let lookahead_tight = (pr - nxt) as f64;
            score -= 12.0 * (1.0 - lookahead_tight / cap);
            if (pr - nxt) % 5 == 0 {
                score -= 4.0; // harmonic alignment bonus
            }
        } else {
            // lookahead cannot use this bin's leftover: mild penalty unless
            // leftover is very small anyway (bin nearly closed)
            if pr > 20 {
                score += 6.0;
            }
        }
    } else {
        // last item: minimize waste directly
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a decent (small-residual) fit.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = cap * 0.55;
        // if the current item is small relative to capacity, opening a bin is
        // more acceptable (less immediate waste)
        score -= 0.2 * (cap - item_size as f64);
        // many open bins with small mean residual -> prefer reusing them
        score += 0.1 * open_bins_count as f64;
        if mean_residual < 30.0 {
            score += 15.0;
        }
        // if lookahead item is large, a fresh bin preserves flexibility
        score -= 0.15 * next_item_size as f64;
    }

    // Slight preference for tighter bins overall (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - post_residual as f64).signum() as f64 * 0.0;
    score += 0.02 * mean_residual * 0.0; // no-op guard

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize unusable small gaps.
    // A post_residual that is too small to fit even the smallest plausible item
    // is wasted space; penalize it super-linearly.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual < 25 {
        score += 0.6 * (25.0 - post_residual as f64);
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bins pressure: discourage spreading across many bins; the more
    // open bins exist, the more we prefer placements that close gaps tightly.
    let pressure = open_bins_count as f64;
    score += pressure * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual; dead space likely.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-ish but slightly penalized so it is
    // chosen only when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Late in the stream, opening a new bin is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= 60.0 * (1.0 - match_diff / bin_capacity as f64);
        // Perfect 2-step match: residual consumed exactly by next item
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: dead space penalty
        score += 15.0 + 0.2 * next_item_size as f64;
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tight fits relative to mean residual
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // New bin candidate: open a new bin only when fits are scarce or waste is high
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        let waste = 0.4 * (bin_capacity as f64 - item_size as f64);
        score += 45.0 + waste - scarcity - 20.0 * progress;
    }

    // Penalize tiny unusable residuals (< 10 cannot fit smallest item)
    if res > 0.0 && res < 10.0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 30.0 * fit_ratio;
    } else if fit_ratio > 0.7 {
        score -= 12.0 * fit_ratio;
    }

    // Penalize large dead space relative to smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 2.0; // awkward leftover
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; leftover is dead weight for lookahead
            score += 4.0 * (post_residual as f64 / 100.0);
        }
    } else {
        // last item: maximize fill
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the item
    // fits poorly everywhere or open bins are very full on average.
    if bin_residual == bin_capacity {
        let waste_penalty = 100.0 - item_size as f64; // small item in fresh bin = waste
        let pressure = mean_residual / bin_capacity as f64; // how full open bins are
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let threshold = 0.35 + 0.3 * progress; // later in stream, more willing to open bins
        if pressure > threshold || scarcity > 0.5 || fitting_bins_count <= 1 {
            score -= 35.0 + waste_penalty * 0.2; // opening justified
        } else {
            score += 50.0 + waste_penalty * 0.5; // prefer existing bins
        }
    }

    // Mild preference to fill bins that are already below-average residual
    // (consolidate emptiness into few bins).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in stream, keep bins flexible (penalize tiny leftovers
    // that block future flexibility); late in stream, prioritize immediate fill.
    if progress < 0.3 && post_residual > 0 && post_residual < 25 {
        score += 5.0 * (1.0 - progress);
    }
    if progress > 0.7 {
        score -= 5.0 * progress * fit_ratio;
    }

    // Bin count pressure: many open bins -> favor consolidating into fewer.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, mildly damped by progress (late stream -> tighter packing)
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling of normalized post-residual with progress
    let p = progress;
    let coupling = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 + 2.0 * p);
    score += 20.0 * coupling;

    // Penalize large dead space relative to mean residual
    score += 0.3 * (pr - mean_residual) * (1.0 + p);

    // Reward near-perfect fits with smooth exponential term
    score -= 30.0 * (-norm_pr * 8.0).exp();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - p);
    }

    // Slight penalty for opening a new bin when others could fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 * (1.0 - p) + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (mod 10) are near-perfectly packed; reward them.
    let residue_class = post_residual % 10;
    let harmonic_reward = match residue_class {
        0 => 6.0,                       // perfectly divisible leftover
        1..=3 => 3.0,                   // nearly full bin, tiny dead space
        4..=6 => 0.0,
        _ => -4.0,                      // large leftover class: penalize (add)
    };
    score -= harmonic_reward;

    // Integer-division threshold on post_residual: leftover <= 10 is dead space.
    let dead_zone = post_residual / 10; // 0 => dead space, 1.. => usable
    if dead_zone == 0 && post_residual > 0 {
        score += 8.0; // punish stranding a tiny unusable gap
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            // harmonic class of the double-fit leftover
            if chain_left % 10 == 0 {
                score -= 12.0;
            }
            score -= (chain_left as f64) * 0.15;
        } else {
            // next item cannot follow here: mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bin: only bin that fits the item — keep it alive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Fraction-of-capacity reasoning: residual as fraction of capacity.
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += frac * frac * 5.0; // prefer filling fuller bins first (best-fit tilt)

    // Mean-residual coupling: bins far below mean residual are "odd ones out";
    // nudge score toward consolidating similar residuals (harmonic grouping).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Late in the stream, consolidate aggressively to avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score += (progress - 0.7) * 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (i.e. many fitting bins means reuse is better; opening wastes capacity).
    if bin_residual == bin_capacity {
        let base = 45.0 + post_residual as f64; // empty bin has post_residual = capacity
        score = base
            + (fitting_bins_count as f64) * 10.0
            - if next_item_size > 0 && next_item_size <= bin_capacity / 2 { 8.0 } else { 0.0 };
        // late stream: strongly discourage new bins
        if progress > 0.5 {
            score += progress * 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: reward heavily (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (min item size = 1, but tiny gaps < 5 are nearly
    // unusable) are penalized quadratically.
    if post_residual > 0 && post_residual < 5 {
        score += (5 - post_residual) as f64 * (5 - post_residual) as f64 * 50.0;
    }

    // Gaps that cannot fit the lookahead item are less useful; penalize mildly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward bins whose leftover can host the next item (chain-friendly).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        if post_residual > 30 {
            score += post_residual as f64 * 0.8; // still avoid wasteful last-chance use
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item leaves a large, reusable residual or few bins fit the item.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        score += open_bins_count as f64 * 2.0; // pressure: discourage too many open bins
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 25.0; // fresh bin can chain the next item
        }
        if fitting_bins_count == 1 {
            score += 80.0; // never open when a last-chance bin exists
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing ones rather than spreading residual capacity.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: when mean residual is low (bins nearly full),
    // filling this bin well is more valuable.
    score -= mean_residual * 0.3;

    // Slight late-stream tightening: waste matters more as stream nears end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent, subtract proportional to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 + slack * 0.3;
        } else {
            // Next item won't fit here: penalize dead space, worse for large leftover
            let waste = post_residual as f64;
            score += 8.0 + waste * 0.4;
        }
    }

    // Compare against mean residual of open bins: prefer bins already below-average residual
    // (filling fuller bins keeps many partially filled bins for future items)
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit (i.e., this item would leave large unusable residue everywhere).
    if bin_residual == bin_capacity {
        // Neutral-ish anchor: slightly above a good fit, below a terrible fit
        score = (bin_capacity - item_size) as f64 + 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0; // fresh bin can also host the next item
        }
        // As stream progresses, slightly discourage proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty for very fragmented bins with tiny residual that can't fit typical items
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills (small post residual).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // Tightness ratio: prefer bins that are filled proportionally more.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 60.0;

    // Non-linear penalty for leaving awkward mid-range residuals that few items fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space trap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement (sets up a chain).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 150.0;
            } else if slack <= 10 {
                score -= 50.0;
            } else {
                score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot use the leftover; penalize proportionally.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state: when many bins are open with large mean residual, prefer
    // consolidating into existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        score -= 0.3 * mean_residual.min(100.0);
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit, or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64;
        if decent_fit_exists && fitting_bins_count > 0 {
            // Penalize new bin when open bins can take the item.
            score += 150.0 + 0.5 * mean_residual;
        } else {
            // Opening a fresh bin is fine early, less so late in the stream.
            score -= 20.0 * (1.0 - progress);
        }
    }

    // Mild time-horizon effect: later in the stream, waste hurts more.
    score += progress * post_residual as f64 * 0.2;

    // Tie-breaker: prefer bins with lower residual overall (denser bins first).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress + 0.6 * norm_pr * progress);

    // Reward tight fits: subtract more when post_residual is small
    score -= (1.0 - norm_pr).powi(3) * cap * (0.35 + 0.4 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.2 + 0.8 * progress);
        } else {
            score -= (1.0 - (pr - nxt) / cap) * 3.0;
        }
    } else {
        // last item: strongly prefer minimal residual
        score -= (cap - pr) * 2.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: mildly penalize early, allow late when fits are poor
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress + 0.5 * mean_residual * (1.0 - progress);
    }

    // Slight preference to fill bins with low mean residual
    score += 0.15 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of perfect fill
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic classes: modulo arithmetic on post_residual
    let pr = post_residual;
    score -= match pr % 10 {
        0 => 40.0,          // residual aligned to decade -> reusable by common sizes
        1 | 9 => 5.0,
        2 | 8 => 2.0,
        _ => 0.0,
    };

    // Integer-division thresholds: residual large enough for next item
    if next_item_size > 0 {
        if pr >= next_item_size {
            // fraction of residual reusable by lookahead
            let reuse = next_item_size as f64 / pr as f64;
            score -= 60.0 * reuse;
            // exact pair fill
            if pr == next_item_size {
                score -= 150.0;
            }
        } else {
            // dead space relative to lookahead
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: keep it competitive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // open new bin if existing residuals are small and item is large
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - fragmentation);
        score = 100.0 - 120.0 * pressure - 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score += 20.0; // lookahead also large: prefer fresh bin less
        }
    }

    // Mild penalty for leaving residual far from mean (balance open bins)
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // Penalize any small gap that likely cannot host a future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits (best-fit style) with a non-linear bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 10.0;
        }
    }

    // Mean-residual coupling: bins far from the mean residual are mildly penalized.
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // Penalize opening new bins when existing ones fit, scaled by stream progress.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 30.0 + 40.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: exact or near-exact fill (minimize post_residual aggressively).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else {
        // Reward small residuals non-linearly (dead space is super-linearly bad).
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64).powi(3) * 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - n).abs() < 0.5 {
            score -= 400.0; // next item will close this bin perfectly
        } else if pr >= n {
            // next item still fits: reward proportionally to how well it fills
            score -= 150.0 * (n / pr);
        } else {
            // next item will NOT fit here: the residual becomes dead space
            // unless small enough to be generally useful. Penalize.
            score += 0.5 * (n - pr);
        }

        // Coupling with mean residual: prefer bins whose post-residual tracks
        // the stream's typical leftover so future items remain placeable.
        let dev = (pr - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity (few open bins would waste space)
    // or no real bin offers a decent fit. Penalize premature new bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            // there exist open bins that fit: make new bin unattractive unless
            // all fits are poor (post_residual large in those cases is already
            // penalized above, so a moderate penalty suffices)
            score += 80.0;
            // but if item is huge and would leave a big residual anyway,
            // a fresh bin may be fine: soften penalty
            if fill_ratio > 0.7 {
                score -= 60.0;
            }
        } else {
            // no open bin fits: new bin is the only option
            score -= 500.0;
        }
        // Slight preference for opening bins early in the stream (builds a pool)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Congestion control: many open bins with high mean residual -> consolidate
    // into existing bins rather than spreading.
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: bonus if the post residual can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportionally to wasted gap
            let gap = post_residual as f64;
            score += 6.0 * (gap / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits terribly in all open bins or the stream is early with few bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (item_size as f64) > mean_residual;
        let mut penalty = 18.0;
        if poor_fit { penalty -= 14.0; }
        if progress < 0.15 && open_bins_count < 3 { penalty -= 8.0; }
        // if item leaves large residual in a fresh bin vs small residual elsewhere, discourage
        penalty += 10.0 * (post_residual as f64 / bin_capacity as f64);
        score += penalty;
    } else {
        // Mild penalty for very fragmented bins (small residual left after placement)
        if post_residual < 10 && post_residual > 0 {
            score += 5.0; // tiny slivers are near-dead space anyway, slight penalty
        }
        // Favor bins whose residual deviates below the mean (consolidating fuller bins)
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Late-stream consolidation: prefer reusing bins as the stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && !is_new_bin {
        score -= 8.0 * progress;
    }

    // Penalize many open bins mildly when reusing (bin-count minimization pressure)
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Smooth polynomial coupling with stream progress: early on, tolerate slack;
    // late in the stream, punish residual waste more aggressively.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score += 20.0 * norm_post * norm_post * progress_coupling;

    // Reward near-perfect fills smoothly (post_residual close to 0)
    score -= 15.0 * (1.0 - norm_post).powi(4) * (1.0 - progress);

    // Lookahead: smooth interaction between leftover space and next item size.
    // If next item fits exactly in the post residual, reward; if post is too
    // small for the next item but nonzero, penalize mildly (dead space).
    if next_item_size > 0 {
        let gap = norm_post - norm_next;
        let fit_quality = (-gap * gap / 0.05).exp(); // peaks when gap == 0
        score -= 10.0 * fit_quality * (1.0 + progress);
        score += 8.0 * (norm_post.max(0.0) * (1.0 - norm_next)).powi(2);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_item);
    }

    // Mean-residual awareness: placing into a bin with residual above mean
    // reduces fragmentation; smooth coupling with open bin count.
    let mean_norm = mean_residual / cap;
    score += 5.0 * (norm_post - mean_norm) * (1.0 - (-open_bins_count as f64 / 10.0).exp());

    // New-bin candidate: neutral baseline slightly above good fits,
    // but becomes attractive when existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 30.0 * norm_item * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity fractions (1/4, 1/2, 3/4) via integer division thresholds.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;
    let class = post_residual / quarter; // 0..=4 harmonic class

    // Dead-space penalty: residuals in the smallest class (0..quarter)
    // are nearly unusable given item sizes; penalize them.
    if class == 0 && post_residual > 0 {
        score += 8.0;
    }
    // Sweet-spot reward: residual that exactly matches common item sizes
    // (multiples of 10) is a perfect fill.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward;
    // if next item is bigger than post residual but small enough to fit
    // elsewhere, mild penalty for wasting this bin on a mismatch.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
        // Harmonic pairing: next item leaves a multiple-of-10 residual too
        if next_item_size <= post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless residual is tiny).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
        if class == 0 {
            score += 6.0; // but not if it creates dead space
        }
    }

    // New-bin candidate: residual == capacity. Prefer it only when no open
    // bin is a decent fit (post_residual would be large/dead).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // open a new bin if the stream is early or many bins are open and
        // mean residual is low (fragmented state)
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < quarter as f64 && open_bins_count > 2 {
            score -= 12.0;
        }
        if progress < 0.15 {
            score -= 4.0;
        }
        // don't open a new bin if the item is small (could fit anywhere)
        if item_size <= quarter {
            score += 15.0;
        }
    }

    // Modulo arithmetic on item size: items near multiples of half-capacity
    // pair well with complementary fills; slight reward for tight fits.
    let tightness = (bin_residual - item_size.min(bin_residual)) as f64;
    if tightness as u32 <= quarter {
        score -= 2.0;
    }

    // Mean-residual drift: penalize bins far below mean (avoid hoarding
    // space in nearly-empty bins when others are fragmented).
    score += ((mean_residual - post_residual as f64).abs()) * 0.05;

    // Integer division threshold on step: late in the stream, be greedier
    // (minimize residual harder) since fewer chances to fix fragmentation.
    if step_index * 2 >= total_items {
        score += post_residual as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space): residual 1..=10 is waste.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Prefer bins with below-average residual (tighter bins get priority).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 15.0;
    }
    // Penalize if post-residual is too small for the lookahead item (dead space for future).
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Early in stream, be slightly more conservative about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward exact / tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: strongly reward bins whose post_residual can hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: reward proportional to how snugly the next item also fits.
            let chain_slack = post_residual - next_item_size;
            score -= 40.0 * (1.0 - (chain_slack as f64) / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize leftover dead space, mildly.
            let gap = next_item_size - post_residual;
            score += 0.15 * (gap as f64).min(50.0);
        }
    }

    // Compare residual against the mean residual of open bins:
    // prefer placing into bins with more residual than average (balance load),
    // unless the fit is tight.
    if post_residual as f64 > mean_residual {
        score += 0.10 * ((post_residual as f64) - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Default penalty so open bins win unless they are bad.
        score += 20.0;
        // But if the item is large relative to capacity and open bins are fragmented,
        // opening fresh can be better.
        let frag = if open_bins_count > 0 { (mean_residual / open_bins_count as f64) } else { 0.0 };
        if (item_size as f64) > 0.5 * (bin_capacity as f64) && frag < (item_size as f64) {
            score -= 35.0;
        }
        // Chain potential in a fresh bin: item + next item fit perfectly.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let slack = bin_capacity - item_size - next_item_size;
            score -= 30.0 * (1.0 - (slack as f64) / (bin_capacity as f64));
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Mild penalty for wasting space in bins that could still serve mid-size items.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly-perfect fill is excellent
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Exact fill gets a huge reward.
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 20 {
        score -= 25.0;
    }

    // Penalize residuals that no realistic item can use (dead space).
    // Smallest item is 1, so only zero residual is truly dead, but small
    // residuals (< 15) are hard to fill: penalize moderately.
    if post_residual >= 1 && post_residual < 15 {
        score += 18.0 * (15.0 - post_residual as f64) / 15.0;
    }

    // Lookahead: if the next item fits perfectly into the post-residual,
    // strongly favor this bin (chained pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            let chain_leftover = post_residual - next_item_size;
            if chain_leftover < 15 {
                score -= 35.0;
            }
        } else if next_item_size <= bin_residual && post_residual > 0 {
            // Next item can't use this bin's leftover; mild penalty if
            // leftover is awkwardly small.
            if post_residual < 25 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Global state: many open bins with large mean residual -> prefer
    // consolidating into existing bins (avoid fragmentation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fragmentation = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= fragmentation * 30.0 * (0.5 + 0.5 * progress);
    }

    // Early in the stream, be more willing to open new bins (better future
    // packing structure); late in the stream, fill existing bins tightly.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline competitive score.
        score = (bin_capacity - item_size) as f64;
        // Early stream: new bins are cheap.
        score -= 40.0 * (1.0 - progress);
        // If nothing fits well anywhere (mean residual very low), opening
        // a new bin is attractive.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // If many bins are open and fragmented, avoid adding more.
        score += (open_bins_count as f64).ln().max(0.0) * 12.0;
        // If next item is large and this item is small, a fresh bin may
        // serve the next item better.
        if next_item_size > item_size && next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Slight preference for bins that are already partially filled
    // (reduces number of active bins long-term).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 12.0 * prog_term * (pr_norm * pr_norm);

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 20.0 * progress * tightness * tightness;

    // Penalize residual that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 6.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        let waste = pr - next_item_size as f64;
        score += 0.05 * waste * waste / cap;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer it only when open bins are quite full on average
    if bin_residual == bin_capacity {
        let mean_full = 1.0 - (mean_residual / cap);
        score += 25.0 * (1.0 - mean_full * mean_full) + 5.0 * open_bins_count as f64 / (open_bins_count as f64 + 3.0);
    } else {
        // Mild penalty for very small leftovers (dead space)
        score += 3.0 * (1.0 - pr_norm) * pr_norm * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small "dead" residues are penalized
    // more than proportionally since they waste capacity.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10; // harmonic decile class
        score += (10 - class) as f64 * 0.8; // waste-weighting within class
        if pr < 10 {
            score += 25.0; // nearly-full bin: excellent, but tiny residue is fine -> actually reward
            score -= 40.0;
        }
        // Integer-division thresholds: residues that can host common sizes
        for &s in &[10u32, 20, 25, 30, 40, 50] {
            if pr >= s && pr < s + 10 {
                score -= 3.0; // residue is "usable" by a future small item
            }
        }
    } else {
        score -= 30.0; // perfect fill
    }

    // Lookahead pairing: if next item fits exactly, strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving a residue that is
            // just below next_item_size (near-miss dead space)
            if pr > 0 && pr < next_item_size {
                score += (next_item_size - pr) as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: neutral baseline; prefer reusing open bins
    // unless they are very empty (fragmenting capacity).
    if bin_residual == bin_capacity {
        // fresh bin: score = capacity, adjusted by stream position and load
        score = bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        if mean_residual > 40.0 && open_bins_count > 2 {
            score -= 15.0; // many half-empty bins: better to open fresh one? no -> keep reuse
            score += 30.0;
        }
        // opening a new bin is bad if the item would leave small residue anyway
        score += post_residual as f64 * 0.5;
    } else {
        // favor filling fuller bins more aggressively as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 15.0 * fullness * (0.5 + progress);
    }

    // Mild penalty tied to number of fitting bins: prefer tightest competition
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it is
    // already well used; reward it.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized; large residual waste is also penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // Dead space: gap too small for any item (min size 1..100, but tiny gaps
        // are nearly unusable) -> strong penalty.
        score += (10.0 - pr) * 6.0;
    } else if pr == 0.0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Reward tight fits relative to the item (small waste ratio).
    let waste_ratio = pr as f64 / (bin_residual.max(1) as f64);
    score += waste_ratio * 25.0;

    // Lookahead coupling: if the next item can fit into the post residual,
    // reward this placement (keeps chains going).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && pr > 0.0 {
        // Leftover can't host next item: mild penalty.
        score += 8.0;
    }

    // Open-bin pressure: penalize adding load to existing bins slightly,
    // so a fresh bin can be preferred when open bins are numerous and fits are poor.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): neutral base; add a mild opening cost so it
    // only wins when existing fits are truly bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if many bins are open and mean residual is high, opening fresh
        // bins keeps capacity spread; slight discount.
        if open_bins_count > 3 && mean_residual > 30.0 {
            score -= 10.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (pr / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.8;
    }
    // Penalize post_residual that cannot fit the next item (dead space risk)
    if next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        score += deficit * 0.5;
    }

    // Tight fit reward: small post_residual relative to mean residual
    let tightness = post_residual as f64 / (mean_residual + 1.0).max(1.0);
    score -= (1.0 - tightness).max(0.0) * 10.0;

    // Penalize bins with much larger residual than the mean (fragmentation hoarders)
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: only bin that fits this item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in stream: prefer filling existing bins, avoid opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 15.0 + progress * 30.0;
    } else if open_bins_count > 1 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 30.0 * (1.0 - tightness).powf(2.0);
    }

    // Penalize large dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fill bonus
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward residual zone
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 8.0; // kills the bin before the next item
        }
    }

    // Time horizon: early in the stream, prefer opening fresh bins (exploration);
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize late, penalize less early.
        score += 18.0 * progress - 10.0 * (1.0 - progress);
        // If many bins are open, discourage adding more.
        score += 2.0 * open_bins_count as f64;
    } else {
        score -= 10.0 * progress;
    }

    // Global residual coupling: if this bin's residual is far below mean,
    // it is a "small" bin; filling it up balances the pool.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Prefer bins with less residual when many fit (best-fit pressure).
    score += 0.05 * (fitting_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Quadratic penalty on waste, amplified by stream progress
    let waste = pr / cap;
    score += 12.0 * waste * waste * (0.5 + progress);

    // Reward tight fits (small post_residual) with non-linear bonus
    score -= 8.0 * (1.0 - waste).powi(3);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - waste);
    }

    // Lookahead coupling: prefer leaving residuals that fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack_fit = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack_fit * slack_fit);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate: penalize opening a bin unless waste elsewhere is high
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 10.0 + 5.0 * (mean_residual / cap) - 2.0 * progress * open.min(20.0) * 0.5;
    } else {
        // Prefer bins with residual close to item size (best-fit flavor, smoothed)
        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 5.0 * fit_gap * fit_gap;
    }

    // Mild preference for filling bins below mean residual (balancing)
    score -= 2.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small leftover space.
    let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tight * tight;

    // Harmonic class of post_residual: dead space classes (mod 10) are penalized
    // since items are >= 10 typically; small unusable slivers are worse.
    let dead_class = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // completely dead sliver
    } else if dead_class <= 2 {
        score -= 4.0; // near-perfect fill class
    } else if dead_class >= 8 {
        score += 3.0; // awkward class
    }

    // Usable-space shaping via integer division thresholds.
    let usable_quotient = post_residual / 10;
    score -= 1.5 * (usable_quotient as f64).min(6.0);

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic compatibility: exact or near match classes.
            let diff = post_residual - next_item_size;
            if diff == 0 {
                score -= 20.0;
            } else if diff < 10 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to overshoot class.
            let over = (next_item_size - post_residual) / 10;
            score += 2.0 + 1.5 * over as f64;
        }
    } else {
        // Last item: fill as much as possible.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins
    // are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = bin_capacity as f64 - 8.0 + crowding.min(10.0);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    } else {
        // Prefer denser bins (less residual before placement).
        score += 0.05 * bin_residual as f64;
        // Early stream: be slightly greedy on opening; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress * tight;
    }

    // Mean-residual coupling: if this bin is below mean residual, it's a good filler.
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Strict dead-space avoidance ----
    // A post_residual gap is "dead" if it cannot hold the lookahead item
    // (or nothing at all when next_item_size == 0). Penalize such gaps hard.
    let usable_next = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual < usable_next {
        // Dead space: gap wasted at least until later items. Penalize strongly,
        // scaled by how close it is to being usable (near-misses hurt most).
        let dead_severity = (usable_next - post_residual) as f64;
        score += 8.0 + dead_severity * 0.5;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect provision for the lookahead item: reward.
        score -= 6.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 4.0;

    // ---- Open-bins pressure ----
    // Keeping the count of open bins low is valuable; mild additive pressure
    // so that among decent fits, fuller bins are preferred, and the new-bin
    // candidate (residual == capacity, post_residual large) is naturally bad.
    score += open_bins_count as f64 * 0.15;

    // ---- Last-chance bin bonus ----
    // If this is the only bin that fits the item, using it avoids opening
    // a fresh bin; reward strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // ---- New-bin candidate calibration ----
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable only if existing residuals are large
        // (poor fits elsewhere) or the item is huge relative to mean residual.
        let mean_fit_quality = mean_residual / bin_capacity as f64;
        // If mean residual is small (bins are mostly full), opening a new bin
        // is fine -> discount its score. If mean residual is large, penalize.
        score -= (1.0 - mean_fit_quality) * 12.0;
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 5.0;
        // A very large item justifies a fresh bin.
        score -= (item_size as f64 / bin_capacity as f64) * 6.0;
    }

    // ---- Mean-residual coupling ----
    // Placing into a bin whose residual is far below the mean residual
    // (i.e., a relatively full bin) is good: it consolidates fragmentation.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.05;
    } else {
        score += (-dev) * 0.03;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: heavy reward for leaving exactly zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is a chain fit -> strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits in leftover: mild bonus proportional to tightness.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 * tightness;
        } else {
            // Next item will NOT fit in the leftover: penalize dead space creation,
            // worse when post_residual is small (unusable sliver).
            let sliver = post_residual as f64 / bin_capacity as f64;
            if sliver < 0.1 {
                score += 200.0 * (1.0 - sliver * 10.0);
            } else {
                score += 30.0;
            }
        }
    } else {
        // Last item: prefer zero-waste placements strongly.
        score -= 400.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving a residual below mean suggests better packing balance.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.5 * mean_gap;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin by default.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if the item is large and lookahead is empty, a fresh bin is fine.
        if item_size > 50 && next_item_size == 0 {
            score -= 100.0;
        }
    }

    // Progression-aware slack: early in the stream, keep bins tight;
    // late in the stream, slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 && (next_item_size == 0 || post_residual < 10) {
        score += 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item fits this bin anyway; slight penalty for consuming space now
        score += 8.0;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Many fitting bins: mildly penalize wasting space in a crowded field
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate logic: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open new bin when mean residual is high (open bins are full-ish)
        score -= 0.6 * mean_residual;
        // cheaper when many bins open (fragmented state, consolidate by opening fresh)
        score -= 2.0 * open_bins_count as f64;
        // early in stream, opening bins is fine; late in stream avoid it
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // if next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates below mean (consolidate emptier bins? no —
    // fill fuller bins first): penalize bins with residual above mean
    if mean_residual > 0.0 {
        score += 0.3 * ((bin_residual as f64 - mean_residual).max(0.0));
    }

    // Small-item arrival: keep large residuals intact
    if item_size <= 20 && bin_residual > 50 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + t) - 0.5 * norm_pr * t * (1.0 - t);
    score += 12.0 * poly;
    // Reward tight fits more strongly as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 8.0 * tight * tight * (0.5 + 0.5 * t);
    // Penalize creating dead space that next item cannot use
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 6.0 * (1.0 - norm_pr) * (0.5 + t);
    } else if next_item_size > 0 {
        let slack = norm_pr - (next_item_size as f64 / cap);
        score -= 4.0 * slack.max(0.0) * (1.0 - t);
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }
    // Prefer reusing bins when many are open
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr;
    // Mild alignment with mean residual state
    score -= 0.5 * (mean_residual - pr).abs() / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "useful"
    // residue classes (divisible by common small item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Residue class via integer division: leftover in [0,10) is dead space.
        let dead = pr % 10;
        score += dead as f64 * 1.5;

        // Harmonic reward: leftover divisible by 20/25/50 can host typical items.
        if pr % 50 == 0 { score -= 6.0; }
        else if pr % 25 == 0 { score -= 4.0; }
        else if pr % 20 == 0 { score -= 3.0; }

        // Class of the leftover bucket: quarter / half capacity fractions.
        let quarter = bin_capacity / 4;
        let half = bin_capacity / 2;
        if pr <= quarter { score += 4.0; }           // tiny leftover: nearly perfect fit
        else if pr <= half { score -= 2.0; }         // half-full leftover is reusable
    } else {
        score -= 12.0; // perfect closure
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the waste is egregious.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin when the stream is early
    // and open bins exist; encourage it late when consolidation is done.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * progress;
        if fitting_bins_count == 0 { score -= 20.0; }
    }

    // Tight-fit bonus: item fills most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 6.0;

    // Mean-residual coupling: prefer bins below mean residual (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Integer-division threshold on item class: large items (>= 3/4 capacity)
    // should go into emptiest bins to avoid fragmenting.
    if item_size >= (3 * bin_capacity) / 4 {
        score += bin_residual as f64 * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are essentially wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post) * 5.0;
    }

    // Penalize "awkward" gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Best-fit flavor: tighter fit preferred (post residual already in base,
    // add mild curvature to emphasize small residuals).
    score += (post / cap) * 8.0;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, keep best-fit ordering via post residual
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading across too many bins,
    // but also allow new-bin escape when all fits are poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // New-bin candidate: make it attractive only when the item fits badly
    // everywhere (large post residual in existing bins) or when the
    // lookahead item would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        let fresh_bonus = 55.0
            + (post / cap) * 20.0
            + if next_item_size > 0 && next_item_size >= item_size { 8.0 } else { 0.0 };
        score -= fresh_bonus.min(70.0);
        // But penalize opening bins when a good fit already exists.
        if post_residual == 0 {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits into post_residual with small slack.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 500.0 / (1.0 + slack);
    }
    // Next item cannot fit in the leftover: penalize proportionally to wasted space.
    else if next_item_size > post_residual {
        let overflow = (next_item_size - post_residual) as f64;
        score += overflow * 0.5;
    }

    // Bonus when this bin is the only fitting option (last-chance placement).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer bins whose residual is below the mean (tighter packing candidates).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference to use existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 + 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving dead space smaller than the minimum plausible item (1..=small),
    // but with unknown distribution penalize residuals below a soft threshold.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item could exactly fill the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits here later; mild reward proportional to leftover-after-next.
            let after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover; penalize proportionally to waste.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate (empty bin): only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred for decent fits.
        score += 70.0;
        // If this bin is the only fitting option, opening new is fine.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
        // If mean residual across open bins is large, opening new is wasteful.
        score += 0.3 * mean_residual;
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If item is large relative to capacity, new bin is reasonable.
        score -= 0.2 * item_size as f64;
    }

    // Mild preference for fuller bins among open bins (best-fit bias).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    // Slight penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: residual mass vs stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 20.0 * poly;

    // Reward tight fits more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if post_residual can't fit next item but another residual could
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (pr - nx) / cap;
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balanced fills)
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Deter opening new bins late in the stream when fitting bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 12.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse buckets.
    // Small leftovers (perfect fits) are highly desirable -> strong discount.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else if pr <= 5 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 30.0;
    } else if pr <= 20 {
        score -= 12.0;
    } else if pr <= 30 {
        score -= 4.0;
    }

    // Modulo-style dead-zone penalty: residuals in "awkward" bands
    // (just above common item sizes) tend to become dead space.
    let awkward = (pr > 0 && pr < 10) || (pr > 20 && pr < 30) || (pr > 40 && pr < 50) || (pr > 60 && pr < 70) || (pr > 80 && pr < 90);
    if awkward {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr && pr - next_item_size <= 10 {
            score -= 25.0;
        } else if next_item_size > pr {
            // next item won't fit here anyway; slight penalty for hoarding space
            score += 5.0;
        }
        // If next item is small and post_residual is large, keep big residual bins flexible
        if next_item_size <= pr / 2 && pr >= 40 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists among open bins (i.e., all fits leave big waste).
    if bin_residual == bin_capacity {
        // Baseline: new bin has full residual; make it lose unless open bins are poor.
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        // Early in stream, prefer opening bins to keep flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 10.0;
        }
        // Many open bins with large mean residual: reuse instead of opening.
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 20.0;
        }
    }

    // Prefer tighter bins generally (waste-averse scaling).
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    // Mild preference for bins with residuals close to the mean (balance load).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A residual that is too small to hold even the minimum item (1) is fine,
    // but residuals in the awkward small range (1..=10) are "dead space":
    // they can rarely be filled later. Penalize quadratically.
    let dead_threshold: f64 = 10.0;
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += 30.0 + (dead_threshold - post_residual as f64).powi(2) * 2.0;
    }

    // Perfect fit reward: subtract to strongly favor exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: leaving a residual that could fit the next item
    // (lookahead k=2) makes this placement more valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual exists but cannot fit the next item: mild penalty,
        // stronger if the residual is in the dead zone.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, encourage consolidating
    // items into existing bins (favoring this bin) to reduce fragmentation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score -= pressure * (0.5 + progress);

    // Mean-residual coupling: if this bin's post_residual is well below the
    // mean residual across open bins, we are compacting efficiently.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64).min(20.0) * 0.8;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when no open bin fits well,
    // i.e., when fitting_bins_count is small and existing residuals are poor.
    if bin_residual == bin_capacity {
        // Base hesitation: opening new bins costs unless necessary.
        score += 18.0 + (open_bins_count as f64) * 2.5;
        // But if the item fits nowhere else, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream with many open bins, prefer consolidation.
        if progress > 0.7 && open_bins_count > 5 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base reward for tight fits
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    if next_item_size > 0 {
        // 2-step lookahead: reward when post_residual exactly accommodates next item
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain: post_residual == next_item_size is ideal
            score -= 40.0 / (1.0 + gap * 0.15);
            // Extra bonus if next item nearly fills bin after chaining
            let chained_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if chained_fill <= 1.0 {
                score -= 25.0 * chained_fill;
            }
        } else {
            // Next item won't fit here: penalize dead space relative to next size
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    } else {
        // Last item: purely minimize post_residual
        score += 0.2 * post_residual as f64;
    }

    // Compare against mean residual: bins with residual far above mean are wasteful targets
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Late in the stream, be more conservative: favor closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: prefer opening a new bin unless existing bin is a very good fit
    if bin_residual == bin_capacity {
        score += 55.0;
    }

    // Mild preference for fewer open bins (consolidation)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves slack: mild reward proportional to reuse
            score -= 10.0 * (1.0 - ((post_residual - next_item_size) as f64) / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize small dead space a bit
            score += 8.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline penalty so open bins win unless they are really bad fits.
        score += 25.0;
        // If many bins fit, opening a new bin is rarely worth it.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).sqrt();
        }
        // Late in the stream, prefer consolidating into open bins.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * t;
        // If mean residual across open bins is large, they can absorb the item.
        if mean_residual > item_size as f64 {
            score += 12.0;
        }
        // Large items start fresh bins more readily (hard to pack later).
        if item_size > 60 {
            score -= 18.0;
        }
    } else {
        // Reward using bins with larger residual (drain the fullest-fit bins first
        // relative to what they can hold): classic best-fit flavor.
        score -= (bin_residual as f64 - item_size as f64).max(0.0) * 0.15;
    }

    // Small global pressure: with many open bins, encourage filling existing ones.
    score += (open_bins_count as f64) * 0.5;

    // Slight preference for bins whose residual is close to item size (tightness).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling: residual value decays non-linearly with progress
    let decay = 1.0 + progress * progress;
    score *= decay;

    // Penalize large leftover space that could be dead space, reward tight fits
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small post-residual that matches next item lookahead
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = 25.0 * (-gap / 30.0) * (-gap / 30.0).exp() * (0.5 + 0.5 * progress);
        score -= match_bonus;
    }

    // Last-chance bin pressure: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 25.0 * progress;
    }

    // Crowding: many open bins -> prefer consolidating into existing space
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += 2.0 * crowding * norm_pr * (1.0 - progress);

    // Mean residual alignment: prefer bins near the mean residual (balanced packing)
    let dev = (pr - mean_residual).abs() / cap.max(1.0);
    score += 10.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin when progress is high or mean residual is large
    if bin_residual == bin_capacity {
        score += 55.0 * (0.5 + 0.5 * progress) + 0.4 * mean_residual;
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: penalize post_residuals that are unlikely to be
    // reusable given typical item sizes (1..100). Small leftovers (<10)
    // are dead space; large leftovers are fine.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Modulo arithmetic: leftover congruent to common item sizes is good.
    let m = post_residual % 20;
    if m == 0 {
        score -= 8.0;
    } else if m <= 10 {
        score -= 4.0;
    } else {
        score += 5.0;
    }

    // Penalize opening a new bin when open bins can fit.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        score += 40.0;
        // But if this bin is the only fitting one, new bin is a real option.
        if fitting_bins_count == 1 && post_residual >= next_item_size as u32 && next_item_size > 0 {
            score -= 55.0;
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Reward using a bin whose leftover can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 6.0;
        }
        // Last-chance bin: strongly favor it to avoid a wasted bin.
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
    }

    // Mild pressure toward consolidating residual mass.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold: u32 = 9;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += (dead_threshold - post_residual + 1) as f64 * 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual.max(1) as f64);
        score -= tightness * item_size as f64 * 0.8;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 90.0;
    }
    // Penalize if next item cannot fit into post residual but could have fit residual.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure from open bins.
        score += 30.0 + (open_bins_count as f64) * 4.0;
        // If only one fitting bin exists, opening a new bin is bad.
        if fitting_bins_count <= 1 {
            score += 80.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    } else {
        // Using existing bins reduces open-bin pressure slightly.
        score -= (open_bins_count as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean (compact them).
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 + 0.5 * slack;
            // Perfect 2-item packing: post_residual exactly matches next item
            if post_residual == next_item_size {
                score -= 700.0;
            }
        } else {
            // Next item cannot follow: penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Relative-to-mean coupling: bins with residuals below mean are precious;
    // prefer filling them (low residual bins get reward for being filled)
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.6 * (mean_residual - residual_f);
    } else {
        score += 0.3 * (residual_f - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening new bins when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 + 200.0 * (1.0 - progress) - 0.4 * open_bins_count as f64;
        // If item fits poorly in any open bin (large item, no fit), new bin is fine
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Mild preference to keep tight items in tight bins: high fill ratio reward
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 50.0 * fill_ratio * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}
